import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { migrateHermesToAro, MIGRATION_MARKER_FILE } from './aro-migration'

describe('aro-migration (ADR 0006 / P11.6)', () => {
  let tempRoot: string

  beforeEach(() => {
    tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'aro-mig-test-'))
  })

  afterEach(() => {
    try {
      fs.rmSync(tempRoot, { recursive: true, force: true })
    } catch {
      // Ignore cleanup error
    }

    vi.restoreAllMocks()
  })

  it('migrates configuration, credentials, and state cleanly to target', () => {
    const src = path.join(tempRoot, '.hermes')
    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'model: test-model\n', 'utf8')
    fs.writeFileSync(path.join(src, '.env'), 'API_KEY=secret-token\n', 'utf8')
    fs.writeFileSync(path.join(src, 'hermes.db'), 'mock-sqlite-bytes', 'utf8')

    const sessDir = path.join(src, 'sessions')
    fs.mkdirSync(sessDir, { recursive: true })
    fs.writeFileSync(path.join(sessDir, 'session-1.json'), '{"id": 1}', 'utf8')

    const tgt = path.join(tempRoot, '.aro')

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })

    expect(result.status).toBe('success')
    expect(result.copied).toContain('config.yaml')
    expect(result.copied).toContain('.env')
    expect(result.copied).toContain('hermes.db')
    expect(result.copied).toContain('sessions')

    // Verify target contents
    expect(fs.readFileSync(path.join(tgt, 'config.yaml'), 'utf8')).toBe('model: test-model\n')
    expect(fs.readFileSync(path.join(tgt, '.env'), 'utf8')).toBe('API_KEY=secret-token\n')
    expect(fs.readFileSync(path.join(tgt, 'hermes.db'), 'utf8')).toBe('mock-sqlite-bytes')
    expect(fs.readFileSync(path.join(tgt, 'sessions', 'session-1.json'), 'utf8')).toBe('{"id": 1}')
    expect(fs.existsSync(path.join(tgt, MIGRATION_MARKER_FILE))).toBe(true)
  })

  it('is strictly non-destructive and leaves source files intact', () => {
    const src = path.join(tempRoot, '.hermes')
    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'important: user-config\n', 'utf8')
    fs.writeFileSync(path.join(src, '.env'), 'KEY=keep-alive\n', 'utf8')

    const tgt = path.join(tempRoot, '.aro')

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(result.status).toBe('success')

    // Source MUST still exist with identical content
    expect(fs.existsSync(src)).toBe(true)
    expect(fs.readFileSync(path.join(src, 'config.yaml'), 'utf8')).toBe('important: user-config\n')
    expect(fs.readFileSync(path.join(src, '.env'), 'utf8')).toBe('KEY=keep-alive\n')
  })

  it('is idempotent and preserves existing data in .aro on subsequent runs', () => {
    const src = path.join(tempRoot, '.hermes')
    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'model: old\n', 'utf8')

    const tgt = path.join(tempRoot, '.aro')

    const res1 = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(res1.status).toBe('success')

    // User updates config in .aro
    fs.writeFileSync(path.join(tgt, 'config.yaml'), 'model: updated-in-aro\n', 'utf8')

    // Second run
    const res2 = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(res2.status).toBe('already_migrated')
    expect(res2.copied).toEqual([])

    // Content in .aro remains the user's updated config
    expect(fs.readFileSync(path.join(tgt, 'config.yaml'), 'utf8')).toBe('model: updated-in-aro\n')
  })

  it('handles missing source directory cleanly without errors', () => {
    const src = path.join(tempRoot, 'non-existent-hermes')
    const tgt = path.join(tempRoot, '.aro')

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(result.status).toBe('no_source')
    expect(fs.existsSync(tgt)).toBe(false)
  })

  it('handles paths with spaces safely', () => {
    const spaceDir = path.join(tempRoot, 'User Path With Spaces')
    const src = path.join(spaceDir, '.hermes')
    const tgt = path.join(spaceDir, '.aro')

    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'spaces: valid\n', 'utf8')

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(result.status).toBe('success')
    expect(fs.readFileSync(path.join(tgt, 'config.yaml'), 'utf8')).toBe('spaces: valid\n')
  })

  it('handles paths with non-ASCII and international Unicode characters safely', () => {
    const unicodeDir = path.join(tempRoot, 'José_Müller_测试_Аро')
    const src = path.join(unicodeDir, '.hermes_данные')
    const tgt = path.join(unicodeDir, '.aro_данные')

    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'unicode: valid\n', 'utf8')

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(result.status).toBe('success')
    expect(fs.readFileSync(path.join(tgt, 'config.yaml'), 'utf8')).toBe('unicode: valid\n')
  })

  it('handles read-only target paths gracefully with permission_denied', () => {
    const src = path.join(tempRoot, '.hermes')
    fs.mkdirSync(src, { recursive: true })
    fs.writeFileSync(path.join(src, 'config.yaml'), 'test: 1\n', 'utf8')

    const tgt = path.join(tempRoot, 'read_only_target', '.aro')

    // Mock mkdirSync throwing EACCES / EPERM
    const originalMkdirSync = fs.mkdirSync
    vi.spyOn(fs, 'mkdirSync').mockImplementation((targetPath, options) => {
      if (String(targetPath).includes('read_only_target')) {
        const error = new Error('EACCES: permission denied')

        ;(error as any).code = 'EACCES'
        throw error
      }

      return originalMkdirSync(targetPath, options)
    })

    const result = migrateHermesToAro({ sourceDir: src, targetDir: tgt })
    expect(result.status).toBe('permission_denied')
    expect(result.error).toContain('permission denied')
  })
})

/**
 * aro-migration.ts — Desktop implementation of non-destructive data directory migration.
 *
 * Implements ADR 0006 (Decision D-6):
 * - Copy-migrates config.yaml, .env, and state from source Hermes directory to target Aro directory.
 * - Idempotent (governed by .aro_migrated marker).
 * - Strictly non-destructive (source is never moved or deleted).
 * - Safe against read-only paths, spaces, and non-ASCII paths.
 */

import fs from 'node:fs'
import path from 'node:path'

export interface AroMigrationResult {
  status: 'success' | 'already_migrated' | 'no_source' | 'permission_denied' | 'error'
  source: string
  target: string
  copied: string[]
  error?: string
}

export const MIGRATION_MARKER_FILE = '.aro_migrated'

const MIGRATION_FILES = ['config.yaml', '.env', 'active_profile', 'hermes.db', 'state.db']
const MIGRATION_DIRS = ['sessions', 'memories', 'skills', 'cron', 'profiles']

export function migrateHermesToAro(options: {
  sourceDir: string
  targetDir: string
}): AroMigrationResult {
  const { sourceDir, targetDir } = options

  const result: AroMigrationResult = {
    status: 'success',
    source: sourceDir,
    target: targetDir,
    copied: []
  }

  const markerPath = path.join(targetDir, MIGRATION_MARKER_FILE)

  if (fs.existsSync(markerPath)) {
    result.status = 'already_migrated'

    return result
  }

  if (!fs.existsSync(sourceDir)) {
    result.status = 'no_source'

    return result
  }

  try {
    fs.mkdirSync(targetDir, { recursive: true })
  } catch (err: unknown) {
    result.status = 'permission_denied'
    result.error = err instanceof Error ? err.message : String(err)

    return result
  }

  const copied: string[] = []

  // Copy files
  for (const file of MIGRATION_FILES) {
    const srcFile = path.join(sourceDir, file)
    const tgtFile = path.join(targetDir, file)

    if (fs.existsSync(srcFile) && !fs.existsSync(tgtFile)) {
      try {
        fs.copyFileSync(srcFile, tgtFile)
        copied.push(file)
      } catch {
        // Non-fatal per-file copy error
      }
    }
  }

  // Copy directories
  for (const dir of MIGRATION_DIRS) {
    const srcSubdir = path.join(sourceDir, dir)
    const tgtSubdir = path.join(targetDir, dir)

    if (fs.existsSync(srcSubdir)) {
      try {
        fs.cpSync(srcSubdir, tgtSubdir, { recursive: true, errorOnExist: false })
        copied.push(dir)
      } catch {
        // Non-fatal per-directory copy error
      }
    }
  }

  result.copied = copied

  // Write marker
  try {
    fs.writeFileSync(
      markerPath,
      JSON.stringify(
        {
          source: sourceDir,
          timestamp: new Date().toISOString(),
          migratedItems: copied
        },
        null,
        2
      ),
      'utf8'
    )
  } catch (err: unknown) {
    result.error = err instanceof Error ? err.message : String(err)
  }

  return result
}

import assert from 'node:assert/strict'

import { test, vi } from 'vitest'

import { createQuitFinalization } from './quit-finalization'

/**
 * #116376: on Windows, closing the last window ran the whole JS quit path
 * (window-all-closed → app.quit → before-quit teardown → will-quit) and the
 * process still stayed resident with 0 windows. The fallback must force the
 * exit once, only on Windows, and only if Electron never reports `quit`.
 */

test('forces a single Windows exit once the admitted quit exceeds its deadline; never arms off Windows', () => {
  let onTimeout: (() => void) | undefined
  const hardExit = vi.fn()

  const finalization = createQuitFinalization({
    isWindows: true,
    schedule: callback => {
      onTimeout = callback

      return 'timer'
    },
    hardExit
  })

  finalization.arm()
  finalization.arm()
  assert.ok(onTimeout)
  onTimeout()
  onTimeout()
  assert.deepEqual(hardExit.mock.calls, [[0]])

  const schedule = vi.fn()
  const posixExit = vi.fn()
  createQuitFinalization({ isWindows: false, schedule, hardExit: posixExit }).arm()
  assert.equal(schedule.mock.calls.length, 0)
  assert.equal(posixExit.mock.calls.length, 0)
})

test('a completed quit cancels the fallback and it never re-arms', () => {
  let onTimeout: (() => void) | undefined
  const cancel = vi.fn()
  const hardExit = vi.fn()

  const schedule = vi.fn((callback: () => void) => {
    onTimeout = callback

    return 'timer'
  })

  const finalization = createQuitFinalization({ isWindows: true, schedule, cancel, hardExit })

  finalization.arm()
  finalization.cancel()
  onTimeout?.()
  finalization.arm()

  assert.deepEqual(cancel.mock.calls, [['timer']])
  assert.equal(hardExit.mock.calls.length, 0)
  assert.equal(schedule.mock.calls.length, 1)
})

/**
 * A quit admitted and deferred for teardown is the only point from which a
 * Windows process can be rescued: a teardown that never settles never reaches
 * `will-quit`, and the resulting windowless process keeps the single-instance
 * lock, so every later launch exits without ever opening the app.
 */
test('an admitted-but-never-finalized quit still forces the Windows exit', () => {
  let onTimeout: (() => void) | undefined
  const hardExit = vi.fn()

  const finalization = createQuitFinalization({
    isWindows: true,
    admittedTimeoutMs: 30_000,
    schedule: callback => {
      onTimeout = callback

      return 'timer'
    },
    hardExit
  })

  finalization.armAdmitted()
  assert.ok(onTimeout, 'admitting the quit must arm the watchdog')
  onTimeout?.()

  assert.deepEqual(hardExit.mock.calls, [[0]])
})

test('the admitted bound is looser than the final-phase bound, and arming twice keeps one timer', () => {
  const deadlines: number[] = []
  const cancel = vi.fn()
  const hardExit = vi.fn()

  const finalization = createQuitFinalization({
    isWindows: true,
    timeoutMs: 10_000,
    admittedTimeoutMs: 30_000,
    schedule: (_callback, delayMs) => {
      deadlines.push(delayMs)

      return 'timer'
    },
    cancel,
    hardExit
  })

  finalization.armAdmitted()
  finalization.arm()

  assert.deepEqual(deadlines, [30_000], 'the admitted quit owns the single armed bound')

  finalization.cancel()
  assert.deepEqual(cancel.mock.calls, [['timer']])
  assert.equal(hardExit.mock.calls.length, 0)

  const posixSchedule = vi.fn()

  const posixFinalization = createQuitFinalization({
    isWindows: false,
    admittedTimeoutMs: 30_000,
    schedule: posixSchedule,
    hardExit: vi.fn()
  })

  posixFinalization.armAdmitted()

  assert.equal(posixSchedule.mock.calls.length, 0)
})

