import { registerRepoStatusCwd, repoStatusForCwd, repoWorktreesForCwd } from '@/store/coding-status'

export function EnvPill({
  cwd,
  disabled,
  onBranchOff,
  onOpenWorktree
}: {
  cwd?: string | null
  disabled?: boolean
  onBranchOff?: () => void
  onOpenWorktree?: (path: string) => void
}) {
