      requestComposerDictation('active')
      await new Promise(resolve => window.setTimeout(resolve, 0))
    })
    expect(mocks.dictate).toHaveBeenCalledTimes(2)
    expect(mocks.endConversation).not.toHaveBeenCalled()

    await act(async () => {
