  const inputDisabled = shouldDisableComposerInput(disabled, gatewayState)

  // The draft engine — detached source of truth (DOM + draftRef + edge
  // selectors); typing never re-renders the chrome. ChatBar owns `queueEditRef`
  // and threads it in so the draft↔queue coupling is an explicit dep, not a tangle.
  const {
    activeQueueSessionKeyRef,
    clearDraft,
    draftScopeRef,
    draftRef,
    editorRef,
    focusInput,
    hasText,
    insertInlineRefs,
    insertText,
    isHelpHint,
    isSteerableText,
    loadIntoComposer,
    requestMainFocus,
    sessionIdRef,
    setComposerText,
    stashAt,
    syncDraftFromEditor
  } = useComposerDraft({ activeQueueSessionKey, focusKey, inputDisabled, queueEditRef, sessionId })

  useComposerScreenshot({ sessionKey: activeQueueSessionKey, focusKey, onAttachImageBlob })

  // Undo/redo. The rich editor bypasses Chromium's editing pipeline for speed,
  // which also bypasses its undo stack — so we own the stack and every edit
  // path below banks its pre-edit state through `recordUndoPoint`.
  const { recordUndoPoint, redo, resetUndoHistory, undo, withUndoPoint } = useComposerUndo({
    editorRef,
    syncDraftFromEditor
  })

  // Paste-to-focus: clipboard images from an unfocused ⌘V ride the bus (the
  // window dispatcher has no handle on this composer's attachment scope).
  // Same ingestion as a focused paste's image branch.
  useEffect(() => {
    if (!onAttachImageBlob) {
      return undefined
    }

    return onComposerAttachImagesRequest(({ blobs, target }) => {
      if (target !== scope.target) {
        return
      }

      triggerHaptic('selection')

      for (const blob of blobs) {
        void onAttachImageBlob(blob)
      }
    })
  }, [onAttachImageBlob, scope.target])

  // Prior history belongs to the draft that just left — undoing into another
  // conversation's text is worse than having none.
  useEffect(() => {
    resetUndoHistory()
  }, [activeQueueSessionKey, resetUndoHistory])

  // "Add URL" dialog — open/value state, autofocus, and submit (host onAddUrl or
  // an @url: directive into the draft).
  const { openUrlDialog, setUrlOpen, setUrlValue, submitUrl, urlInputRef, urlOpen, urlValue } = useComposerUrlDialog({
    insertText,
    onAddUrl
  })

  // The queue engine — queued turns, in-place editing, the shared drain lock,
  // and bounded auto-drain. Consumes the draft API and writes `queueEditRef`.
  const {
    beginQueuedEdit,
    deliverQueuedNow,
    drainNextQueued,
    editingQueuedPrompt,
    exitQueuedEdit,
    queueCurrentDraft,
    queueEdit,
    queueParked,
    queuedPrompts,
    sendQueuedNow,
    steerQueuedNow,
    stepQueuedEdit
  } = useComposerQueue({
    activeQueueSessionKey,
    attachments,
    busy,
    clearDraft,
    draftRef,
    focusInput,
    loadIntoComposer,
    onCancel,
    onSteer,
    onSubmit,
    queueEditRef,
    queueSessionKey,
    sessionId
  })

  const statusStackVisible = queuedPrompts.length > 0 || statusPresent

  // Halt vs. reach-the-queue: every interrupt lands on onCancel, but only the
  // gestures that MEAN "stop working" (Stop button, Esc) go through this
  // wrapper, which parks the queue first — an explicit halt must not roll
  // straight into the next queued prompt (that read as Stop not working; the
  // queued text also seemed to vanish, since the collapsed panel row was its
  // only trace). Interrupts that exist to advance the queue (send-now-while-
  // busy) call the raw onCancel and keep draining on settle. Parked entries
  // stay in the panel until resumed, sent, edited, or deleted.
  const haltRun = useCallback(() => {
    parkQueuedPrompts(activeQueueSessionKeyRef.current)

    return onCancel()
  }, [activeQueueSessionKeyRef, onCancel])

  const { compactPill, foldVoice, minimal, stacked } = useComposerMetrics({
    composerDockRef,
    composerRef,
    composerSurfaceRef,
    editorRef,
    poppedOut
  })

  const hasComposerPayload = hasText || attachments.length > 0
  const canSubmit = busy || hasComposerPayload

  // Steer only makes sense mid-turn, text-only (the gateway can't carry images
  // into a tool result) and never for a slash command (those execute inline).
  // A blocking prompt (approval/sudo/secret) also rules it out: the tool batch
  // is parked on the user, so a steer can't reach the model — text queues.
  // Compaction does not: the gateway holds the correction until it finishes.
  const canSteer = busy && !blockingPrompt && !!onSteer && attachments.length === 0 && isSteerableText

  // While busy: text redirects the live turn (Cursor-style stop-and-correct),
  // attachments queue for the next turn, an empty composer stops.
  const busyAction: 'steer' | 'queue' | 'stop' = canSteer
    ? 'steer'
    : compacting || hasComposerPayload
      ? 'queue'
      : 'stop'

  // The submit engine — the orchestration seam where draft + queue meet. Owns
  // the submit decision tree, the send-with-restore primitive, and steer.
  const { queueDraft, steerDraft, submitDraft } = useComposerSubmit({
    activeQueueSessionKey,
    activeQueueSessionKeyRef,
    attachments,
    busy,
    clearDraft,
    disabled,
    draftScopeRef,
    draftRef,
    drainNextQueued,
    editorRef,
    exitQueuedEdit,
    focusInput,
    inputDisabled,
    loadIntoComposer,
    // The submit engine's only cancel call is the Stop-button branch (busy +
    // empty composer) — an explicit halt, so it parks the queue.
    onCancel: haltRun,
    onSteer,
    onSteerHidden,
    onSubmit,
    queueCurrentDraft,
    queueEdit,
    queuedPrompts,
    sessionId,
    setComposerText,
    stashAt
  })

  // Resting / reconnecting / starting placeholder text, re-rolled only on a real
  // conversation change.
  const placeholder = useComposerPlaceholder({ disabled, reconnecting, sessionId })

  // Trigger / completion engine: @// detection, the adapter-driven item list,
  // popover selection, and chip insertion. The keydown nav block below consumes
  // this API; keyup uses triggerKeyConsumedRef to skip its refresh.
  const {
    argStageEmpty,
    ascendTriggerPath,
    closeTrigger,
    commitTypedSlashDirective,
    moveTriggerActive,
    refreshTrigger,
    replaceTriggerWithChip,
    setTriggerActive,
    slashFreeTextArgStage,
    trigger,
    triggerActive,
    triggerActiveExplicit,
    triggerItems,
    triggerKeyConsumedRef,
    triggerLoading
  } = useComposerTrigger({ at, draftRef, editorRef, emoji, recordUndoPoint, requestMainFocus, setComposerText, slash })

  // Pull the live contentEditable text into draftRef + the AUI composer state
  // (which drives `hasComposerPayload` → the send button). Shared by the input
  // and compositionend paths so committed IME text reaches state through either.
  // A pending coalesced flush (rAF id). `composerPlainText` serializes the whole
  // editor (O(n)), so running it on every event during a burst — holding a key,
  // or holding Cmd+V into a growing editor — is O(n²) across the burst. The
  // contentEditable DOM is the source of truth (submit + the compositionend /
  // keydown paths re-read it synchronously), so collapsing the input/paste
  // flushes to one per paint is lossless.
  const flushRafRef = useRef<number | undefined>(undefined)

  const flushEditorToDraft = (editor: HTMLDivElement) => {
    if (flushRafRef.current !== undefined) {
      window.cancelAnimationFrame(flushRafRef.current)
      flushRafRef.current = undefined
    }

    normalizeComposerEditorDom(editor)

    const nextDraft = sanitizeComposerInput(composerPlainText(editor))

    if (nextDraft !== draftRef.current) {
      draftRef.current = nextDraft
      setComposerText(nextDraft)
    }

    window.setTimeout(refreshTrigger, 0)
  }

  // Coalesce the high-frequency input/paste flushes to one per frame. Immediate
  // paths (compositionend, Enter/keydown, submit) keep calling
  // flushEditorToDraft directly, which cancels any pending coalesced run first.
  const scheduleFlushEditorToDraft = (editor: HTMLDivElement) => {
    if (flushRafRef.current !== undefined) {
      return
    }

    flushRafRef.current = window.requestAnimationFrame(() => {
      flushRafRef.current = undefined
      flushEditorToDraft(editor)
    })
  }

  useEffect(
    () => () => {
      if (flushRafRef.current !== undefined) {
        window.cancelAnimationFrame(flushRafRef.current)
      }
    },
    []
  )

  const handleEditorInput = (event: FormEvent<HTMLDivElement>) => {
    // During IME composition the DOM contains uncommitted preedit text
    // mixed with real content.  Skip state writes — compositionend flushes
    // the finalized text (see onCompositionEnd).
    if (composingRef.current) {
      return
    }

    scheduleFlushEditorToDraft(event.currentTarget)
  }

  // Native typing/deleting mutates the DOM through Chromium's editing pipeline,
  // whose undo stack we've taken over — so bank the pre-edit state here, before
  // the change lands. `beforeinput` is the only hook that still sees the old
  // text. Consecutive keystrokes coalesce into one entry, so ⌘Z steps back by a
  // burst rather than a character.
  const handleEditorBeforeInput = (event: FormEvent<HTMLDivElement>) => {
    const inputType = (event.nativeEvent as InputEvent).inputType

    // Undo/redo are ours (handled in useComposerUndo + keydown), and IME preedit
    // is not a committed edit — compositionend is where that text becomes real.
    if (inputType === 'historyUndo' || inputType === 'historyRedo' || composingRef.current) {
      return
    }

    recordUndoPoint({ coalesce: inputType === 'insertText' || inputType === 'deleteContentBackward' })
  }

  // Cut never reaches the handler above: React's onBeforeInput is a
  // keypress/textInput polyfill and does not observe the native
  // `beforeinput` event, so Chromium's deleteByCut input type is invisible to
  // it. The native `cut` clipboard event still fires before the DOM mutation,
  // which is where the pre-edit snapshot has to be banked or ⌘Z skips the cut.
  const handleCut = () => {
    recordUndoPoint()
  }

  const handlePaste = (event: ClipboardEvent<HTMLDivElement>) => {
    const imageBlobs = extractClipboardImageBlobs(event.clipboardData)

    if (imageBlobs.length > 0 && onAttachImageBlob) {
      triggerHaptic('selection')

      for (const blob of imageBlobs) {
        void onAttachImageBlob(blob)
      }
    }

    // Trim surrounding whitespace so a copy that dragged along leading/trailing
    // blank lines (common when selecting from terminals, code blocks, web pages)
    // doesn't dump multiline padding into the composer. Internal newlines are
    // preserved — only the edges are cleaned up.
    const pastedText = sanitizeComposerInput(event.clipboardData.getData('text').trim())

    if (!pastedText) {
      event.preventDefault()

      if (imageBlobs.length > 0) {
        return
      }

      // Under WSL2/WSLg the Windows host clipboard doesn't bridge *images* to
      // the Linux clipboard the DOM paste event reads, so a host screenshot
      // arrives as an empty paste (no blobs, no text). Fall back to the main
      // process, which pulls the image straight off the Windows clipboard.
      // Silent so a genuinely-empty paste doesn't pop a "no image" warning.
      if (onPasteClipboardImage) {
        triggerHaptic('selection')
        void onPasteClipboardImage({ silent: true })
      }

      return
    }

    if (DATA_IMAGE_URL_RE.test(pastedText)) {
      event.preventDefault()

      return
    }

    event.preventDefault()

    // Pasting exactly one link while composer text is selected turns that text
    // into a markdown link instead of replacing it — the behavior every rich
    // editor ships (ported from block/buzz#6684). Selections that span chips
    // or lines fall through to the normal replace-with-chip path.
    const exactLink = resolveExactLinkPaste(pastedText)

    if (exactLink) {
      const label = selectionLinkLabel(event.currentTarget)

      if (label) {
        recordUndoPoint()
        insertComposerContentsAtCaret(event.currentTarget, markdownLinkFor(label, exactLink))
        scheduleFlushEditorToDraft(event.currentTarget)

        return
      }
    }

    // A paste past the large-paste threshold becomes a `.txt` attachment chip
    // instead of flooding the composer.
    // The instruction the user types stays in the input; the pasted source
    // material rides along as a file. Falls back to inline insertion if the
    // attachment can't be created (missing bridge, write failure) so the
    // paste is never lost.
    if (onAttachPastedText && shouldConvertPasteToAttachment(pastedText)) {
      const editor = event.currentTarget

      void Promise.resolve(onAttachPastedText(pastedText)).then(attached => {
        if (attached) {
          triggerHaptic('selection')

          return
        }

        recordUndoPoint()
        insertComposerContentsAtCaret(editor, pathifyRefs(linkifyUrls(pastedText)), openDirectiveScope(editor))
        scheduleFlushEditorToDraft(editor)
      })

      return
    }

    // Links in the paste land as `@url:` chips rather than a wall of URL text —
    // the same reference the "Add URL" dialog inserts, parsed in place so a link
    // mid-sentence keeps its position. Bare `@path` tokens promote the same way.
    // A paste into an open `@url:`/`@file:` scope CONSUMES that scope instead of
    // stacking on it — the scope is the browse mode the user is pasting into,
    // not text they typed and want to keep (`@url:@url:\`https://…\``).
    const scope = openDirectiveScope(event.currentTarget)

    recordUndoPoint()
    insertComposerContentsAtCaret(event.currentTarget, pathifyRefs(linkifyUrls(pastedText)), scope)
    scheduleFlushEditorToDraft(event.currentTarget)
  }

  const handleEditorKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    // Self-heal a stale composition flag before the guard below reads it.
    // compositionend can be missed (focus jumps, input-source switches, or a
    // programmatic DOM swap mid-preedit abort the composition without the
    // event reaching us), and a wedged composingRef silently swallows every
    // Enter — and, via the form onSubmit guard, the Send button — until the
    // component remounts (#44135). Chromium stamps isComposing on every
    // keydown of a genuine composition, so when the native flag says we're
    // not composing, trust it and recover.
    if (composingRef.current && !event.nativeEvent.isComposing) {
      composingRef.current = false
    }

    // IME composition: Enter confirms composed text, not a message submission.
    // We check both composingRef (set by compositionstart/compositionend, robust
    // across browsers) and nativeEvent.isComposing (Chromium fallback).  Without
    // this guard, pressing Enter to finalise a Korean/Japanese/Chinese IME
    // preedit fires submitDraft() and splits the message mid-word.
    if (composingRef.current || event.nativeEvent.isComposing) {
      return
    }

    // PageUp/PageDown: the composer is a single-line contentEditable — these
    // keys have no text-editing purpose, and letting their default bubble to
    // the browser's scroll-the-nearest-scrollable-ancestor behavior breaks the
    // chat layout in the desktop pane tree (large blank area, sidebar pushed
    // off-screen — #49978). Swallow the default here; the global
    // conversation.scrollPageUp/Down keybind turns the intent into an
    // explicit, focused-transcript page instead.
    if (event.key === 'PageUp' || event.key === 'PageDown') {
      event.preventDefault()

      return
    }

    // macOS Chinese IME (and some 3rd-party IMEs on Windows) emit Enter with
    // keyCode 229 (legacy VK_PROCESSKEY) while isComposing is already false.
    // The compositionend has fired but the keydown still carries 229, signalling
    // "this Enter is an IME commit, not a user send".  If we let it through,
    // the message fires before the committed text is fully in the DOM.
    if (event.key === 'Enter' && event.keyCode === 229) {
      return
    }

    // Undo/redo before anything else — we own the stack (see useComposerUndo),
    // so these never reach Chromium's native history, which has no record of
    // the Range-based edits the rich editor makes.
    if (isUndoShortcut(event.nativeEvent)) {
      event.preventDefault()
      undo()

      return
    }

    if (isRedoShortcut(event.nativeEvent)) {
      event.preventDefault()
      redo()

      return
    }

    // Plain Backspace right after a directive chip: remove the chip + its
    // auto-inserted trailing space as one unit, so deleting a directive never
    // leaves an orphaned space. (Modified backspaces stay native.)
    if (
      event.key === 'Backspace' &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.altKey &&
      withUndoPoint(() => deleteChipBeforeCaret(event.currentTarget))
    ) {
      event.preventDefault()
      flushEditorToDraft(event.currentTarget)

      return
    }

    // Non-collapsed Backspace/Delete: native selection-delete is ~O(n²) on large
    // drafts (Ctrl+A → Delete froze ~1.3s). Collapsed carets fall through.
    if (
      (event.key === 'Backspace' || event.key === 'Delete') &&
      withUndoPoint(() => deleteSelectionInEditor(event.currentTarget))
    ) {
      event.preventDefault()
      flushEditorToDraft(event.currentTarget)

      return
    }

    // A typed link finished with a space chips like a pasted one — the space
    // itself rides along inside the insert.
    if (withUndoPoint(() => chipTypedUrlOnSpace(event))) {
      event.preventDefault()
      flushEditorToDraft(event.currentTarget)

      return
    }

    // Same for a bare `@path` — a hand-typed or Tab-descended path chips into
    // the `@file:`/`@folder:` ref it means, instead of submitting as plain text
    // the backend never resolves.
    if (withUndoPoint(() => chipTypedPathOnSpace(event))) {
      event.preventDefault()
      flushEditorToDraft(event.currentTarget)

      return
    }

    // Cmd/Ctrl+Shift+K drains the next queued message. Plain Cmd/Ctrl+K is
    // reserved for the global command palette.
    if ((event.metaKey || event.ctrlKey) && !event.altKey && event.shiftKey && event.key.toLowerCase() === 'k') {
      event.preventDefault()

      if (!busy) {
        void drainNextQueued()
      }

      return
    }

    // The popover is open but its items are still in flight (debounce + RPC).
    // Tab must not fall through to the browser — it would move focus out of
    // the composer mid-completion, which reads as the popover "eating" the
    // keypress. Swallow it; the refresh lands with the items.
    if (trigger && triggerLoading && triggerItems.length === 0 && event.key === 'Tab') {
      event.preventDefault()
      triggerKeyConsumedRef.current = true

      return
    }

    if (trigger && triggerItems.length > 0) {
      if (event.key === 'ArrowDown') {
        event.preventDefault()
        triggerKeyConsumedRef.current = true
        moveTriggerActive(1)

        return
      }

      if (event.key === 'ArrowUp') {
        event.preventDefault()
        triggerKeyConsumedRef.current = true
        moveTriggerActive(-1)

        return
      }

      // Accepting a completion: a no-arg command commits its directive chip,
      // an arg-taking command expands to its options step, and an arg option
      // commits the full `/cmd arg` chip. Space/Enter resolve the pick so a
      // leftover highlight does not replace a typed command; Tab still takes
      // the highlight.
      const accept = acceptsTriggerCompletion({
        activeExplicit: triggerActiveExplicit,
        freeTextArgStage: slashFreeTextArgStage,
        key: event.key,
        kind: trigger.kind,
        query: trigger.query
      })

      if (accept) {
        const itemTexts = triggerItems.map(item => {
          const meta = item.metadata as { command?: string; rawText?: string } | undefined

          return meta?.command || meta?.rawText || item.label
        })

        const item =
          trigger.kind === '/' && event.key !== 'Tab'
            ? triggerItems[
                implicitSlashAcceptIndex(trigger.query, itemTexts, triggerActive, triggerActiveExplicit) ?? -1
              ]
            : triggerItems[triggerActive]

        if (item) {
          event.preventDefault()
          triggerKeyConsumedRef.current = true
          // Tab means "go deeper" on a folder; Enter means "I want this one".
          replaceTriggerWithChip(item, { descend: event.key === 'Tab' })

          return
        }

        if (event.key === 'Tab') {
          event.preventDefault()
          triggerKeyConsumedRef.current = true

          return
        }
      }

      // Backspace climbs out of an `@` path one segment at a time, mirroring
      // Tab's one-key descent. Only when the caret sits at the end of the
      // token — mid-token editing keeps normal character deletion.
      if (event.key === 'Backspace' && !event.metaKey && !event.altKey && ascendTriggerPath()) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true

        return
      }

      if (event.key === 'Escape') {
        event.preventDefault()
        triggerKeyConsumedRef.current = true
        closeTrigger()

        return
      }
    }

    // Arg stage with nothing left to suggest — a fully-typed arg the backend
    // completer no longer echoes (it drops the exact match), e.g.
    // `/personality creative`. Space/Tab still commit what's typed as a single
    // directive chip; Enter falls through to submit (send it as-is).
    if (
      trigger?.kind === '/' &&
      !triggerItems.length &&
      (event.key === ' ' || event.key === 'Tab') &&
      slashArgStage(trigger.query) &&
      trigger.query.trim()
    ) {
      if (commitTypedSlashDirective()) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true

        return
      }
    }

    // ArrowUp/ArrowDown navigate, in priority order: the queue (edit entries in
    // place) then sent-message history. The history ring is derived from live
    // session messages each press — single source of truth, no mirror.
    if (event.key === 'ArrowUp') {
      // Decide from the live editor: the mirror is a frame behind typing or a
      // paste, and this branch can replace what the user just wrote.
      const currentDraft = liveComposerDraft(editorRef.current, draftRef.current)

      // Editing a queued turn → walk to the older entry.
      if (queueEdit && stepQueuedEdit(-1)) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true

        return
      }

      // Empty composer + a queued turn → open the newest queued entry for edit
      // (the row's pencil), not a text recall. Enter saves it back to the queue.
      if (!currentDraft.trim() && !queueEdit && queuedPrompts.length > 0) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true
        beginQueuedEdit(queuedPrompts[queuedPrompts.length - 1]!)

        return
      }

      // Don't hijack a typed draft unless already browsing — they'd lose it.
      if (currentDraft.trim() && !isBrowsingHistory(sessionId)) {
        return
      }

      event.preventDefault()
      triggerKeyConsumedRef.current = true

      // $messages is read imperatively (not subscribed) so the composer
      // doesn't re-render on every streaming delta flush.
      const history = deriveUserHistory(scope.$messages.get(), chatMessageText)
      const entry = browseBackward(sessionId, currentDraft, history)

      if (entry !== null) {
        loadIntoComposer(entry, scope.attachments.$attachments.get())
      }

      return
    }

    if (event.key === 'ArrowDown') {
      // Editing a queued turn → walk to the newer entry (past the newest exits).
      if (queueEdit) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true
        stepQueuedEdit(1)

        return
      }

      // Browsing sent history → step toward the present, restoring the draft.
      if (isBrowsingHistory(sessionId)) {
        event.preventDefault()
        triggerKeyConsumedRef.current = true

        const history = deriveUserHistory(scope.$messages.get(), chatMessageText)
        const result = browseForward(sessionId, history)

        if (result !== null) {
          loadIntoComposer(result.text, scope.attachments.$attachments.get())
        }
      }

      return
    }

    // Cmd/Ctrl+Enter queues a follow-up while a turn runs. Plain Enter steers
    // a text-only draft, so both live-turn actions stay reachable by keyboard.
    if (event.key === 'Enter' && (event.metaKey || event.ctrlKey) && !event.shiftKey) {
      event.preventDefault()

      if (busy && !disabled) {
        // As with plain Enter, source the just-typed content from the DOM so a
        // fast keypress cannot queue a stale draft.
        const editorText = liveComposerDraft(editorRef.current, draftRef.current)

        if (editorText !== draftRef.current) {
          draftRef.current = editorText
          setComposerText(editorText)
        }

        queueDraft()
      }

      return
    }

    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault()

      // Decide from the DOM, not React state. `hasComposerPayload` is derived
      // from the AUI composer state, which lags the latest keystroke by a
      // render, so on fast typing / IME the just-typed text isn't in state yet.
      // Without the live read, a real message typed while prompts are queued
      // would drain the queue instead of sending. submitDraft() re-syncs and
      // sends the live editor text.
      const editorText = liveComposerDraft(editorRef.current, draftRef.current)
      const hasLivePayload = editorText.trim().length > 0 || attachments.length > 0

      if (disabled) {
        return
      }

      if (!busy && !hasLivePayload && queuedPrompts.length > 0) {
        void drainNextQueued()

        return
      }

      // Empty Enter while busy. With prompts queued this is the double-send:
      // the first Enter put the words in the queue, a second delivers them
      // now — steered into the live turn when a steer can carry them, else
      // promote + interrupt + drain on settle — mirroring the idle empty-Enter
      // drain above. With nothing queued it stays a no-op — interrupting is
      // explicit (Stop/Esc), never a stray Enter after sending. Gate on the live
      // DOM payload (not the render-lagged composer state) so a message typed
      // fast / via IME while busy still reaches submitDraft() and gets queued
      // instead of being mistaken for an empty Enter.
      if (busy && !hasLivePayload) {
        const head = queuedPrompts.find(entry => entry.id !== queueEdit?.entryId)

        if (head) {
          void deliverQueuedNow(head.id)
        }

        return
      }

      submitDraft()

      return
    }

    if (event.key === 'Escape') {
      // Editing a queued turn → Esc cancels the edit, restoring the prior draft.
      if (queueEdit) {
        event.preventDefault()
        exitQueuedEdit('cancel')

        return
      }

      // Otherwise Esc interrupts the running turn (Stop-button parity) — unless
      // the turn is parked waiting on the user, where Esc must not discard the
      // pending prompt. An explicit halt, so it parks the queue too.
      if (busy && !awaitingInput) {
        event.preventDefault()
        triggerHaptic('cancel')
        void Promise.resolve(haltRun())
      }
    }
  }

  const handleEditorKeyUp = triggerKeyUpHandler(triggerKeyConsumedRef, refreshTrigger)

  const {
    dragActive,
    handleDragEnter,
    handleDragLeave,
    handleDragOver,
    handleDrop,
    handleInputDragOver,
    handleInputDrop
  } = useComposerDrop({ cwd, insertInlineRefs, onAttachDroppedItems, recordUndoPoint, requestMainFocus, sessionId })

  // A bot chat is a companion conversation, not a working session, so it has no
  // repo to speak of — see the blank repoPath handed to CodingStatusRow below.
  // Three stores: the scope set records the answer, and resolving this runtime
  // id to the stored one it is filed under reads the other two.
  const botChat = useStoresSelector([$botChatSessionIds, $sessionStates, $sessionTiles], () =>
    isBotChatSession(sessionId)
  )

  // Branch / worktree hand-offs (CodingStatusRow). Owns the worktree open +
  // branch-off/convert/list/switch actions; draft travels into the new session.
  const { handleBranchOff, handleConvertBranch, handleListBranches, handleSwitchBranch, openInWorktree } =
    useComposerBranch({ clearDraft, cwd, draftRef })

  // Global Esc-to-cancel when the chat (not the composer input) has focus.
  // Same explicit-halt semantics as the Stop button: park the queue.
  useComposerEscCancel({ awaitingInput, busy, onCancel: haltRun, target: scope.target })

  const {
    conversation,
    dictate,
    endConversation,
    handleToggleAutoSpeak,
    startConversation,
    voiceActivityState,
    voiceConversationActive,
    voiceStatus
  } = useComposerVoice({
    busy,
    clearDraft,
    disabled,
    focusInput,
    insertText,
    maxRecordingSeconds,
    // Voice barge-in mid-generation halts the run like the Stop button.
    onInterrupt: haltRun,
    onSubmit,
    onTranscribeAudio,
    sessionId,
    target: scope.target
  })

  // Keep the typed-stop interceptor (see onSubmit above) in sync with the
  // live conversation state. Render-time ref assignment, same pattern as
  // dispatchSubmitRef — no effect needed for a plain mirror.
  voiceStopRef.current = { active: voiceConversationActive, end: endConversation }

  const contextMenu = (
    <ContextMenu
      onInsertText={insertText}
      onOpenUrlDialog={openUrlDialog}
      onPasteClipboardImage={onPasteClipboardImage}
      onPickFiles={onPickFiles}
      onPickFolders={onPickFolders}
      onPickImages={onPickImages}
      state={state}
    />
  )

  const isAro = typeof document !== 'undefined' && document.documentElement.dataset.aroUi === 'true'

  const projects = useStore($projectTree)
  const explicitProjects = useStore($projects)
  const projectScope = useStore($projectScope)
  const aroSessionProjectMap = useStore($aroSessionProjectMap)
  const aroDraftProjectId = useStore($aroDraftProjectId)

  const chatBarSessionProjectFromMap = sessionId ? aroSessionProjectMap[sessionId] : null
  const chatBarCurrentProjectId = sessionId ? chatBarSessionProjectFromMap : aroDraftProjectId || projectScope

  const chatBarCurrentProject = chatBarCurrentProjectId
    ? explicitProjects.find(p => p.id === chatBarCurrentProjectId && !p.archived)
    : null

  const chatBarCurrentRoot =
    (chatBarCurrentProject && 'primary_path' in chatBarCurrentProject ? chatBarCurrentProject.primary_path : null) ||
    (chatBarCurrentProject && 'folders' in chatBarCurrentProject ? chatBarCurrentProject.folders?.[0]?.path : null) ||
    null

  const leadingCluster = (
    <div className="flex min-w-0 items-center gap-1" data-aro-composer-leading="">
      {contextMenu}
      {!isAro && (
        <ProjectPickerControl
          cwd={cwd}
          disabled={inputDisabled}
          placement="toolbar"
          profile={profile}
          sessionId={sessionId}
        />
      )}
      {!isAro && (
        <>
          <Button
            aria-label="Slash commands"
            className="h-[30px] w-[30px] rounded-control p-0 text-aro-ink-3 hover:bg-aro-hover hover:text-aro-ink"
            disabled={inputDisabled}
            onClick={() => insertText('/')}
            size="icon"
            type="button"
            variant="ghost"
          >
            <span aria-hidden className="font-mono text-xs font-semibold">
              /
            </span>
          </Button>
          <Button
            aria-label="Path and context references"
            className="h-[30px] w-[30px] rounded-control p-0 text-aro-ink-3 hover:bg-aro-hover hover:text-aro-ink"
            disabled={inputDisabled}
            onClick={() => insertText('@')}
            size="icon"
            type="button"
            variant="ghost"
          >
            <span aria-hidden className="font-mono text-xs font-semibold">
              @
            </span>
          </Button>
        </>
      )}
    </div>
  )

  const modeControl = <ApprovalModePill disabled={disabled} gateway={gateway} sessionId={sessionId} />

  const envControl = (
    <EnvPill
      cwd={cwd}
      disabled={disabled}
      onBranchOff={() => void openWorktreeDialog({ repoPath: cwd ?? undefined })}
      onOpenWorktree={path => {
        requestStartWorkSession(path)
      }}
    />
  )

  const contextControl = <ContextPill busy={busy} gateway={gateway} sessionId={sessionId} />

  const controls = (
    <ComposerControls
      autoSpeak={autoSpeak}
      busy={busy}
      busyAction={busyAction}
      canSubmit={canSubmit}
      compactModelPill={poppedOut || compactPill}
      contextControl={contextControl}
      conversation={{
        active: voiceConversationActive,
        level: conversation.level,
        muted: conversation.muted,
        onEnd: endConversation,
        onStart: startConversation,
        onStopTurn: conversation.stopTurn,
        onToggleMute: conversation.toggleMute,
        status: conversation.status
      }}
      disabled={disabled}
      envControl={envControl}
      foldVoice={foldVoice}
      hasComposerPayload={hasComposerPayload}
      hideModelPill={guidedChat}
      leadingCluster={leadingCluster}
      minimal={minimal}
      modeControl={modeControl}
      onDictate={dictate}
      onQueue={queueDraft}
      onToggleAutoSpeak={handleToggleAutoSpeak}
      state={state}
      voiceStatus={voiceStatus}
    />
  )

  const inputWidthClass = composerInputWidthClass(stacked)

  const input = (
    <div className={cn('relative', inputWidthClass)}>
      <div
        aria-disabled={inputDisabled ? true : undefined}
        aria-label={t.composer.message}
        autoCapitalize="off"
        // Chromium's macOS text-replacement path shares the autocorrect gate.
        // Keeping spellcheck off below still excludes smart quotes and dashes.
        autoCorrect={isMacPlatform() ? 'on' : 'off'}
        className={cn(
          'min-h-[1.625rem] min-h-(--composer-input-min-height) max-h-(--composer-input-max-height) cursor-text overflow-y-auto whitespace-pre-wrap break-words [overflow-wrap:anywhere] bg-transparent pb-1 pr-1 pt-1 leading-normal text-foreground outline-none disabled:cursor-not-allowed',
          '**:data-ref-text:cursor-default',
          stacked && 'pl-3',
          inputWidthClass,
          // Inside the native Wayland HUD drag region: a drag region swallows
          // the page's mouse input whole, so the input must opt back out or it
          // becomes unclickable. Buttons use the global no-drag rule.
          hudNativeDrag && '[-webkit-app-region:no-drag]'
        )}
        contentEditable={!inputDisabled}
        data-placeholder={placeholder}
        data-slot={RICH_INPUT_SLOT}
        dir={textDirection}
        onBeforeInput={handleEditorBeforeInput}
        onBlur={() => {
          // A composition never survives focus loss (Chromium commits the
          // preedit and fires compositionend on blur) — but if that event is
          // missed, the wedged flag would block the Send button's form-submit
          // guard forever (#44135). Clear unconditionally: by the time blur
          // runs there is nothing left composing in this editor.
          composingRef.current = false

          if (blurCloseTimer.current !== null) {
            window.clearTimeout(blurCloseTimer.current)
          }

          blurCloseTimer.current = window.setTimeout(() => {
            blurCloseTimer.current = null
            closeTrigger()
          }, 80)
        }}
        onCompositionEnd={event => {
          composingRef.current = false

          // The input events fired *during* composition were skipped (they
          // carried uncommitted preedit text), and Chromium does NOT reliably
          // emit a trailing input event after compositionend on Windows IMEs.
          // Without flushing here, committed multi-character IME input (e.g.
          // Chinese "你好", Japanese, Korean) never reaches composer state, so
          // `hasComposerPayload` stays false and the send button stays hidden
          // until an unrelated edit forces a sync (#39614).
          flushEditorToDraft(event.currentTarget)
        }}
        onCompositionStart={event => {
          composingRef.current = true

          // Input events are skipped for the rest of the composition, so
          // nothing else would clear the empty marker until it ends — and the
          // hint would sit behind the preedit text the whole time (#75960).
          beginComposerComposition(event.currentTarget)
        }}
        onCut={handleCut}
        onDragOver={handleInputDragOver}
        onDrop={handleInputDrop}
        onFocus={() => markActiveComposer(scope.target)}
        onInput={handleEditorInput}
        onKeyDown={handleEditorKeyDown}
        onKeyUp={handleEditorKeyUp}
        onMouseUp={refreshTrigger}
        onPaste={handlePaste}
        ref={editorRef}
        role="textbox"
        spellCheck={false}
        suppressContentEditableWarning
      />
      <ComposerDirectiveActions editorRef={editorRef} />
      {/* assistant-ui requires ComposerPrimitive.Input somewhere in the tree
        so the composer-state binding (text + IME + paste + form-submit hookup)
        wires up. We render the real input UI ourselves above via the
        contentEditable, so the primitive is invisible (sr-only).

        IMPORTANT: don't let it render its default <TextareaAutosize>. That
        component runs `useLayoutEffect(resizeTextarea)` on every value change
        and reads `node.scrollHeight` against a hidden measurement textarea,
        forcing two synchronous layouts per keystroke for an element the
        user can't see. Profiling 400-char synthetic typing showed >900ms
        cumulative cost in getHeight2/calculateNodeHeight alone (~2.3ms/key)
        on top of the per-keystroke React commit.

        `asChild` swaps TextareaAutosize for a Radix Slot wrapping our
        plain <textarea>, which carries the binding but skips autosize. */}
      <ComposerPrimitive.Input asChild submitMode="ctrlEnter" tabIndex={-1} unstable_focusOnScrollToBottom={false}>
        <textarea
          aria-hidden
          autoCapitalize="off"
          autoComplete="off"
          autoCorrect="off"
          className="sr-only"
          spellCheck={false}
          tabIndex={-1}
        />
      </ComposerPrimitive.Input>
    </div>
  )

  return (
    <>
      {dragging && poppedOut && (
        <div
          aria-hidden
          // `absolute`, not `fixed`: anchor to the chat-column root (the same
          // `relative isolate` container the docked composer centers in) so the
          // glow spans the thread area only — never the full viewport / under the
          // sidebar. The dock target IS the docked position, so they must share
          // a containing block.
          className="pointer-events-none absolute inset-x-0 bottom-0 z-20 h-32"
          style={{
            // A bottom-centered radial glow — soft on every side by construction,
            // so it reads as the dock target without any hard band edges. Its
            // intensity tracks how close the composer is to the dock (1 = peak).
            background:
              'radial-gradient(64% 130% at 50% 100%, color-mix(in srgb, var(--color-primary) 26%, transparent) 0%, transparent 70%)',
            // Scaled by --dock-glow-scale (lower in light mode — see styles.css).
            opacity: `calc(${0.1 + dockProximity * 0.57} * var(--dock-glow-scale, 1))`
          }}
        />
      )}
      <ComposerPrimitive.Unstable_TriggerPopoverRoot>
        {/* Dock column: owns the composer's POSITION and stacks, bottom-up,
            [micro actions] · [status stack] · [composer] · [underside].
            Anchored at the bottom, so in-flow children grow upward and still
            overlay the thread — no absolute lane needed.

            The strips are siblings of the composer, not children: the pop-out
            drag region is `absolute inset-0` INSIDE the composer, so anything
            rendered in there is inside the grab area by construction. Keeping
            them out here is what makes that impossible rather than excluded. */}
        <div
          className={cn(
            'z-30 flex flex-col',
            poppedOut ? 'fixed max-w-[calc(100vw-1.5rem)]' : 'absolute bottom-0 left-1/2 max-w-full -translate-x-1/2'
          )}
          data-popped-out={poppedOut ? '' : undefined}
          data-slot="composer-dock"
          data-thread-scrolled-up={scrolledUp ? '' : undefined}
          // Measured for the thread's bottom clearance: the dock is the box
          // that contains the strips, the status stack, AND the composer, so
          // one measurement covers everything the thread must clear.
          ref={composerDockRef}
          style={
            poppedOut
              ? {
                  bottom: `${popoutPosition.bottom}px`,
                  right: `${popoutPosition.right}px`,
                  // A compact one-sentence width when floating.
                  ['--composer-popout-width' as string]: `${POPOUT_WIDTH_REM}rem`
                }
              : undefined
          }
        >
          {/* Aligned to the composer SURFACE, which sits inside the composer's
              5px transparent grab margin — so both strips carry the same inset
              and share one left edge with it. */}
          <div className={cn(composerFloatingStrip, 'px-[5px] pb-1.5 empty:hidden')}>
            <ActionBadges sessionId={statusSessionId} />
            <SuggestionPills sessionId={statusSessionId} />
            <OnboardingSkip />
          </div>
          {/* Session-scoped status stack (todos, subagents, background tasks,
              queue). An in-flow dock child: the dock is bottom-anchored, so it
              grows upward over the thread and the dock's own measurement covers
              it. Collapses to nothing when every status is empty. */}
          <StatusDrawerContent collapsed={statusDrawerCollapsed} id={statusDrawerId}>
            <ComposerStatusStack
              onSubmit={onSubmit}
              queue={
                activeQueueSessionKey && queuedPrompts.length > 0 ? (
                  <QueuePanel
                    busy={busy}
                    editingId={queueEdit?.entryId ?? null}
                    entries={queuedPrompts}
                    onDelete={id => {
                      if (removeQueuedPrompt(activeQueueSessionKey, id) && queueEdit?.entryId === id) {
                        exitQueuedEdit('cancel')
                      }
                    }}
                    onEdit={beginQueuedEdit}
                    onResume={() => {
                      unparkQueuedPrompts(activeQueueSessionKey)

                      // Idle → kick the head immediately; busy → the settle drain
                      // takes over now that the park is lifted.
                      if (!busy) {
                        void drainNextQueued()
                      }
                    }}
                    onSendNow={id => void sendQueuedNow(id)}
                    onSteerNow={id => void steerQueuedNow(id)}
                    parked={queueParked}
                  />
                ) : null
              }
              sessionId={statusSessionId}
            />
          </StatusDrawerContent>
          <ComposerPrimitive.Root
            className={cn(
              'group/composer relative w-full overflow-visible rounded-overlay',
              poppedOut && 'bg-transparent',
              dragging && 'cursor-grabbing select-none touch-none',
              // Native Wayland HUD: setBounds cannot position a top-level
              // surface, so the bar must ask the compositor to move it. X11
              // stays out of app-region mode so the renderer receives its
              // Ctrl+primary-button drag. pt-4 is the carved-out grab band.
              hudNativeDrag && 'hud-native-drag pt-4 [-webkit-app-region:drag]'
            )}
            data-aro-composer=""
            data-drag-active={dragActive ? '' : undefined}
            data-hud-grabbing={hudGrabbing ? '' : undefined}
            data-popped-out={poppedOut ? '' : undefined}
            data-slot="composer-root"
            data-status-stack={statusStackVisible && !statusDrawerCollapsed ? '' : undefined}
            data-thread-scrolled-up={scrolledUp ? '' : undefined}
            data-tip-region=""
            data-tour={composerTourMarker}
            onDragEnter={handleDragEnter}
            onDragLeave={handleDragLeave}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
            onPointerDown={!hudMode && popoutAllowed ? onComposerGesturePointerDown : undefined}
            onPointerDownCapture={hudMode ? onHudDragPointerDown : undefined}
            onSubmit={e => {
              e.preventDefault()

              if (composingRef.current) {
                return
              }

              submitDraft()
            }}
            ref={composerRef}
          >
            {isHelpHint && <HelpHint />}
            {trigger && !argStageEmpty && (
              <ComposerTriggerPopover
                activeIndex={triggerActive}
                items={triggerItems}
                kind={trigger.kind}
                loading={triggerLoading}
                onHover={setTriggerActive}
                onPick={replaceTriggerWithChip}
                scope={trigger.scope}
              />
            )}
            {!poppedOut && (
              <div
                className="pointer-events-none absolute inset-0 rounded-[inherit]"
                style={{ background: COMPOSER_FADE_BACKGROUND }}
              />
            )}
            {/* Drag region: covers the transparent grab margin around the surface.
              The surface sits on top (z-4) so only the exposed ring receives this
              element's hover/cursor — grab cursor + a diagonal hatch (/////)
              appear when you hover the draggable margin, never over the input.
              The hatch pattern + opacity ladder live in styles.css. */}
            {popoutAllowed && (
              <div
                aria-hidden
                className={cn('pointer-events-auto absolute inset-0', dragging ? 'cursor-grabbing' : 'cursor-grab')}
                data-dragging={dragging ? '' : undefined}
                data-slot="composer-drag-region"
                onDoubleClick={handleComposerToggle}
              />
            )}
            <div className="relative w-full rounded-[inherit]">
              {!hudMode && !guidedChat && (
                <StatusDrawerToggle
                  collapsed={statusDrawerCollapsed}
                  controls={`${statusDrawerId} ${codingDrawerId}`}
                  onToggle={toggleStatusDrawer}
                />
              )}
              {hudMode && busy && <span aria-hidden className="arc-border arc-composer" />}
              <div
                className={cn(
                  // grid-cols-[minmax(0,1fr)]: the implicit `auto` column sized
                  // itself to its items' min-content, so a status row whose
                  // content out-measured a narrow pane silently widened the
                  // track past the surface — and every `w-full` child (the fade,
                  // the input/controls row) laid out against that phantom width
                  // and got clipped by overflow-hidden, send button first.
                  'group/composer-surface relative z-4 isolate grid grid-cols-[minmax(0,1fr)] grid-rows-[auto_1fr] overflow-hidden rounded-[inherit] border border-[color-mix(in_srgb,var(--dt-composer-ring)_calc(18%*var(--composer-ring-strength)),var(--dt-input))]',
                  COMPOSER_DROP_FADE_CLASS,
                  dragActive && COMPOSER_DROP_ACTIVE_CLASS
                )}
                data-aro-composer-layout="codex"
                data-aro-composer-surface=""
                data-aro-listening={voiceStatus !== 'idle' ? '' : undefined}
                data-aro-streaming={busy ? '' : undefined}
                data-slot="composer-surface"
                ref={composerSurfaceRef}
              >
                {/* Prototype drop overlay (globals.css .reference-composer +
                    Workbench.tsx drop card): while a drag hovers the composer, a
                    dashed iris panel with a raised card announces the attach
                    target. Pointer-events-none — the real handlers live on the
                    composer root and the input. */}
                {isAro && dragActive ? (
                  <div
                    aria-hidden
                    className="pointer-events-none absolute inset-0 z-30 flex animate-in items-center justify-center rounded-[inherit] border-2 border-dashed border-aro-iris bg-aro-void/85 fade-in zoom-in-95 backdrop-blur-xs duration-150"
                  >
                    <div className="flex items-center gap-2 rounded-panel border border-aro-line-strong bg-aro-raise px-3.5 py-2 text-sm font-medium text-aro-iris-soft shadow-(--aro-shadow-e3)">
                      <IconFolder className="animate-bounce" size={17} />
                      <span>Drop to attach to this session</span>
                    </div>
                  </div>
                ) : null}
                <div aria-hidden className={composerInputBacking} />
                {codingRowShown && (
                  <StatusDrawerContent collapsed={statusDrawerCollapsed} id={codingDrawerId}>
                    <CodingStatusRow
                      onBranchOff={handleBranchOff}
                      onConvertBranch={handleConvertBranch}
                      onListBranches={handleListBranches}
                      // A tile's rail reviews ITS worktree: pin the pane's scope to
                      // this surface's cwd. Main keeps the classic follow-the-
                      // active-session scope (null).
                      onOpen={() => toggleReview(scope.target === 'main' ? null : (cwd ?? null), scope.target)}
                      onOpenWorktree={openInWorktree}
                      onSwitchBranch={handleSwitchBranch}
                      // Blank in a bot chat: the row hides itself without a repo,
                      // and stops probing git / GitHub for a surface that has no
                      // branch to show. Cheaper than a second composer.
                      repoPath={botChat ? undefined : cwd}
                    />
                  </StatusDrawerContent>
                )}
                <div
                  className={cn(
                    'relative z-1 flex min-h-0 w-full flex-col gap-(--composer-row-gap) overflow-hidden rounded-[inherit] px-(--composer-surface-pad-x) py-(--composer-surface-pad-y) transition-opacity duration-200 ease-out',
                    scrolledUp
                      ? 'opacity-30 group-hover/composer:opacity-100 group-focus-within/composer-surface:opacity-100'
                      : 'opacity-100'
                  )}
                  data-slot="composer-fade"
                >
                  {/* Contribution seams: banners above, a row below, inline
                    additions beside the "+" menu and before the controls.
                    All four render nothing until something contributes. */}
                  <ContribSlot area={COMPOSER_AREAS.top} />
                  {isAro && (
                    <ProjectPickerControl
                      cwd={cwd}
                      disabled={inputDisabled}
                      placement="header"
                      profile={profile}
                      sessionId={sessionId}
                    />
                  )}
                  <RestoredDraftNotice
                    freshDraft={activeQueueSessionKey === null}
                    onUndone={clearDraft}
                    readLiveText={syncDraftFromEditor}
                  />
                  <VoiceActivity state={voiceActivityState} />
                  <VoicePlaybackActivity />
                  {queueEdit && editingQueuedPrompt && (
                    <div className="flex items-center justify-between gap-2 rounded-panel border border-[color-mix(in_srgb,var(--dt-composer-ring)_32%,transparent)] bg-accent/18 px-2 py-1">
                      <div className="min-w-0 text-aro-xs text-muted-foreground/88">
                        {t.composer.editingQueuedInComposer}
                      </div>
                      <div className="flex shrink-0 items-center gap-1">
                        <Button
                          className="h-6 rounded-control px-2 text-aro-xs"
                          onClick={() => exitQueuedEdit('cancel')}
                          type="button"
                          variant="ghost"
                        >
                          {t.common.cancel}
                        </Button>
                        <Button
                          className="h-6 rounded-control px-2 text-aro-xs"
                          onClick={() => exitQueuedEdit('save')}
                          type="button"
                        >
                          {t.common.save}
                        </Button>
                      </div>
                    </div>
                  )}
                  {attachments.length > 0 && <AttachmentList attachments={attachments} onRemove={onRemoveAttachment} />}
                  <div className="min-h-[4.25rem] min-w-0 w-full" data-slot="input">
                    {input}
                  </div>
                  <div
                    className="reference-composer-toolbar flex min-h-[40px] w-full min-w-0 items-center justify-between gap-1"
                    data-slot="footer"
                  >
                    <ContribSlot area={COMPOSER_AREAS.leading} />
                    {controls}
                    <ContribSlot area={COMPOSER_AREAS.actions} />
                  </div>
                  <ContribSlot area={COMPOSER_AREAS.bottom} />
                </div>
              </div>
            </div>
          </ComposerPrimitive.Root>
          {isAro && Boolean(chatBarCurrentProject && chatBarCurrentRoot) && (
            <AroRepoBar
              cwd={chatBarCurrentRoot}
              onOpenDiff={() => toggleReview(chatBarCurrentRoot, scope.target)}
              onOpenSettings={() => void openWorktreeDialog({ repoPath: chatBarCurrentRoot ?? undefined })}
              sessionId={sessionId}
            />
          )}
          {/* Underside: chrome-free strip BELOW the composer. Outside the root
              for the same reason as the micro actions — it must not fall inside
              the pop-out drag region. Same px as the strip above, so the two
              bracket the composer on one vertical line. */}
          <div className={cn(composerFloatingStrip, 'px-[5px] pt-1.5 empty:hidden')}>
            <ContribSlot area={COMPOSER_AREAS.underside} />
          </div>
          {typeof document !== 'undefined' && document.documentElement.dataset.aroUi === 'true' && !sessionId && (
            <p className="mt-2 text-center text-aro-xs text-(--ui-text-quaternary) select-none pointer-events-none">
              Blank canvas — nothing is connected until you choose a project and model.
            </p>
          )}
          {/* The floating voice orb, driven by THIS composer's real voice
              engine (dictation pipeline + VAD conversation). Fixed-position,
              so the dock column is just its React home. */}
          {typeof document !== 'undefined' &&
            document.documentElement.dataset.aroUi === 'true' &&
            !hudMode &&
            !poppedOut && (
              <VoiceAgentOrb
                busy={busy}
                conversationActive={voiceConversationActive}
                conversationStatus={conversation.status}
                dictate={dictate}
                onEndConversation={endConversation}
                onStartConversation={startConversation}
                onSubmit={text => {
                  void onSubmit(text)
                }}
                voiceActivity={voiceActivityState}
                voiceStatus={voiceStatus}
              />
            )}
        </div>
      </ComposerPrimitive.Unstable_TriggerPopoverRoot>

      <UrlDialog
        inputRef={urlInputRef}
        onChange={setUrlValue}
        onOpenChange={setUrlOpen}
        onSubmit={submitUrl}
        open={urlOpen}
        value={urlValue}
      />
    </>
  )
}

export function ChatBarFallback() {
  return (
    <div
      className={cn(
        'group/composer absolute bottom-0 left-1/2 z-30 w-[min(var(--composer-width),calc(100%-2rem))] max-w-full -translate-x-1/2 rounded-overlay pt-2 pb-[var(--composer-shell-pad-block-end)]',
        'bg-linear-to-b from-transparent to-background/55'
      )}
      data-slot="composer-root"
    >
      <div className="composer-fallback-surface relative isolate h-(--composer-fallback-height) w-full rounded-[inherit] border border-[color-mix(in_srgb,var(--dt-composer-ring)_calc(18%*var(--composer-ring-strength)),var(--dt-input))]">
        <div aria-hidden className={composerInputBacking} />
      </div>
    </div>
  )
}

/** Project selector matching the prototype's "attach/switch project" control.
 * Existing sessions move through Hermes' workspace RPC; a fresh draft enters
 * the project scope so the next session is created in that workspace. */
function ProjectPickerControl({
  cwd,
  disabled,
  placement,
  profile,
  sessionId
}: {
  cwd?: null | string
  disabled: boolean
  placement: 'header' | 'toolbar'
  profile?: null | string
  sessionId?: null | string
}) {
  const { t } = useI18n()
  const projects = useStore($projectTree)
  const explicitProjects = useStore($projects)
  const loading = useStore($projectTreeLoading)
  const projectScope = useStore($projectScope)
  const aroSessionProjectMap = useStore($aroSessionProjectMap)
  const aroDraftProjectId = useStore($aroDraftProjectId)
  const sessions = useStore($sessions)
  const projectOwners = useStore($projectOwnerBySessionId)
  const [open, setOpen] = useState(false)

  const [gitStatus, setGitStatus] = useState<Awaited<
    ReturnType<NonNullable<ReturnType<typeof desktopGit>>['repoStatus']>
  > | null>(null)

  const [search, setSearch] = useState('')
  const session = sessionId ? sessions.find(item => item.id === sessionId) : null

  const currentProjectId = session
    ? session.id.startsWith('draft_')
      ? aroSessionProjectMap[session.id] || resolveAroDraftProjectId(aroDraftProjectId, projectScope)
      : resolveAroSessionProjectId(session, explicitProjects, projectOwners, aroSessionProjectMap)
    : sessionId
      ? aroSessionProjectMap[sessionId] ||
        (sessionId.startsWith('draft_') ? resolveAroDraftProjectId(aroDraftProjectId, projectScope) : null)
      : resolveAroDraftProjectId(aroDraftProjectId, projectScope)

  const currentProject = currentProjectId ? explicitProjects.find(p => p.id === currentProjectId && !p.archived) : null

  const currentRoot =
    (currentProject && 'primary_path' in currentProject ? currentProject.primary_path : null) ||
    (currentProject && 'folders' in currentProject ? currentProject.folders?.[0]?.path : null) ||
    null

  const currentLabel = currentProject?.name

  const $repoStatus = repoStatusForCwd(currentRoot)
  const liveRepoStatus = useStore($repoStatus)
  const configuredDefault = useStore($configuredDefaultProjectDir)

  useEffect(() => {
    if (!currentRoot) {
      return
    }

    const unregister = registerRepoStatusCwd(currentRoot)

    return () => {
      unregister?.()
    }
  }, [currentRoot])

  useEffect(() => {
    let cancelled = false

    if (!currentRoot) {
      setGitStatus(null)

      return
    }

    const git = desktopGit()

    if (!git) {
      setGitStatus(null)

      return
    }

    void git
      .repoStatus(currentRoot)
      .then(status => {
        if (!cancelled) {
          setGitStatus(status)
        }
      })
      .catch(() => {
        if (!cancelled) {
          setGitStatus(null)
        }
      })

    return () => {
      cancelled = true
    }
  }, [currentRoot])

  const effectiveStatus = liveRepoStatus || gitStatus

  const availableProjects = useMemo(() => {
    const list: Array<{ id: string; label: string; path: string; color?: string; isDemo?: boolean }> = []
    const seen = new Set<string>()

    // Strictly from explicit projects ($projects)
    for (const p of explicitProjects) {
      if (p.id && !p.archived && !seen.has(p.id)) {
        seen.add(p.id)
        const pPath = p.primary_path || p.folders?.[0]?.path || ''
        list.push({
          id: p.id,
          label: p.name || p.id,
          path: pPath,
          color: p.color || undefined,
          isDemo: p.id.includes('demo') || (p.name || '').toLowerCase().includes('demo')
        })
      }
    }

    return list
  }, [explicitProjects])

  const filteredProjects = useMemo(() => {
    if (!search.trim()) {
      return availableProjects
    }

    const query = search.toLowerCase()

    return availableProjects.filter(
      p => p.label.toLowerCase().includes(query) || (p.path || '').toLowerCase().includes(query)
    )
  }, [availableProjects, search])

  const chooseProject = async (projectId?: string) => {
    const isDraftSession = Boolean(sessionId?.startsWith('draft_'))
    const isFreshDraft = !sessionId || isDraftSession

    if (!projectId) {
      await clearAroProjectAndRevertToDefault(sessionId)
      setOpen(false)

      return
    }

    const project = availableProjects.find(item => item.id === projectId)

    if (!project) {
      setOpen(false)

      return
    }

    const projectRoot = project.path.trim()

    if (project.id === currentProjectId) {
      if (isFreshDraft) {
        setAroDraftProject(projectId)
        setNewChatWorkspaceTarget(projectRoot || null)

        if (projectRoot) {
          setCurrentCwd(projectRoot)
          followEnteredProjectCwd(projectRoot)
        }

        if (isDraftSession && sessionId) {
          void assignSessionToProject(sessionId, projectId)
          setSessions(prev => prev.map(item => (item.id === sessionId ? { ...item, cwd: projectRoot || null } : item)))
        }
      }

      setOpen(false)

      return
    }

    try {
      if (sessionId && !isDraftSession) {
        await assignSessionToProject(sessionId, projectId)

        if (sessionId === $selectedStoredSessionId.get() && projectRoot) {
          setCurrentCwd(projectRoot)
          commitWorkspaceCwdForSelectedSession(projectRoot)
          followEnteredProjectCwd(projectRoot)
          setSessions(prev => prev.map(item => (item.id === sessionId ? { ...item, cwd: projectRoot || null } : item)))
        }
      } else {
        setAroDraftProject(projectId)
        setNewChatWorkspaceTarget(projectRoot || null)

        if (projectRoot) {
          setCurrentCwd(projectRoot)
          followEnteredProjectCwd(projectRoot)
        }

        if (isDraftSession && sessionId) {
          await assignSessionToProject(sessionId, projectId)
          setSessions(prev => prev.map(item => (item.id === sessionId ? { ...item, cwd: projectRoot || null } : item)))
        }
      }

      enterProject(projectId)
      setOpen(false)
      void Promise.all([refreshProjects().catch(() => {}), refreshProjectTree().catch(() => {})])
    } catch (error) {
      notifyError(error, 'Could not switch project')
    }
  }

  return (
    <DropdownMenu
      onOpenChange={next => {
        setOpen(next)

        if (!next) {
          setSearch('')
        } else {
          void Promise.all([refreshProjects().catch(() => {}), refreshProjectTree().catch(() => {})])
        }
      }}
      open={open}
    >
      {placement === 'header' && currentLabel ? (
        <div
          className={cn(
            'group/project-pill flex h-7 w-auto max-w-[min(100%,18rem)] min-w-0 self-start items-center rounded-full border border-aro-line-soft bg-aro-raise/60 pl-2.5 pr-1 text-left text-xs text-aro-ink hover:bg-aro-hover hover:border-aro-line transition-colors',
            disabled && 'opacity-60 pointer-events-none'
          )}
          data-aro-project-control=""
          data-aro-project-placement={placement}
          data-aro-project-selected=""
        >
          <DropdownMenuTrigger asChild>
            <button
              aria-label={`${t.sidebar.projects.worktreeProjectLabel}: ${currentLabel}${effectiveStatus?.branch ? ` (${effectiveStatus.branch})` : ''}`}
              className="flex h-full min-w-0 flex-1 items-center gap-1.5 text-left text-xs text-aro-ink hover:text-aro-ink focus:outline-none"
              disabled={disabled}
              type="button"
            >
              <IconFolder className="shrink-0 text-aro-iris-soft" size={14} />
              <span className="max-w-[11rem] min-w-0 truncate font-medium">{currentLabel}</span>
              <IconChevronDown
                className="shrink-0 text-aro-ink-4 transition-transform group-data-[state=open]:rotate-180"
                size={11}
              />
            </button>
          </DropdownMenuTrigger>
          <button
            aria-label="Clear project (revert to default workspace)"
            className="ml-1 flex size-4 shrink-0 items-center justify-center rounded-full text-aro-ink-4 hover:bg-aro-raise hover:text-aro-ink transition-colors"
            disabled={disabled}
            onClick={e => {
              e.stopPropagation()
              e.preventDefault()
              void chooseProject(undefined)
            }}
            type="button"
          >
            <IconX size={10} />
          </button>
        </div>
      ) : (
        <DropdownMenuTrigger asChild>
          <Button
            aria-label={
              currentLabel
                ? `${t.sidebar.projects.worktreeProjectLabel}: ${currentLabel}${effectiveStatus?.branch ? ` (${effectiveStatus.branch})` : ''}`
                : t.composer.chooseProject
            }
            className={cn(
              placement === 'header'
                ? 'group flex h-7 w-auto max-w-[min(100%,16rem)] min-w-0 self-start items-center justify-start gap-1.5 rounded-full border border-aro-line-soft bg-aro-raise/60 px-2.5 text-left text-xs text-aro-ink-3 hover:bg-aro-hover hover:text-aro-ink'
                : 'h-[30px] w-[30px] shrink-0 rounded-control p-0 text-aro-ink-2 hover:bg-aro-hover hover:text-aro-ink',
              currentLabel && placement === 'header' && 'text-aro-ink'
            )}
            data-aro-project-control=""
            data-aro-project-placement={placement}
            data-aro-project-selected={currentLabel ? '' : undefined}
            disabled={disabled}
            size={placement === 'header' ? 'sm' : 'icon'}
            type="button"
            variant="ghost"
          >
            <IconFolder size={15} />
            {placement === 'header' && (
              <>
                <span className="max-w-[12rem] min-w-0 truncate">{currentLabel || t.composer.chooseProject}</span>
                <IconChevronDown
                  className="shrink-0 text-aro-ink-4 transition-transform group-data-[state=open]:rotate-180"
                  size={12}
                />
              </>
            )}
          </Button>
        </DropdownMenuTrigger>
      )}
      <DropdownMenuContent align="start" className="w-[340px] p-0" side="top" sideOffset={8}>
        <div className="repo-chooser">
          {currentRoot && effectiveStatus ? (
            <div className="mx-2.5 my-2 flex items-center gap-1.5 rounded-control border border-aro-line-soft bg-aro-bg/70 px-2.5 py-1.5 text-xs text-aro-ink-3">
              <IconBranch className="text-aro-iris-soft shrink-0" size={12} />
              <span className="min-w-0 flex-1 truncate font-mono">{effectiveStatus.branch || 'Detached HEAD'}</span>
              {effectiveStatus.changed > 0 ? (
                <span className="shrink-0 text-amber-500 font-medium font-mono">
                  +{effectiveStatus.changed} changed
                </span>
              ) : (
                <span className="shrink-0 text-emerald-500 font-medium font-mono">Clean</span>
              )}
            </div>
          ) : null}
          <div className="repo-chooser-search">
            <IconSearch size={13} />
            <input
              aria-label="Search repositories"
              onChange={e => setSearch(e.target.value)}
              placeholder="Search repositories…"
              value={search}
            />
          </div>
          <div className="repo-chooser-list">
            {(!search.trim() || 'default'.includes(search.toLowerCase())) && (
              <button
                className={cn('repo-chooser-row', !currentProjectId && 'selected')}
                onClick={() => void chooseProject(undefined)}
                type="button"
              >
                <span className="repo-chooser-main">
                  <span className="repo-chooser-name flex items-center gap-1.5">
                    <span className="size-2 rounded-full shrink-0 bg-aro-ink-4" />
                    <span>Default</span>
                  </span>
                  <span className="repo-chooser-sub">
                    {configuredDefault ? `Default: ${configuredDefault}` : 'No project (standalone chat)'}
                  </span>
                </span>
                {!currentProjectId ? <IconCheck className="repo-chooser-check" size={13} /> : null}
              </button>
            )}
            {loading && explicitProjects.length === 0 ? (
              <div className="p-3 text-center text-xs text-aro-ink-3">Loading projects…</div>
            ) : filteredProjects.length === 0 && search.trim() && !'default'.includes(search.toLowerCase()) ? (
              <p className="repo-chooser-empty">{`No repositories match “${search}”.`}</p>
            ) : (
              filteredProjects.map(project => {
                const isSelected = project.id === currentProjectId
                const root = project.path
                const isDemo = project.id.includes('demo') || project.label.toLowerCase().includes('demo')

                return (
                  <button
                    className={cn('repo-chooser-row', isSelected && 'selected')}
                    key={project.id}
                    onClick={() => void chooseProject(project.id)}
                    type="button"
                  >
                    <span className="repo-chooser-main">
                      <span className="repo-chooser-name flex items-center gap-1.5">
                        <span
                          className="size-2 rounded-full shrink-0"
                          style={{ backgroundColor: (project as { color?: string }).color || '#818cf8' }}
                        />
                        <span>{project.label}</span>
                      </span>
                      {root ? <span className="repo-chooser-sub">{root}</span> : null}
                    </span>
                    {isDemo ? <span className="repo-chooser-demo">DEMO</span> : null}
                    {isSelected ? <IconCheck className="repo-chooser-check" size={13} /> : null}
                  </button>
                )
              })
            )}
          </div>
          <div className="flex items-center justify-between border-t border-aro-line-soft/60 px-2.5 py-1.5">
            <button
              className="repo-chooser-add"
              onClick={() => {
                setOpen(false)
                openProjectCreate()
              }}
              type="button"
            >
              <IconPlus size={12} /> New project…
            </button>
            <button
              aria-label="Set default workspace directory for chats without a project"
              className="text-xs text-aro-ink-3 hover:text-aro-ink flex items-center gap-1 transition-colors px-1.5 py-0.5 rounded-control hover:bg-aro-hover"
              onClick={() => {
                setOpen(false)
                void chooseAndSetDefaultWorkspaceDir()
              }}
              type="button"
            >
              <IconFolder size={12} /> Default workspace…
            </button>
          </div>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

