import { GlyphSpinner } from '@/components/ui/glyph-spinner'
import { releaseTypingFocus } from '@/components/ui/keyboard-first'
import { Tip } from '@/components/ui/tooltip'
import { useI18n } from '@/i18n'
import { ChevronDown } from '@/lib/icons'
import { formatModelPillLabel, providerDisplayName } from '@/lib/model-status-label'
import { cn } from '@/lib/utils'
import { $currentModelSource, setModelPickerOpen } from '@/store/session'

import { useComposerModelPillLabel } from './contrib'
import { onComposerModelMenuRequest } from './focus'
import { RICH_INPUT_SLOT } from './rich-editor'
import { useComposerScope } from './scope'
import type { ChatBarState } from './types'

// `shrink` (not `shrink-0`) with a truncating label: the pill is the one
// control in the row that can give width back continuously, so it absorbs the
// squeeze between collapse stages instead of pushing Send past the edge.
// No `max-w-*` cap: the pill sizes to its label, so a long model name only
// truncates when the row is genuinely out of room (#49340) — not at an
// arbitrary 160px.
const PILL = cn(
  'h-[28px] min-w-0 shrink gap-1 rounded-full border border-aro-line-soft bg-aro-well/60 px-3 text-xs font-normal shadow-(--aro-shadow-e1) transition-colors',
  'text-aro-ink-3 hover:border-aro-line hover:bg-aro-hover hover:text-aro-ink'
)

/**
 * Composer model selector — the relocated status-bar pill. Reuses the live
 * `model.options` dropdown (`modelMenuContent`) verbatim; falls back to the
 * full picker when the gateway is closed and no live menu exists.
 *
 * Display follows THIS surface's SessionView (primary or tile) — never the
 * primary-only globals — so side-by-side panes each show their own model.
 */
export function ModelPill({
  compact = false,
  disabled,
  model
}: {
  compact?: boolean
  disabled: boolean
  model: ChatBarState['model']
}) {
  const copy = useI18n().t.shell.statusbar
  // Two return branches below, one handle: only ever one of them mounts.
  const tourMarker = useTourMarker('model-pill')
  const view = useSessionView()
  // Prefer the chat-bar snapshot (already view-scoped by ChatView); fall back
  // to the live SessionView atoms so a mid-flight session.info still paints.
  const viewModel = useStore(view.$model)
  const viewProvider = useStore(view.$provider)
  const currentModel = model.model || viewModel
  const currentProvider = model.provider || viewProvider
  const fastMode = useStore(view.$fast)
  const reasoningEffort = useStore(view.$reasoningEffort)
  const modelSource = useStore($currentModelSource)
  const runtimeId = useStore(view.$runtimeId)
  const [open, setOpen] = useState(false)
  const restoreSelection = useRef<(() => void) | null>(null)
  const scope = useComposerScope()
  const hasLiveMenu = Boolean(model.modelMenuContent)

  // The `composer.modelPicker` hotkey, routed to exactly one surface (the pane
  // under the pointer, else the active composer — see requestModelMenuToggle).
  // Toggles the live dropdown; with no live menu (gateway closed) it opens the
  // full picker dialog, same as clicking the pill.
  useEffect(
    () =>
      onComposerModelMenuRequest(target => {
        if (target !== scope.target || disabled) {
          return
        }

        if (hasLiveMenu) {
          const editor = document.activeElement
          const selection = window.getSelection()

          if (
            editor instanceof HTMLElement &&
            editor.dataset.slot === RICH_INPUT_SLOT &&
            selection?.anchorNode &&
            selection.focusNode &&
            editor.contains(selection.anchorNode) &&
            editor.contains(selection.focusNode)
          ) {
            const { anchorNode, anchorOffset, focusNode, focusOffset } = selection

            restoreSelection.current = () => {
              if (
                !editor.isConnected ||
                isElementInHiddenPane(editor) ||
                !editor.contains(anchorNode) ||
                !editor.contains(focusNode)
              ) {
                return
              }

              editor.focus({ preventScroll: true })
              window.getSelection()?.setBaseAndExtent(anchorNode, anchorOffset, focusNode, focusOffset)
            }
          }

          setOpen(prev => !prev)
        } else {
          setModelPickerOpen(true)
        }
      }),
    [scope.target, disabled, hasLiveMenu]
  )

  // The composer pick is sticky: a manual selection is pinned and every NEW
  // chat uses it instead of the Settings → Model default — silently, which has
  // cost users real money on a forgotten paid-model pick (#62055). Surface the
  // pin whenever a draft (no live session) is running on a manual override. A
  // live session's footer reflects that session's model, so no badge there.
  // Tiles always have a runtime — pin badge is primary-draft only.
  const pinnedOverride =
    view.kind === 'primary' && !runtimeId && modelSource === 'manual' && Boolean(currentModel.trim())

  // The model resolves a beat after the gateway/session comes up. Rather than
  // flash a literal "No model", show a quiet loader (inherits the pill text
  // color at half opacity) until a model lands.
  //
  // A `composer.modelPill` provider may override the LABEL (compact reasoning
  // label, custom naming) — the pill keeps its chrome, pin dot, and menu; only
  // the text changes, and a provider that declines leaves the core label.
  const pillLabel = useComposerModelPillLabel({ compact, model: currentModel, reasoningEffort: reasoningEffort || '' })

  const label = compact ? (
    <ChevronDown className="size-3.5 shrink-0 opacity-70" />
  ) : (
    <>
      {currentModel.trim() ? (
        <span className="truncate">{pillLabel ?? formatModelPillLabel(currentModel, { fastMode })}</span>
      ) : (
        <GlyphSpinner className="opacity-50" spinner="braille" />
      )}
      {pinnedOverride && (
        <span
          aria-label={copy.modelPinned}
          className="size-1 shrink-0 rounded-full bg-(--ui-accent)"
          data-testid="model-pinned-dot"
          role="img"
        />
      )}
      <ChevronDown className="size-2.5 shrink-0 opacity-50" />
    </>
  )

  // Compact (floating composer): a snug square holding just the chevron — no pill
  // padding, sized to match the other composer icon buttons.
  const pillClass = compact
    ? cn(
        'size-(--composer-control-size) shrink-0 justify-center gap-0 rounded-control p-0',
        'text-(--ui-text-tertiary) hover:bg-(--chrome-action-hover) hover:text-foreground'
      )
    : PILL

  const baseTitle = currentProvider
    ? copy.modelTitle(providerDisplayName(currentProvider), currentModel || copy.modelNone)
    : copy.switchModel

  const title = pinnedOverride ? `${baseTitle} — ${copy.modelPinned}` : baseTitle

  if (!model.modelMenuContent) {
    return (
      <Tip label={pinnedOverride ? `${copy.openModelPicker} — ${copy.modelPinned}` : copy.openModelPicker} side="top">
        <Button
          aria-label={copy.openModelPicker}
          className={pillClass}
          data-aro-model-pill=""
          data-tour={tourMarker}
          disabled={disabled}
          onClick={() => setModelPickerOpen(true)}
          type="button"
          variant="ghost"
        >
          {label}
        </Button>
      </Tip>
    )
  }

  // Closing the menu ends its claim on the keyboard: Radix restores focus to
  // this pill (a toolbar button), so without the release the Enter that
  // committed a model also swallows whatever you type next.
  const setMenuOpen = (next: boolean) => {
    setOpen(next)

    if (!next) {
      releaseTypingFocus()
    }
  }

  return (
    <DropdownMenu onOpenChange={setMenuOpen} open={open}>
      <Tip label={title} side="top">
        <DropdownMenuTrigger asChild>
          <Button
            aria-label={title}
            className={pillClass}
            data-aro-model-pill=""
            data-tour={tourMarker}
            disabled={disabled}
            type="button"
            variant="ghost"
          >
            {label}
          </Button>
        </DropdownMenuTrigger>
      </Tip>
      <DropdownMenuContent
        align="end"
        className="w-72 p-0"
        onCloseAutoFocus={event => {
          if (restoreSelection.current) {
            event.preventDefault()
            restoreSelection.current()
            restoreSelection.current = null
          }
        }}
        onInteractOutside={() => {
          restoreSelection.current = null
        }}
        side="top"
        sideOffset={8}
      >
        <ModelMenuCloseContext.Provider value={() => setMenuOpen(false)}>
          {model.modelMenuContent}
        </ModelMenuCloseContext.Provider>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import { DEFAULT_REASONING_EFFORT } from '@hermes/shared'
import { useStore } from '@nanostores/react'
import { useState } from 'react'

import { useSessionView } from '@/app/chat/session-view'
import { ModelMenuCloseContext } from '@/app/shell/model-menu-panel'
import { Button } from '@/components/ui/button'
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from '@/components/ui/dropdown-menu'
import { GlyphSpinner } from '@/components/ui/glyph-spinner'
import { releaseTypingFocus } from '@/components/ui/keyboard-first'
import { Tip } from '@/components/ui/tooltip'
import { useI18n } from '@/i18n'
import { ChevronDown } from '@/lib/icons'
import { reasoningEffortClamp, reasoningEffortLabel } from '@/lib/reasoning-effort'
import { cn } from '@/lib/utils'
import { $defaultReasoningEffort } from '@/store/session'

import type { ChatBarState } from './types'

const PILL = cn(
  'h-[28px] shrink-0 gap-1 rounded-full border border-aro-line-soft bg-aro-well/60 px-3 text-xs font-normal shadow-(--aro-shadow-e1) transition-colors',
  'text-aro-ink-3 hover:border-aro-line hover:bg-aro-hover hover:text-aro-ink'
)

/**
 * Composer reasoning selector: the active model's effort level as its own
 * pill next to the model pill, opening the same Thinking / Fast / Effort rows
 * the catalog offers per model — without having to find the model's row and
 * hover its submenu. Hidden when the catalog says the model has no reasoning
 * control, and while there is no live menu (gateway closed).
 *
 * Reads THIS surface's SessionView (primary or tile), like the model pill.
 */
export function ReasoningPill({ disabled, model }: { disabled: boolean; model: ChatBarState['model'] }) {
  const copy = useI18n().t.shell.modelOptions
  const view = useSessionView()
  const reasoningEffort = useStore(view.$reasoningEffort)
  const reasoningEffortWire = useStore(view.$reasoningEffortWire)
  const pending = useStore(view.$reasoningEffortPending)
  const defaultEffort = useStore($defaultReasoningEffort)
  const [open, setOpen] = useState(false)

  if (!model.reasoningMenuContent || model.supportsReasoning === false) {
    return null
  }

  const effort = reasoningEffort || defaultEffort || DEFAULT_REASONING_EFFORT
  // A clamped pick (`ultra` → `max`) keeps the pill compact ("Ultra→Max") and
  // spells out the CLI's wording in the tooltip, so Ultra is never shown as a
  // distinct wire level the route does not have (#61634).
  const clamp = reasoningEffortClamp(effort, reasoningEffortWire)
  const label = reasoningEffortLabel(effort, reasoningEffortWire)

  // Until the session reports its own effort, the profile default is a guess
  // about to be replaced (#79807). Show the model pill's quiet loader instead.
  const title = pending
    ? copy.effort
    : clamp
      ? `${copy.effort}: ${copy[clamp.effort]} (${copy.sendsOnRoute(copy[clamp.wire])})`
      : `${copy.effort}: ${label}`

  // Closing the menu ends its claim on the keyboard: Radix restores focus to
  // this pill (a toolbar button), so without the release the Enter that
  // committed a level also swallows whatever you type next.
  const setMenuOpen = (next: boolean) => {
    setOpen(next)

    if (!next) {
      releaseTypingFocus()
    }
  }

  return (
    <DropdownMenu onOpenChange={setMenuOpen} open={open}>
      <Tip label={title} side="top">
        <DropdownMenuTrigger asChild>
          <Button
            aria-label={title}
            className={PILL}
            data-aro-reasoning-pill=""
            data-testid="reasoning-pill"
            disabled={disabled}
            type="button"
            variant="ghost"
          >
            {pending ? <GlyphSpinner className="opacity-50" spinner="braille" /> : <span>{label}</span>}
            <ChevronDown className="size-2.5 shrink-0 opacity-50" />
          </Button>
        </DropdownMenuTrigger>
      </Tip>
      <DropdownMenuContent align="end" className="w-52 p-0" side="top" sideOffset={8}>
        <ModelMenuCloseContext.Provider value={() => setMenuOpen(false)}>
          {model.reasoningMenuContent}
        </ModelMenuCloseContext.Provider>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

