import { cleanup, render } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { PaneVisibleContext } from '@/components/pane-shell/pane-visibility'
import { I18nProvider } from '@/i18n'
import * as gateway from '@/store/gateway'
import { _resetSessionOwnerHintsForTests, setSessionOwnerHint } from '@/store/session'
import { $subagentsBySession } from '@/store/subagents'

import { SubagentTranscript } from './subagent-transcript'
import { useSubagentSnapshot } from './use-subagent-snapshot'

const SID = 'sess-hidden-subagent-poll'

function SnapshotHarness({ sessionId }: { sessionId: string }) {
  useSubagentSnapshot(sessionId)

  return <div data-testid="snapshot-harness" />
}

function snapshotTree(visible: boolean) {
  return (
    <PaneVisibleContext.Provider value={visible}>
      <SnapshotHarness sessionId={SID} />
    </PaneVisibleContext.Provider>
  )
}

function transcriptTree(visible: boolean) {
  return (
    <I18nProvider configClient={null} initialLocale="en">
      <PaneVisibleContext.Provider value={visible}>
        <SubagentTranscript sessionId={SID} subagentId="worker" />
      </PaneVisibleContext.Provider>
    </I18nProvider>
  )
}

// #106686: keep-alive hidden tiles stay mounted with document.visibilityState
// === 'visible', so document.hidden alone never stops subagent.list (5s) or
// subagent.tail (2s); both effects gate on usePaneVisible() and re-run on reveal.
describe('hidden-pane subagent polls', () => {
  const request = vi.fn(async (_c: string, _p: string, method: string) => {
    if (method === 'subagent.list') {
      return { subagents: [] }
    }

    if (method === 'subagent.tail') {
      return { available: true, text: 'tail', truncated: false }
    }

    return {}
  })

  const listCalls = () => request.mock.calls.filter(([, , method]) => method === 'subagent.list').length
  const tailCalls = () => request.mock.calls.filter(([, , method]) => method === 'subagent.tail').length

  beforeEach(() => {
    vi.useFakeTimers()
    vi.spyOn(document, 'visibilityState', 'get').mockReturnValue('visible')
    request.mockClear()
    vi.spyOn(gateway, 'requestGatewayForAgent').mockImplementation(request as never)
    setSessionOwnerHint(SID, { connectionId: 'remote-owner', profile: 'research' })
  })

  afterEach(() => {
    cleanup()
    vi.useRealTimers()
    vi.restoreAllMocks()
    $subagentsBySession.set({})
    _resetSessionOwnerHintsForTests()
  })

  it('hidden snapshot tile issues no subagent.list; reveal seeds once and polls every 5s; hiding again stops it', async () => {
    const view = render(snapshotTree(false))
    await vi.advanceTimersByTimeAsync(15_000)
    expect(listCalls()).toBe(0)

    view.rerender(snapshotTree(true))
    await vi.advanceTimersByTimeAsync(0)
    expect(listCalls()).toBe(1)
    await vi.advanceTimersByTimeAsync(15_100)
    expect(listCalls()).toBe(1 + 3)

    view.rerender(snapshotTree(false))
    await vi.advanceTimersByTimeAsync(15_000)
    expect(listCalls()).toBe(1 + 3)
  })

  it('hidden transcript tile issues no subagent.tail; reveal seeds once and polls every 2s; hiding again stops it', async () => {
    const view = render(transcriptTree(false))
    await vi.advanceTimersByTimeAsync(6_000)
    expect(tailCalls()).toBe(0)

    view.rerender(transcriptTree(true))
    await vi.advanceTimersByTimeAsync(0)
    expect(tailCalls()).toBe(1)
    await vi.advanceTimersByTimeAsync(6_100)
    expect(tailCalls()).toBe(1 + 3)

    view.rerender(transcriptTree(false))
    await vi.advanceTimersByTimeAsync(6_000)
    expect(tailCalls()).toBe(1 + 3)
  })

  it('visible snapshot tile skips in-tick polls while the document is hidden', async () => {
    vi.spyOn(document, 'visibilityState', 'get').mockReturnValue('hidden')
    render(snapshotTree(true))
    await vi.advanceTimersByTimeAsync(0)
    await vi.advanceTimersByTimeAsync(15_000)
    expect(listCalls()).toBe(1)
  })
})

import { cleanup, render } from '@testing-library/react'
import { MemoryRouter } from 'react-router'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { PaneVisibleContext } from '@/components/pane-shell/pane-visibility'
import { I18nProvider } from '@/i18n'
import { $backgroundStatusBySession, resetBackgroundPollingGuard } from '@/store/composer-status'
import { $gateway } from '@/store/gateway'

import { ComposerStatusStack } from './index'

// The stack measures itself into a surface var — jsdom has no ResizeObserver.
class ResizeObserverStub {
  observe() {}
  unobserve() {}
  disconnect() {}
}

vi.stubGlobal('ResizeObserver', ResizeObserverStub)

const SID = 'sess-dead-runtime'

function renderStack() {
  return render(
    <MemoryRouter>
      <I18nProvider configClient={null} initialLocale="en">
        <ComposerStatusStack queue={null} sessionId={SID} />
      </I18nProvider>
    </MemoryRouter>
  )
}

// #98434: a boot-restored tile can stay bound to a dead runtime id and remount
// repeatedly (no genuine rebind ever happens). The mount effect used to clear
// the gone-polling latch on every mount, so each remount re-armed the 4001
// storm against that id forever.
describe('ComposerStatusStack dead-runtime remount', () => {
  beforeEach(() => {
    resetBackgroundPollingGuard()
  })

  afterEach(() => {
    cleanup()
    $gateway.set(null as never)
    resetBackgroundPollingGuard()
  })

  it('does not re-poll process.list after a remount once the session is latched gone', async () => {
    const request = vi.fn(async (method: string) => {
      if (method === 'process.list') {
        throw new Error('session not found')
      }

      return {}
    })

    const processListCalls = () => request.mock.calls.filter(([method]) => method === 'process.list').length

    $gateway.set({ request } as never)

    const first = renderStack()
    await Promise.resolve()
    await Promise.resolve()

    expect(processListCalls()).toBe(1)

    first.unmount()

    const second = renderStack()
    await Promise.resolve()
    await Promise.resolve()

    // Before the fix: the mount effect cleared the latch, so this remount
    // re-fired process.list against the same dead id.
    expect(processListCalls()).toBe(1)

    second.unmount()
  })
})

// #73287: keep-alive keeps every ever-active tab mounted, so each background
// tile's 5s safety-net poll used to fire even while its tab was hidden — N
// sessions meant N gateway round-trips plus shared-map churn forever.
describe('ComposerStatusStack hidden-pane poll', () => {
  const SID_BG = 'sess-bg-poll'

  const runningList = vi.fn(async (method: string) =>
    method === 'process.list' ? { processes: [{ command: 'dev server', session_id: 'bg1', status: 'running' }] } : {}
  )

  const processListCalls = () => runningList.mock.calls.filter(([method]) => method === 'process.list').length

  function renderStackBg(visible: boolean) {
    return render(
      <MemoryRouter>
        <I18nProvider configClient={null} initialLocale="en">
          <PaneVisibleContext.Provider value={visible}>
            <ComposerStatusStack queue={null} sessionId={SID_BG} />
          </PaneVisibleContext.Provider>
        </I18nProvider>
      </MemoryRouter>
    )
  }

  beforeEach(() => {
    vi.useFakeTimers()
    // jsdom defaults to 'prerender', which the in-tick document check skips.
    vi.spyOn(document, 'visibilityState', 'get').mockReturnValue('visible')
    runningList.mockClear()
    $gateway.set({ request: runningList } as never)
  })

  afterEach(() => {
    cleanup()
    vi.useRealTimers()
    vi.restoreAllMocks()
    $gateway.set(null as never)
    $backgroundStatusBySession.set({})
    resetBackgroundPollingGuard()
  })

  it('hidden tile skips the 5s poll; visible tile polls; reveal resumes', async () => {
    const hidden = renderStackBg(false)
    await vi.advanceTimersByTimeAsync(0)
    await vi.advanceTimersByTimeAsync(15_000)
    // Mount seed only — the interval never armed while hidden.
    expect(processListCalls()).toBe(1)
    hidden.unmount()

    const shown = renderStackBg(true)
    await vi.advanceTimersByTimeAsync(0)
    await vi.advanceTimersByTimeAsync(15_000)
    // Mount seed + three 5s ticks.
    expect(processListCalls()).toBe(1 + 1 + 3)
    shown.unmount()
  })

  it('revealing a hidden tile arms the poll', async () => {
    const view = renderStackBg(false)
    await vi.advanceTimersByTimeAsync(0)
    await vi.advanceTimersByTimeAsync(15_000)
    expect(processListCalls()).toBe(1)

    view.rerender(
      <MemoryRouter>
        <I18nProvider configClient={null} initialLocale="en">
          <PaneVisibleContext.Provider value>
            <ComposerStatusStack queue={null} sessionId={SID_BG} />
          </PaneVisibleContext.Provider>
        </I18nProvider>
      </MemoryRouter>
    )
    await vi.advanceTimersByTimeAsync(10_000)
    expect(processListCalls()).toBeGreaterThan(1)
    view.unmount()
  })
})

import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter } from 'react-router'
import { afterEach, expect, it, vi } from 'vitest'

import * as gateway from '@/store/gateway'
import { _resetSessionOwnerHintsForTests, setSessionOwnerHint } from '@/store/session'
import { $subagentsBySession, upsertSubagent } from '@/store/subagents'

import { ComposerStatusStack } from './index'

vi.stubGlobal(
  'ResizeObserver',
  class {
    disconnect() {}
    observe() {}
    unobserve() {}
  }
)
Element.prototype.animate = vi.fn(() => ({ cancel() {} }) as Animation)
afterEach(() => {
  cleanup()
  $subagentsBySession.set({})
  _resetSessionOwnerHintsForTests()
  vi.restoreAllMocks()
})

it('hydrates the empty owner composer and exposes an extended owner-routed transcript without leaking on session change', async () => {
  const text = '  Full transcript\tline with preserved whitespace  \n\n'.repeat(100)

  const request = vi.spyOn(gateway, 'requestGatewayForAgent').mockImplementation(async (_c, _p, method) => {
    if (method === 'subagent.list') {
      return {
        subagents: [
          { subagent_id: 'worker', goal: 'Recovered work', started_at: 1000, status: 'running', last_tool: 'read_file' }
        ],
        delegations: []
      } as never
    }

    if (method === 'subagent.tail') {
      return { subagent_id: 'worker', available: true, text, truncated: true } as never
    }

    return {} as never
  })

  setSessionOwnerHint('parent', { connectionId: 'remote-owner', profile: 'research' })

  const view = render(
    <MemoryRouter>
      <ComposerStatusStack queue={null} sessionId="parent" />
    </MemoryRouter>
  )

  fireEvent.click(await screen.findByRole('button', { name: /1 Subagent/ }))
  await screen.findByText('Recovered work')
  expect(screen.getByText('Read File')).toBeTruthy()
  expect(request).toHaveBeenCalledWith('remote-owner', 'research', 'subagent.list', { session_id: 'parent' })
  expect($subagentsBySession.get().parent[0].startedAt).toBe(1000000)
  fireEvent.click(screen.getByRole('button', { name: /Recovered work/ }))
  await waitFor(() => expect(document.querySelector('[data-slot="subagent-transcript"]')?.textContent).toContain(text))
  expect(request).toHaveBeenCalledWith('remote-owner', 'research', 'subagent.tail', {
    session_id: 'parent',
    subagent_id: 'worker'
  })
  view.rerender(
    <MemoryRouter>
      <ComposerStatusStack queue={null} sessionId="other" />
    </MemoryRouter>
  )
  expect(document.querySelector('[data-slot="subagent-transcript"]')).toBeNull()
})

it('does not resurrect a child completed while the roster snapshot was in flight', async () => {
  let resolve!: (value: unknown) => void
  vi.spyOn(gateway, 'requestGatewayForAgent').mockImplementation(async (_c, _p, method) => {
    if (method === 'subagent.list') {
      return (await new Promise<unknown>(r => {
        resolve = r
      })) as never
    }

    return {} as never
  })
  setSessionOwnerHint('parent', { connectionId: 'remote-owner', profile: 'research' })
  upsertSubagent('parent', { subagent_id: 'worker', goal: 'Finishing work' })
  render(
    <MemoryRouter>
      <ComposerStatusStack queue={null} sessionId="parent" />
    </MemoryRouter>
  )
  await waitFor(() => expect(resolve).toBeTypeOf('function'))
  act(() => upsertSubagent('parent', { subagent_id: 'worker', status: 'completed' }, false, 'subagent.complete'))
  await act(async () =>
    resolve({ subagents: [{ subagent_id: 'worker', goal: 'Finishing work', status: 'running' }], delegations: [] })
  )
  expect(screen.queryByText('Finishing work')).toBeNull()
