import { compactNumber } from '@hermes/shared'
import { useStore } from '@nanostores/react'
import { useCallback, useEffect, useState } from 'react'

import { useContextBreakdown } from '@/app/shell/hooks/use-context-breakdown'
import { IconBrain, IconMcp } from '@/aro/Icons'
import { Badge, Bar, Panel, Ring } from '@/aro/ui'
import { listMcpServers } from '@/hermes'
import { cn } from '@/lib/utils'
import { activeGateway } from '@/store/gateway'
import { $activeSessionId, $busy, $selectedStoredSessionId } from '@/store/session'
import type { McpServerSummary } from '@/types/hermes'

export function ContextSection() {
  const activeSessionId = useStore($activeSessionId)
  const selectedStoredId = useStore($selectedStoredSessionId)
  const sessionId = activeSessionId || selectedStoredId
  const busy = useStore($busy)

  const requestGateway = useCallback(
    function <T = unknown>(method: string, params?: Record<string, unknown>): Promise<T> {
      const gw = activeGateway()

      if (!gw) {
        return Promise.reject(new Error('Gateway not connected'))
      }

      return gw.request(method, params ?? {})
    },
    []
  )

  const { breakdown, loading: breakdownLoading } = useContextBreakdown({
    busy,
    enabled: true,
    requestGateway,
    sessionId: sessionId ?? null,
  })

  const [mcpServers, setMcpServers] = useState<McpServerSummary[]>([])
  const [mcpLoading, setMcpLoading] = useState(false)

  useEffect(() => {
    let mounted = true

    if (!window.hermesDesktop?.api) {
      setMcpLoading(false)

      return
    }

    setMcpLoading(true)
    listMcpServers()
      .then(res => {
        if (mounted) {
          setMcpServers(res.servers ?? [])
        }
      })
      .catch(() => {
        if (mounted) {
          setMcpServers([])
        }
      })
      .finally(() => {
        if (mounted) {
          setMcpLoading(false)
        }
      })

    return () => {
      mounted = false
    }
  }, [])

  const usagePercent = Math.min(100, Math.max(0, Math.round(breakdown?.context_percent ?? 0)))
  const totalTokens = breakdown?.context_used ?? 0
  const maxTokens = breakdown?.context_max ?? 200_000
  const categories = breakdown?.categories ?? []

  return (
    <div className="space-y-3 p-3">
      {/* Context window gauge & breakdown */}
      <Panel className="p-3">
        <div className="flex items-center gap-3">
          <Ring size={54} stroke={5} tone="var(--aro-iris)" value={usagePercent}>
            <span className="font-aro-mono text-xs font-semibold text-aro-ink">{usagePercent}%</span>
          </Ring>
          <div className="min-w-0 flex-1 space-y-1">
            <div className="flex items-baseline justify-between">
              <span className="text-xs font-medium text-aro-ink-2">Context window</span>
              <span className="font-aro-mono text-[var(--aro-text-2xs,10px)] text-aro-ink-4">
                {compactNumber(totalTokens)} / {compactNumber(maxTokens)}
              </span>
            </div>

            {categories.length > 0 ? (
              categories.map(c => {
                const percent = totalTokens > 0 ? Math.round((c.tokens / totalTokens) * 100) : 0

                return (
                  <div className="flex items-center gap-2" key={c.id}>
                    <span className="w-[84px] shrink-0 truncate text-aro-xs text-aro-ink-3">{c.label}</span>
                    <Bar height={3} tone="iris" value={percent} />
                    <span className="w-8 text-right font-aro-mono text-[var(--aro-text-2xs,9px)] text-aro-ink-4">
                      {compactNumber(c.tokens)}
                    </span>
                  </div>
                )
              })
            ) : (
              <div className="text-aro-xs text-aro-ink-4">
                {breakdownLoading ? 'Analyzing context…' : 'No active context tokens'}
              </div>
            )}
          </div>
        </div>
      </Panel>

      {/* MCP Connectors */}
      <Panel>
        <div className="flex items-center justify-between border-b border-aro-line-soft px-2.5 py-2">
          <span className="flex items-center gap-1.5 font-aro-mono text-aro-xs font-semibold tracking-[.14em] text-aro-ink-4 uppercase">
            <IconMcp size={10} /> MCP Connectors
          </span>
          <Badge className="text-[var(--aro-text-2xs,9px)]" mono tone={mcpServers.length > 0 ? 'mint' : 'neutral'}>
            {mcpServers.filter(s => s.enabled).length} live
          </Badge>
        </div>
        <div className="p-2">
          {mcpServers.length === 0 ? (
            <div className="py-2 text-center font-aro-mono text-aro-xs text-aro-ink-4">
              {mcpLoading ? 'Querying connectors…' : 'No MCP servers configured'}
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-1.5">
              {mcpServers.map(s => {
                const toolCount = s.tools?.length ?? 0

                return (
                  <div className="rounded-control border border-aro-line-soft bg-aro-well px-2 py-1.5" key={s.name}>
                    <div className="flex items-center gap-1.5">
                      <i
                        className={cn(
                          'size-[5px] shrink-0 rounded-full',
                          s.enabled ? 'bg-aro-mint' : 'bg-aro-line-strong'
                        )}
                      />
                      <span className="truncate font-aro-mono text-aro-xs text-aro-ink-2" title={s.name}>
                        {s.name}
                      </span>
                      <span className="ml-auto shrink-0 font-aro-mono text-[var(--aro-text-2xs,9px)] text-aro-ink-4">
                        {toolCount}t
                      </span>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>
      </Panel>

      {/* Memory & context notes */}
      <Panel>
        <div className="flex items-center justify-between border-b border-aro-line-soft px-2.5 py-2">
          <span className="flex items-center gap-1.5 font-aro-mono text-aro-xs font-semibold tracking-[.14em] text-aro-ink-4 uppercase">
            <IconBrain className="text-aro-mint" size={10} /> Agent Memory
          </span>
        </div>
        <div className="p-2.5">
          <p className="text-xs leading-relaxed text-aro-ink-3">
            Persistent cross-session memories and learned context are injected automatically per turn.
          </p>
        </div>
      </Panel>
    </div>
  )
}

import { useStore } from '@nanostores/react'
import { useCallback } from 'react'

import { IconBranch, IconGit, IconPlus } from '@/aro/Icons'
import { Badge, Button, Panel } from '@/aro/ui'
import { cn } from '@/lib/utils'
import { openWorktreeDialog, repoStatusForCwd, repoWorktreesForCwd } from '@/store/coding-status'
import { openFolderAsProject } from '@/store/projects'
import { $focusedWorkspaceCwd } from '@/store/session-states'

export function GitSection() {
  const cwd = useStore($focusedWorkspaceCwd)
  const status = useStore(repoStatusForCwd(cwd))
  const worktrees = useStore(repoWorktreesForCwd(cwd))

  const handleOpenWorktreeDialog = useCallback(() => {
    void openWorktreeDialog({ repoPath: cwd || undefined })
  }, [cwd])

  const handleSwitchWorktree = useCallback((path: string) => {
    void openFolderAsProject(path)
  }, [])

  if (!status) {
    return (
      <div className="flex h-full min-h-[240px] flex-col items-center justify-center p-6 text-center">
        <div className="flex size-10 items-center justify-center rounded-overlay border border-aro-line-soft bg-aro-raise text-aro-ink-3 shadow-aro-e1">
          <IconGit size={18} />
        </div>
        <h3 className="mt-3 font-aro-display text-sm font-semibold text-aro-ink">No Git Repository</h3>
        <p className="mt-1 max-w-[220px] text-xs leading-relaxed text-aro-ink-3">
          Open a folder containing a Git repository to view branches, worktrees, and working tree changes.
        </p>
      </div>
    )
  }

  const branchName = status.detached ? 'HEAD (detached)' : status.branch || 'HEAD'
  const dirtyCount = (status.staged ?? 0) + (status.unstaged ?? 0)
  const ahead = status.ahead ?? 0
  const behind = status.behind ?? 0

  return (
    <div className="space-y-3 p-3">
      {/* Current branch status */}
      <Panel className="p-3">
        <div className="flex items-center gap-2">
          <IconBranch className="text-aro-iris-soft" size={13} />
          <span className="truncate font-aro-mono text-xs font-medium text-aro-iris-soft">
            {branchName}
          </span>
          <span className="ml-auto font-aro-mono text-[var(--aro-text-2xs,10px)] text-aro-ink-4">
            ↑{ahead} · ↓{behind}
          </span>
        </div>

        <div className="mt-2 flex items-center justify-between text-xs text-aro-ink-3">
          <span>
            {dirtyCount === 0 ? (
              <span className="text-aro-mint">Working tree clean</span>
            ) : (
              <span>
                {status.staged ?? 0} staged · {status.unstaged ?? 0} unstaged
              </span>
            )}
          </span>
          {dirtyCount > 0 && (
            <Badge className="text-[var(--aro-text-2xs,9px)]" mono tone="amber">
              {dirtyCount} modified
            </Badge>
          )}
        </div>

        <div className="mt-3 flex gap-1.5">
          <Button
            className="flex-1"
            icon={IconPlus}
            onClick={handleOpenWorktreeDialog}
            size="xs"
            variant="primary"
          >
            Branch / Worktree
          </Button>
        </div>
      </Panel>

      {/* Worktrees list */}
      <Panel>
        <div className="flex items-center justify-between border-b border-aro-line-soft px-2.5 py-2">
          <span className="font-aro-mono text-aro-xs font-semibold tracking-[.14em] text-aro-ink-4 uppercase">
            Worktrees
          </span>
          <Badge className="text-[var(--aro-text-2xs,9px)]" mono tone="neutral">
            {worktrees.length} total
          </Badge>
        </div>

        <div className="space-y-0.5 p-1">
          {worktrees.length === 0 ? (
            <div className="p-2 text-center font-aro-mono text-aro-xs text-aro-ink-4">
              Single checkout (main worktree)
            </div>
          ) : (
            worktrees.map(wt => {
              const isCurrent = cwd && wt.path.toLowerCase() === cwd.toLowerCase()
              const wtBranch = wt.branch || wt.path.split(/[\\/]+/).pop() || wt.path

              return (
                <div
                  className={cn(
                    'flex items-center gap-2 rounded-control px-2.5 py-1.5 text-left text-xs transition-colors',
                    isCurrent ? 'bg-aro-iris-tint/60 text-aro-ink' : 'text-aro-ink-2 hover:bg-aro-hover/60'
                  )}
                  key={wt.path}
                >
                  <IconBranch
                    className={cn('shrink-0', isCurrent ? 'text-aro-iris-soft' : 'text-aro-ink-4')}
                    size={11}
                  />
                  <div className="min-w-0 flex-1 truncate">
                    <span className="font-aro-mono font-medium">{wtBranch}</span>
                    {wt.isMain && (
                      <span className="ml-1.5 font-aro-mono text-[var(--aro-text-2xs,9px)] text-aro-ink-4">(main)</span>
                    )}
                  </div>
                  {isCurrent ? (
                    <Badge className="text-[8.5px]" mono tone="iris">
                      current
                    </Badge>
                  ) : (
                    <Button
                      className="h-5 px-1.5 text-[var(--aro-text-2xs,10px)]"
                      onClick={() => handleSwitchWorktree(wt.path)}
                      size="xs"
                      variant="ghost"
                    >
                      Open
                    </Button>
                  )}
                </div>
              )
            })
          )}
        </div>
      </Panel>
    </div>
  )
}

