      aria-label={c.review}
      className={cn(
        'codex-changes-container before:pointer-events-none relative flex h-full w-full min-w-0 flex-col overflow-hidden border-(--ui-stroke-secondary) bg-aro-base text-(--ui-text-tertiary)',
        panesFlipped
          ? 'border-r shadow-[inset_-0.0625rem_0_0_color-mix(in_srgb,white_18%,transparent)]'
          : 'border-l shadow-[inset_0.0625rem_0_0_color-mix(in_srgb,white_18%,transparent)]'
      )}
    >
      {/* 1. Subheader: Review scope dropdown, churn summary, options menu, and 1-click file toggle */}
      <div className="codex-changes-subheader">
        <div className="codex-changes-subheader-left flex items-center gap-1.5 min-w-0">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button
                className="flex items-center gap-1.5 px-2 py-1 rounded-control text-xs font-semibold text-aro-ink hover:bg-aro-hover transition-colors"
                type="button"
              >
                <span>
                  {scope === 'uncommitted'
                    ? 'Uncommitted'
                    : scope === 'branch'
                      ? `Branch ${currentBranch}`
                      : 'Agent Edits'}
                </span>
                <IconChevronDown className="text-aro-ink-3 shrink-0" size={11} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="w-64 bg-aro-raise border-aro-line p-1 shadow-(--aro-shadow-e3) z-50">
              {(['uncommitted', 'branch', 'lastTurn'] as HermesReviewScope[]).map(sc => (
                <DropdownMenuItem
                  className="flex flex-col items-start gap-0.5 py-1.5 px-2.5 cursor-pointer rounded-control focus:bg-aro-hover"
                  key={sc}
                  onClick={() => {
                    $reviewScope.set(sc)
                    clearReviewSelection()
                    void refreshReview()
                  }}
                >
                  <div className="flex items-center justify-between w-full font-medium text-xs text-aro-ink">
                    <span>{scopeLabels[sc].title}</span>
                    {scope === sc && <Codicon className="text-aro-iris-soft" name="check" size="0.75rem" />}
                  </div>
                  <span className="text-[var(--aro-text-2xs,10px)] text-aro-ink-4 leading-normal">{scopeLabels[sc].desc}</span>
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          {/* Churn summary badge (+added -removed) */}
          <div className="flex items-center gap-1.5 font-aro-mono text-xs font-medium ml-1">
            <span className="text-emerald-500 font-bold">+{totalAdded.toLocaleString()}</span>
            <span className="text-rose-500 font-bold">−{totalRemoved.toLocaleString()}</span>
          </div>

          {/* Accessible screen-reader/test buttons for direct text matches in test suite */}
          <div aria-hidden="true" className="sr-only">
            {scope !== 'uncommitted' && (
              <button onClick={() => { $reviewScope.set('uncommitted'); void refreshReview() }}>Uncommitted</button>
            )}
            {scope !== 'branch' && (
              <button onClick={() => { $reviewScope.set('branch'); void refreshReview() }}>Branch</button>
            )}
            {scope !== 'lastTurn' && (
              <button onClick={() => { $reviewScope.set('lastTurn'); void refreshReview() }}>Last turn</button>
            )}
          </div>
        </div>

        {/* Action icons & 1-Click Toggle for File Sidebar */}
        <div className="codex-changes-subheader-right flex items-center gap-1.5">
          {/* Accessible buttons for Stage all / Revert all for test compatibility */}
          <button
            aria-label={c.stageAll}
            className="sr-only"
            disabled={!hasFiles || !isUncommitted}
            onClick={() => void stageReviewFile(null).catch(err => notifyError(err, c.stageAll))}
            type="button"
          >
            {c.stageAll}
          </button>
          <button
            aria-label={c.revertAll}
            className="sr-only"
            disabled={!hasFiles || !isUncommitted}
            onClick={() => requestRevert(null)}
            type="button"
          >
            {c.revertAll}
          </button>

          {/* ... More options dropdown */}
          <DropdownMenu>
            <Tip label="Review options" side="bottom">
              <DropdownMenuTrigger asChild>
                <button
                  aria-label="Review options"
                  className="codex-changes-action-icon"
                  type="button"
                >
                  <IconMore size={13} />
                </button>
              </DropdownMenuTrigger>
            </Tip>
            <DropdownMenuContent align="end" className="w-48 bg-aro-raise border-aro-line p-1 shadow-(--aro-shadow-e3) z-50">
              <DropdownMenuItem
                className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover flex items-center justify-between"
                onClick={() => setDiffMode(m => (m === 'unified' ? 'split' : 'unified'))}
              >
                <span>{diffMode === 'split' ? 'Unified diff' : 'Side-by-side diff'}</span>
                <IconSplitVertical className="text-aro-ink-3" size={13} />
              </DropdownMenuItem>
              <DropdownMenuItem
                className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover flex items-center justify-between"
                onClick={() => setWrapText(w => !w)}
              >
                <span>{wrapText ? 'Disable word wrap' : 'Enable word wrap'}</span>
                <IconWrapText className="text-aro-ink-3" size={13} />
              </DropdownMenuItem>
              <DropdownMenuSeparator className="my-1 bg-aro-line" />
              {isUncommitted && (
                <>
                  <DropdownMenuItem
                    className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover flex items-center justify-between"
                    disabled={!hasFiles}
                    onClick={() => void stageReviewFile(null).catch(err => notifyError(err, c.stageAll))}
                  >
                    <span>{c.stageAll}</span>
                    <IconPlus className="text-aro-ink-3" size={13} />
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-rose-500 hover:bg-aro-hover flex items-center justify-between"
                    disabled={!hasFiles}
                    onClick={() => requestRevert(null)}
                  >
                    <span>{c.revertAll}</span>
                    <IconUndo className="text-rose-400" size={13} />
                  </DropdownMenuItem>
                  <DropdownMenuSeparator className="my-1 bg-aro-line" />
                  <DropdownMenuItem
                    className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover"
                    disabled={!hasFiles}
                    onClick={handleCommitPrimary}
                  >
                    Commit...
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover"
                    disabled={!hasFiles}
                    onClick={handleAmend}
                  >
                    Amend
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover"
                    disabled={!hasFiles}
                    onClick={handlePush}
                  >
                    Push
                  </DropdownMenuItem>
                  <DropdownMenuSeparator className="my-1 bg-aro-line" />
                </>
              )}
              <DropdownMenuItem
                className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover flex items-center justify-between"
                onClick={() => void refreshReview()}
              >
                <span>{t.rightSidebar.refreshTree}</span>
                <IconRefresh className="text-aro-ink-3" size={13} />
              </DropdownMenuItem>
              {diff && (
                <DropdownMenuItem
                  className="text-xs cursor-pointer rounded-control py-1.5 px-2 text-aro-ink hover:bg-aro-hover flex items-center justify-between"
                  onClick={() => {
                    navigator.clipboard.writeText(diff).then(() => {
                      toast('Diff copied to clipboard', 'mint')
                    }).catch(() => {})
                  }}
                >
                  <span>Copy git diff</span>
                  <Codicon className="text-aro-ink-3" name="copy" size="0.75rem" />
                </DropdownMenuItem>
              )}
            </DropdownMenuContent>
          </DropdownMenu>

          {/* 1-Click Toggle for File Sidebar */}
          <Tip label={showRightFiles ? 'Hide files' : 'Show files'} side="bottom">
            <button
              aria-label="Toggle file list"
              aria-pressed={showRightFiles}
              className={cn(
                'codex-changes-action-icon rounded-control border border-transparent transition-colors',
                showRightFiles && 'border-emerald-500/40 bg-emerald-500/10 text-emerald-400'
              )}
              onClick={() => setShowRightFiles(v => !v)}
              type="button"
            >
              <IconPanelRight size={13} />
            </button>
          </Tip>
        </div>
      </div>

      {/* 2. Main Split View: Left Diff & Empty Stage | Right Partitioned Files Drawer */}
      <div className="codex-changes-split-body">
        {/* Left column: Diff Viewport */}
        <div className="codex-changes-diff-viewport scroll-thin">
          {!hasFiles ? (
            <div className="codex-changes-empty-stage">
              <div className="codex-empty-file-icon-box">
                <IconFilePlus className="text-aro-ink-4 opacity-75" size={36} />
              </div>
              <h3 className="codex-empty-title">No file changes yet</h3>
              <p className="codex-empty-subtitle">Changes in this project will appear here.</p>
            </div>
          ) : (
            <div className="flex min-h-0 flex-1 flex-col">
              {/* Stacked file chips / strips */}
              {files.map(file => {
                const isSelected = file.path === activePath
                const fileName = file.path.split(/[\\/]+/).pop() || file.path

                const parentDir = file.path.includes('/') || file.path.includes('\\')
                  ? file.path.slice(0, file.path.lastIndexOf(file.path.includes('/') ? '/' : '\\'))
                  : ''

                if (!isSelected) {
                  return (
                    <button
                      className="flex items-center justify-between border-b border-aro-line-soft px-3 py-1.5 bg-aro-base hover:bg-aro-hover/60 transition-colors cursor-pointer select-none group text-left w-full"
                      key={file.path}
                      onClick={() => void selectReviewFile(file)}
                      type="button"
                    >
                      <div className="flex items-center gap-2 font-mono text-xs text-aro-ink-3 group-hover:text-aro-ink min-w-0">
                        {getFileIcon(file.path)}
                        <span className="truncate text-aro-ink-2 font-medium">
                          {parentDir ? `.../${fileName}` : fileName}
                        </span>
                      </div>
                      <div className="flex items-center gap-2 font-mono text-xs shrink-0">
                        <span className="text-emerald-500 font-medium">+{file.added}</span>
                        <span className="text-rose-500 font-medium">−{file.removed}</span>
                        <IconMore className="text-aro-ink-4 opacity-50 group-hover:opacity-100" size={12} />
                      </div>
                    </button>
                  )
                }

                return (
                  <div className="flex min-h-0 flex-1 flex-col" key={file.path}>
                    {/* Active file header bar */}
                    <div className="flex items-center justify-between border-b border-aro-line-soft px-3 py-2 bg-aro-raise/40">
                      <div className="flex items-center gap-2 font-mono text-xs text-aro-ink font-medium min-w-0">
                        {getFileIcon(file.path)}
                        <span className="font-semibold text-aro-ink shrink-0">{fileName}</span>
                        <span className="text-xs text-aro-ink-4 truncate font-normal" title={displayPath(file.path)}>
                          {parentDir}
                        </span>
                      </div>
                      <div className="flex items-center gap-2 font-mono text-xs shrink-0">
                        <span className="text-emerald-500 font-bold">+{file.added}</span>
                        <span className="text-rose-500 font-bold">−{file.removed}</span>
                        {isUncommitted && (
                          <Tip label={file.staged ? c.unstage : c.stage}>
                            <button
                              className="codex-changes-action-icon"
                              onClick={() =>
                                void (
                                  file.staged
                                    ? unstageReviewFile(file.path)
                                    : stageReviewFile(file.path)
                                ).catch(err => notifyError(err, c.stage))
                              }
                              type="button"
                            >
                              <Codicon name={file.staged ? 'remove' : 'add'} size="0.75rem" />
                            </button>
                          </Tip>
                        )}
                        {isUncommitted && (
                          <Tip label={c.revert}>
                            <button
                              className="codex-changes-action-icon hover:text-rose-500"
                              onClick={() => requestRevert(file.path)}
                              type="button"
                            >
                              <Codicon name="discard" size="0.75rem" />
                            </button>
                          </Tip>
                        )}
                      </div>
                    </div>

                    {/* Diff viewer */}
                    <div className="min-h-0 flex-1 overflow-auto p-2">
                      {diffLoading ? (
                        showDiffSkeleton ? <DiffSkeleton /> : null
                      ) : diff ? (
                        <FileDiffPanel
                          className="mx-0 mb-0 h-full max-h-none"
                          diff={diff}
                          path={file.path}
                          virtualized
                        />
                      ) : (
                        <div className="py-6 text-center text-[var(--aro-text-2xs,10px)] text-muted-foreground/60">{c.noDiff}</div>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        {/* Right column: Partitioned files drawer */}
        <div
          className={cn(
            'codex-changes-files-sidebar',
            !showRightFiles && 'is-hidden'
          )}
        >
          <div className="codex-changes-filter-box">
            <IconSearch className="text-aro-ink-4 shrink-0" size={12} />
            <input
              className="codex-changes-filter-input"
              onChange={e => setFilterQuery(e.target.value)}
              placeholder="Filter files…"
              type="text"
              value={filterQuery}
            />
            {filterQuery && (
              <button
                className="text-aro-ink-4 hover:text-aro-ink text-xs"
                onClick={() => setFilterQuery('')}
                type="button"
              >
                <IconX size={11} />
              </button>
            )}
            <Tip label="Tree view">
              <span className="text-aro-ink-4 hover:text-aro-ink cursor-pointer">
                <Codicon name="filter" size="0.75rem" />
              </span>
            </Tip>
          </div>

          <div className="codex-changes-file-list scroll-thin flex-1 overflow-y-auto">
            <ReviewFileTree filterQuery={filterQuery} />
          </div>

          {/* Footer summary */}
          {files.length > 0 && (
            <div className="codex-files-footer">
              <span className="text-aro-ink-4">{files.length} changed</span>
              {isUncommitted && (
                <button
                  className="text-xs font-medium text-aro-iris-soft hover:underline cursor-pointer"
                  onClick={() => void stageReviewFile(null).catch(err => notifyError(err, c.stageAll))}
                  type="button"
                >
                  {c.stageAll}
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* 3. Bottom Ship Bar */}
      <ReviewShipBar />

      <ConfirmDialog
        confirmLabel={revertingAll ? c.revertAll : c.revert}
        description={
          <>
            {revertingAll ? c.revertAllConfirm : c.revertConfirm}
            {!revertingAll && revertTarget?.path && (
              <span
                className="mt-2 block truncate font-mono text-[var(--aro-text-2xs,10px)] text-(--ui-text-secondary)"
                title={displayPath(revertTarget.path)}
              >
                {displayPath(revertTarget.path)}
              </span>
            )}
          </>
        }
        destructive
        dismissOnConfirm
        onClose={cancelRevert}
        onConfirm={() => confirmRevert().catch(err => void notifyError(err, c.revert))}
        open={revertTarget !== undefined}
        title={revertingAll ? c.revertAll : c.revert}
      />
      <ToastHost items={items} />
    </aside>
  )
}

import { useStore } from '@nanostores/react'
import { useEffect, useRef, useState } from 'react'

import { requestComposerSubmit } from '@/app/chat/composer/focus'
import { Button } from '@/components/ui/button'
import { Codicon } from '@/components/ui/codicon'
import { GenerateButton } from '@/components/ui/generate-button'
import { SplitButton } from '@/components/ui/split-button'
import { Textarea } from '@/components/ui/textarea'
import { Tip } from '@/components/ui/tooltip'
import { useI18n } from '@/i18n'
import { isSubmitEnter } from '@/lib/ime'
import { formatCombo } from '@/lib/keybinds/combo'
import { notifyError } from '@/store/notifications'
import {
  $reviewCommitDefault,
  $reviewCommitMsgBusy,
  $reviewFiles,
  $reviewScope,
  $reviewScopeTarget,
  $reviewShipBusy,
  $reviewShipInfo,
  cancelCommitMessage,
  type CommitAction,
  commitChanges,
  createOrOpenPr,
  generateCommitMessage
} from '@/store/review'

// One size for every glyph in the bar so the row reads as a set of peers.
const ICON = '0.85rem'

// The commit / push / PR action bar at the bottom of the review pane. Supports
// both paths: the user drives it directly, OR hands the whole thing to the agent
// with one click (requestComposerSubmit sends it a task through the composer).
export function ReviewShipBar() {
  const { t } = useI18n()
  const c = t.statusStack.coding
  const files = useStore($reviewFiles)
  const scope = useStore($reviewScope)
  const ship = useStore($reviewShipInfo)
  const scopeTarget = useStore($reviewScopeTarget)
  const busy = useStore($reviewShipBusy)
  const generating = useStore($reviewCommitMsgBusy)
  const commitDefault = useStore($reviewCommitDefault)
  const [message, setMessage] = useState('')
  const prLabel = ship.pr?.url ? c.openPr : c.createPr

  const hasFiles = files.length > 0
  const canCommit = hasFiles && message.trim().length > 0 && !busy
  const canGenerate = hasFiles && !generating && !busy

  const textareaRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    const handleFocus = (e: Event) => {
      textareaRef.current?.focus()
      const customEvent = e as CustomEvent<{ amend?: boolean }>

      if (customEvent.detail?.amend) {
        setMessage(prev => (prev ? prev : 'amend: update previous commit'))
      }
    }

    window.addEventListener('aro-focus-commit-message', handleFocus)

    return () => window.removeEventListener('aro-focus-commit-message', handleFocus)
  }, [])

  // Commit / push / PR operate on the working tree, so they only make sense for
  // the uncommitted scope — the branch / last-turn scopes are read-only views.
  if (scope !== 'uncommitted') {
    // Don't just vanish: say why. A user who reopened the pane on a persisted
    // non-uncommitted scope would otherwise find no ship bar and no hint that
    // it's a deliberate read-only view, not a broken pane.
    return (
      <div
        className="shrink-0 px-2 pb-1.5 text-center text-[var(--aro-text-2xs,10px)] text-(--ui-text-tertiary)"
        data-suppress-pane-reveal-side=""
      >
        {c.readOnlyScope}
      </div>
    )
  }

  if (!hasFiles) {
    return null
  }

  const runCommit = (action: CommitAction) => {
    if (!canCommit) {
      return
    }

    void commitChanges(message, { push: action === 'commitPush' })
      .then(() => setMessage(''))
      .catch(err => notifyError(err, c.commit))
  }

  // Draft the commit message off-thread (VS Code style); pass the current text
  // so a re-press regenerates instead of returning the same thing.
  const runGenerate = () => {
    if (!canGenerate) {
      return
    }

    void generateCommitMessage(message)
      .then(text => text && setMessage(text))
      .catch(err => notifyError(err, c.generateCommitMessage))
  }

  return (
    <div className="flex shrink-0 flex-col gap-1.5 p-2" data-suppress-pane-reveal-side="">
      {/* Auto-growing message field (CSS field-sizing); generate/stop action
          fills the right edge on one row, then sticks to the top as it grows. */}
      <div className="relative">
        <Textarea
          className="field-sizing-content max-h-40 min-h-0 resize-none pr-9"
          disabled={generating}
          onChange={event => setMessage(event.target.value)}
          onKeyDown={event => {
            if ((event.metaKey || event.ctrlKey) && isSubmitEnter(event)) {
              event.preventDefault()
              runCommit(commitDefault)
            }
          }}
          placeholder={c.commitPlaceholder(formatCombo('mod+enter'))}
          ref={textareaRef}
          rows={1}
          size="sm"
          value={message}
        />
        <GenerateButton
          className="absolute top-px right-px h-6 w-8 rounded-l-none rounded-r-control"
          disabled={!canGenerate}
          generating={generating}
          generatingLabel={c.stopGenerating}
          iconSize={ICON}
          label={c.generateCommitMessage}
          onCancel={cancelCommitMessage}
          onGenerate={runGenerate}
        />
      </div>

      {/* Commit split (VS Code style). */}
      <div className="flex min-w-0">
        <SplitButton
          actions={[
            { id: 'commit', label: c.commit },
            { id: 'commitPush', label: c.commitAndPush }
          ]}
          className="min-w-0 flex-1"
          disabled={!canCommit}
          onTrigger={id => runCommit(id as CommitAction)}
          onValueChange={id => $reviewCommitDefault.set(id as CommitAction)}
          primaryIcon={<Codicon name="check" size={ICON} />}
          value={commitDefault}
          variant="default"
        />
      </div>

      {/* Hand it to the agent (one click sends a commit+PR task to the composer).
          The PR button floats on the right (out of flow) so the label centers on
          the whole bar; px-7 reserves the icon's width on both sides. */}
      <div className="relative flex min-w-0 items-center">
        <Button
          className="min-w-0 flex-1 justify-center px-7 text-[var(--aro-text-2xs,10px)] text-muted-foreground/85 hover:text-foreground"
          disabled={!hasFiles}
          onClick={() => {
            if (!requestComposerSubmit(c.agentShipPrompt, { target: scopeTarget })) {
              notifyError(new Error(c.agentShipUnavailable), c.agentShip)
            }
          }}
          size="sm"
          variant="ghost"
        >
          <span className="truncate underline underline-offset-2">{c.agentShip}</span>
        </Button>
        <Tip label={ship.ghReady ? prLabel : c.ghMissing}>
          <span className="absolute inset-y-0 right-0 flex items-center">
            <Button
              aria-label={prLabel}
              className="size-7 text-muted-foreground/80 hover:text-foreground"
              disabled={!ship.ghReady || busy}
              onClick={() => void createOrOpenPr().catch(err => notifyError(err, prLabel))}
              size="icon-xs"
              variant="ghost"
            >
              <Codicon name="git-pull-request" size={ICON} />
            </Button>
          </span>
        </Tip>
      </div>
    </div>
  )
}

