        requestGateway={requestGateway}
        storedSessionId={focusedSessionId}
      />
    )

    await handle!.submitText('/approvals off')

    expect(requestGateway).toHaveBeenCalledWith('slash.exec', {
      command: 'approvals off',
      session_id: focusedSessionId
