  it('reports the exact accepted identity through onAccepted after a stale-runtime recovery', async () => {
    const STORED_SESSION_ID = 'stored-db-xyz789'
    const RECOVERED_SESSION_ID = 'rt-recovered-456'
    let submitAttempts = 0

