  // A saved cloud connection on a local-primary device has exactly one
  // recovery when its gateway session lapses: the silent portal cascade. The
  // dial's error copy sends the user to Settings → Gateways, so the "Use
  // gateway" action there must run that cascade and retry the switch — a
  // plain reauth failure toast would point at a page that cannot help.
  describe('saved cloud gateway re-auth', () => {
    const reauthError = new GatewayReauthRequiredError(
      'Reached the gateway over HTTP, but the OAuth session was rejected while minting a WebSocket ticket.'
    )

    const saved = {
      id: 'saved-a',
      kind: 'cloud',
      label: 'Research',
      url: 'https://a.example',
      authMode: 'oauth'
    }

    const mountCloudPanelWith = (cloud: Record<string, unknown>) => {
      getConnectionConfig.mockResolvedValue({ ...localConnection, mode: 'cloud', remoteUrl: saved.url })
      registry.value = { connections: [saved] }
      Object.assign(window.hermesDesktop, { cloud })
    }

    it('re-signs a lapsed saved gateway session via the portal cascade and retries the switch', async () => {
      mountCloudPanelWith({
        status: vi.fn().mockResolvedValue({ signedIn: true }),
        login: vi.fn(),
        agentSignIn: vi.fn().mockResolvedValue({ connected: true })
      })
      const oauthLogoutConnectionConfig = vi.fn().mockResolvedValue({ ok: true })
      Object.assign(window.hermesDesktop, { oauthLogoutConnectionConfig })
      selectConnection.mockRejectedValueOnce(reauthError).mockResolvedValueOnce(undefined)

      render(<GatewaySettings embedded />)
      const row = (await screen.findByText('Research')).closest('[data-slot]') as HTMLElement
      fireEvent.click(within(row).getByRole('button', { name: 'Use gateway' }))

      await waitFor(() => expect(selectConnection).toHaveBeenCalledTimes(2))
      expect(selectConnection).toHaveBeenNthCalledWith(1, saved.id)
      expect(selectConnection).toHaveBeenNthCalledWith(2, saved.id)
      expect(oauthLogoutConnectionConfig).toHaveBeenCalledWith(saved.url)
      expect(window.hermesDesktop!.cloud!.agentSignIn).toHaveBeenCalledWith(saved.url)
      // The portal session was already live: no interactive portal login.
      expect(window.hermesDesktop!.cloud!.login).not.toHaveBeenCalled()
      registry.value = null
    })

    it('fails closed instead of cascading against an empty saved dashboard URL', async () => {
      const savedWithoutUrl = {
        id: 'saved-without-url',
        kind: 'cloud',
        label: 'Incomplete',
        authMode: 'oauth'
      }

      getConnectionConfig.mockResolvedValue({ ...localConnection, mode: 'cloud', remoteUrl: '' })
      registry.value = { connections: [savedWithoutUrl] }
      const agentSignIn = vi.fn()
      const oauthLogoutConnectionConfig = vi.fn()
      Object.assign(window.hermesDesktop, {
        oauthLogoutConnectionConfig,
        cloud: {
          status: vi.fn().mockResolvedValue({ signedIn: true }),
          login: vi.fn(),
          agentSignIn
        }
      })
      selectConnection.mockRejectedValueOnce(reauthError)

      render(<GatewaySettings embedded />)
      const row = (await screen.findByText('Incomplete')).closest('[data-slot]') as HTMLElement
      fireEvent.click(within(row).getByRole('button', { name: 'Use gateway' }))

      await waitFor(() => expect(selectConnection).toHaveBeenCalledTimes(1))
      expect(oauthLogoutConnectionConfig).not.toHaveBeenCalled()
      expect(agentSignIn).not.toHaveBeenCalled()
      registry.value = null
    })

    it('does not cascade for a non-reauth switch failure', async () => {
      mountCloudPanelWith({
        status: vi.fn().mockResolvedValue({ signedIn: true }),
        login: vi.fn(),
        agentSignIn: vi.fn()
      })
      const oauthLogoutConnectionConfig = vi.fn()
      Object.assign(window.hermesDesktop, { oauthLogoutConnectionConfig })
      selectConnection.mockRejectedValueOnce(new Error('Timed out connecting to "Research".'))

      render(<GatewaySettings embedded />)
      const row = (await screen.findByText('Research')).closest('[data-slot]') as HTMLElement
      fireEvent.click(within(row).getByRole('button', { name: 'Use gateway' }))

      await waitFor(() => expect(selectConnection).toHaveBeenCalledTimes(1))
      expect(oauthLogoutConnectionConfig).not.toHaveBeenCalled()
      expect(window.hermesDesktop!.cloud!.agentSignIn).not.toHaveBeenCalled()
      registry.value = null
    })

    it('signs into the portal first when that session has lapsed too', async () => {
      mountCloudPanelWith({
        status: vi.fn().mockResolvedValue({ signedIn: false }),
        login: vi.fn().mockResolvedValue({ ok: true, signedIn: true }),
        agentSignIn: vi.fn().mockResolvedValue({ connected: true })
      })
      const oauthLogoutConnectionConfig = vi.fn().mockResolvedValue({ ok: true })
      Object.assign(window.hermesDesktop, { oauthLogoutConnectionConfig })
      selectConnection.mockRejectedValueOnce(reauthError).mockResolvedValueOnce(undefined)

      render(<GatewaySettings embedded />)
      const row = (await screen.findByText('Research')).closest('[data-slot]') as HTMLElement
      fireEvent.click(within(row).getByRole('button', { name: 'Use gateway' }))

      await waitFor(() => expect(selectConnection).toHaveBeenCalledTimes(2))
      expect(window.hermesDesktop!.cloud!.login).toHaveBeenCalledTimes(1)
      expect(window.hermesDesktop!.cloud!.agentSignIn).toHaveBeenCalledWith(saved.url)
      registry.value = null
    })
  })

  it('opens a focused, typeable custom SSH host input on the first "Custom" selection', async () => {
    getConnectionConfig.mockResolvedValue({
      ...localConnection,
      mode: 'ssh',
      sshHost: '',
      sshUser: '',
      sshPort: 22,
      sshKeyPath: '',
      sshRemoteHermesPath: '',
      sshRemoteProfile: ''
    })
    const sshConfigHosts = vi.fn().mockResolvedValue({ hosts: ['github.com'] })
    Object.assign(window.hermesDesktop, { sshConfigHosts })

    render(<GatewaySettings />)

    // With ~/.ssh/config aliases available the host field is a dropdown.
    fireEvent.click(await screen.findByRole('combobox'))
    fireEvent.click(screen.getByRole('option', { name: 'Custom (enter manually)…' }))

    // The FIRST pick swaps the dropdown for a free-text input, no round-trip
    // through another option needed.
    const hostRow = screen.getByText('Host').closest('.grid') as HTMLElement
    const input = within(hostRow).getByRole('textbox') as HTMLInputElement

    await waitFor(() => expect(document.activeElement).toBe(input))
    fireEvent.change(input, { target: { value: 'build-box' } })
    expect(input.value).toBe('build-box')

    // Clearing it and leaving the field backs out of Custom to the dropdown.
    fireEvent.change(input, { target: { value: '' } })
    fireEvent.blur(input)
    expect(await within(hostRow).findByRole('combobox')).toBeTruthy()
    expect(within(hostRow).queryByRole('textbox')).toBeNull()
  })
})

import { useCallback, useEffect, useRef, useState } from 'react'

import { Button } from '@/components/ui/button'
import { useI18n } from '@/i18n'
import { notifyError } from '@/store/notifications'

import { ToggleRow } from './primitives'

export function MinimizeToTraySetting() {
  const { t } = useI18n()
  const c = t.settings.config
  const bridge = window.hermesDesktop?.minimizeToTray
  const [status, setStatus] = useState<{ enabled: boolean; available: boolean } | null>(null)
  const [saving, setSaving] = useState(false)
  const [loadFailed, setLoadFailed] = useState(false)
  const revision = useRef(0)

  const load = useCallback(async () => {
    if (!bridge) {
      return
    }

    const version = ++revision.current
    setLoadFailed(false)

    try {
      const next = await bridge.get()

      if (revision.current === version) {
        setStatus(next)
      }
    } catch (error) {
      if (revision.current === version) {
        setLoadFailed(true)
        notifyError(error, c.failedLoad)
      }
    }
  }, [bridge, c.failedLoad])

  useEffect(() => {
    if (!bridge) {
      return
    }

    const unsubscribe = bridge.onChanged(next => {
      revision.current++
      setStatus(next)
      setLoadFailed(false)
    })

    void load()

    return () => {
      revision.current++
      unsubscribe()
    }
  }, [bridge, load])

  if (!bridge) {
    return null
  }

  const save = async (enabled: boolean) => {
    const previous = status
    const version = ++revision.current
    setSaving(true)
    setStatus({ enabled, available: status?.available ?? false })

    try {
      const next = await bridge.set(enabled)

      if (revision.current === version) {
        setStatus(next)
      }
    } catch (error) {
      if (revision.current === version) {
        setStatus(previous)
      }

      notifyError(error, c.autosaveFailed)
    } finally {
      setSaving(false)
    }
  }

  return (
    <>
      <ToggleRow
        checked={status?.enabled ?? false}
        description={
          status?.enabled && !status.available && !saving ? c.minimizeToTrayUnavailable : c.minimizeToTrayDesc
        }
        disabled={!status || saving}
        label={c.minimizeToTrayTitle}
        onChange={enabled => void save(enabled)}
      />
      {loadFailed && (
        <Button onClick={() => void load()} size="sm" variant="secondary">
          {t.settings.screenshot.retry}
        </Button>
      )}
    </>
  )
}

// @vitest-environment jsdom
import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { atom } from 'nanostores'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import type { ProfileInfo } from '@/types/hermes'

// Keep store/profile's side-effecting imports inert — same seam as
// store/profile.test.ts / profile-tag.test.tsx.
vi.mock('@/store/gateway', () => ({
  $gateway: atom<unknown>(null),
  ensureGatewayForAgent: vi.fn(async () => undefined),
  ensureGatewayForProfile: vi.fn(async () => undefined),
  openGatewayForProfile: vi.fn(async () => undefined)
}))
vi.mock('@/hermes', () => ({
  getProfiles: vi.fn(async () => ({ profiles: [] })),
  setApiRequestProfile: vi.fn()
}))
vi.mock('@/lib/query-client', () => ({ invalidateProfileScopedQueries: vi.fn() }))
vi.mock('@/store/starmap', () => ({ resetStarmapGraph: vi.fn() }))

const { $activeGatewayProfile, $profiles } = await import('@/store/profile')
const { $settingsScopeOverride } = await import('@/store/settings-scope')
const { ActiveProfileNote, SettingsProfileScope } = await import('./profile-scope')

const profile = (name: string, isDefault = false, extra: Partial<ProfileInfo> = {}): ProfileInfo =>
  ({ has_env: false, is_default: isDefault, model: null, name, ...extra }) as ProfileInfo

beforeEach(() => {
  $activeGatewayProfile.set('default')
  $settingsScopeOverride.set(null)
  $profiles.set([])
})

afterEach(cleanup)

describe('SettingsProfileScope', () => {
  it('renders nothing with fewer than two profiles', () => {
    $profiles.set([profile('default', true)])

    const { container } = render(<SettingsProfileScope />)
    expect(container.textContent).toBe('')
  })

  it('selecting another profile sets the shared override; re-selecting the active clears it', () => {
    $profiles.set([profile('default', true), profile('coder')])

    render(<SettingsProfileScope />)

    fireEvent.click(screen.getByRole('button', { name: 'coder' }))
    expect($settingsScopeOverride.get()).toBe('coder')

    fireEvent.click(screen.getByRole('button', { name: 'default' }))
    expect($settingsScopeOverride.get()).toBeNull()
  })

  // #89190/#89162 class: after opening a Bot Mode chat, the ACTIVE profile is
  // the bot's — so with no override the settings pages silently edit the bot's
  // config. The target must be stated (accented) whenever it isn't the default
  // profile, override or not.
  it('states the edit target when the active profile is a non-default bot (no override)', () => {
    $activeGatewayProfile.set('scout')
    $profiles.set([profile('default', true), profile('scout')])

    const { container } = render(<SettingsProfileScope />)

    expect($settingsScopeOverride.get()).toBeNull()
    expect(container.textContent).toContain('scout')
    // The note is present and flagged loud (data-scope-loud marks the accented variant).
    const note = container.querySelector('[role="status"]')
    expect(note).toBeTruthy()
    expect(note?.getAttribute('data-scope-loud')).toBe('true')
  })

  it('shows no note when following the active DEFAULT profile', () => {
    $activeGatewayProfile.set('default')
    $profiles.set([profile('default', true), profile('coder')])

    const { container } = render(<SettingsProfileScope />)

    expect(container.querySelector('[role="status"]')).toBeNull()
  })

  it('keeps the quiet note style for an explicit override onto the default profile', () => {
    $activeGatewayProfile.set('scout')
    $profiles.set([profile('default', true), profile('scout')])

    render(<SettingsProfileScope />)

    fireEvent.click(screen.getByRole('button', { name: 'default' }))
    expect($settingsScopeOverride.get()).toBe('default')

    const note = document.querySelector('[role="status"]')
    expect(note).toBeTruthy()
    expect(note?.hasAttribute('data-scope-loud')).toBe(false)
  })

  it('labels chips with the bot title, else the display name, else the slug', () => {
    $profiles.set([
      profile('default', true, { bot_title: 'JordyV', display_name: 'JordieF' }),
      profile('default-2', false, { display_name: 'Copy' }),
      profile('weather-man')
    ])

    render(<SettingsProfileScope />)

    // Bot Mode title wins over display_name and the slug — same identity the
    // Bots roster shows.
    expect(screen.getByRole('button', { name: 'JordyV' })).toBeTruthy()
    // display_name (profile.yaml) when no Bot Mode title exists.
    expect(screen.getByRole('button', { name: 'Copy' })).toBeTruthy()
    // Canonical slug when neither is set.
    expect(screen.getByRole('button', { name: 'weather-man' })).toBeTruthy()
  })

  it('keeps selection keyed on the canonical name while showing the presentation label', () => {
    $profiles.set([profile('default', true), profile('coder', false, { bot_title: 'JordyV' })])

    render(<SettingsProfileScope />)

    fireEvent.click(screen.getByRole('button', { name: 'JordyV' }))
    // The label changed, the identity did not: the override stores the slug.
    expect($settingsScopeOverride.get()).toBe('coder')
    // The "applies to" note names the target the way its chip does.
    expect(document.querySelector('[role="status"]')?.textContent).toContain('JordyV')
    expect(document.querySelector('[role="status"]')?.textContent).not.toContain('coder')
  })
})

// Local Models sends unscoped requests, so it always edits the ACTIVE profile;
// the note must say which one — and stay silent for single-profile users, like
// the selector.
describe('ActiveProfileNote', () => {
  it('names the active profile (by its chip label) only with two or more profiles', () => {
    $activeGatewayProfile.set('setup')
    $profiles.set([profile('default', true)])
    const { container, rerender } = render(<ActiveProfileNote />)
    expect(container.textContent).toBe('')

    $profiles.set([profile('default', true), profile('setup', false, { display_name: 'Setup box' })])
    rerender(<ActiveProfileNote />)
    expect(screen.getByRole('status').textContent).toContain('Setup box')
    expect($settingsScopeOverride.get()).toBeNull()
  })
})

