/** Overlay count on a titlebar glyph. Hidden when count is 0/undefined. */
function withCountBadge(icon: ReactNode, count: number | undefined): ReactNode {
  if (!count) {
    return icon
  }

  return (
    <span className="relative inline-flex">
      {icon}
      <span className="pointer-events-none absolute -top-2.5 -right-1.5 z-1">
        <Badge aria-hidden size="overlay" variant="solid">
          {compactNumber(count)}
        </Badge>
      </span>
    </span>
  )
}

/** Live ⌘/Ctrl tracking — mod-click affordances telegraph themselves (the
 *  layout button morphs into its reset form while the modifier is down). */
function useModifierHeld(): boolean {
  const [held, setHeld] = useState(false)

  useEffect(() => {
    const sync = (event: KeyboardEvent) => setHeld(event.metaKey || event.ctrlKey)
    const clear = () => setHeld(false)

    window.addEventListener('keydown', sync)
    window.addEventListener('keyup', sync)
    window.addEventListener('blur', clear)

    return () => {
      window.removeEventListener('keydown', sync)
      window.removeEventListener('keyup', sync)
      window.removeEventListener('blur', clear)
    }
  }, [])

  return held
}

export function TitlebarControls({ leftTools = [], tools = [], onOpenSettings }: TitlebarControlsProps) {
  const { t } = useI18n()
  const navigate = useNavigate()
  const location = useLocation()
  const modHeld = useModifierHeld()
  const fileBrowserOpen = useStore($fileBrowserOpen)
  const leftSideOpen = useStore($leftSideOpen)
  const panesFlipped = useStore($panesFlipped)
  const unreadCount = useStore($unreadSessionCount)
  const appActionsSide = useStore($titlebarAppActionsSide)
  const interfaceMode = useStore($interfaceMode)
  const unreadBadge = unreadCount > 0 ? unreadCount : undefined
  const unreadHint = unreadBadge ? ` · ${t.titlebar.unreadSessions(unreadBadge)}` : ''
  // One filter for every cluster: a tool's own `hidden`, then the mode's tier.
  const shown = shownInMode(interfaceMode)
  const visibleTool = (tool: TitlebarTool) => !tool.hidden && shown(tool)

  // `titleBar.*` slot content is mount-scoped — a page's <Contribute> registers
  // only while that surface is up — so a non-empty area means a page is
  // actively projecting chrome into the band right now.
  const titleBarLeft = useContributions('titleBar.left')
  const titleBarRight = useContributions('titleBar.right')
  const pageOwnsTitlebar = titleBarLeft.length + titleBarRight.length > 0

  // POSITIONAL toggles: each button shows/hides everything on its physical
  // side of the main zone (the layout tree collapses the whole side), so they
  // stay correct through flips and rearranges. Both edges resolve their column
  // from the live tree (see toggleLeftSide / toggleRightSide) — the browser
  // column, the sessions column, whatever is physically left / right. Never an
  // active highlight — plain show/hide affordances.
  const leftEdge = { open: leftSideOpen, toggle: toggleLeftSide }
  const rightEdge = { open: fileBrowserOpen, toggle: toggleRightSide }
  const leftLabel = leftEdge.open ? t.titlebar.hideSidebar : t.titlebar.showSidebar
  const rightLabel = rightEdge.open ? t.titlebar.hideRightSidebar : t.titlebar.showRightSidebar

  const sidebarTool: TitlebarTool = {
    ...TITLEBAR_FIXED_TOOLS.sidebar,
    actionId: 'view.toggleSidebar',
    badge: panesFlipped ? undefined : unreadBadge,
    icon: <TitlebarIcon name="layout-sidebar-left" />,
    id: 'sidebar',
    label: `${leftLabel}${panesFlipped ? '' : unreadHint}`,
    onSelect: () => {
      triggerHaptic('tap')
      leftEdge.toggle()
    }
  }

  const flipTool: TitlebarTool = {
    ...TITLEBAR_FIXED_TOOLS['flip-panes'],
    actionId: 'view.flipPanes',
    icon: <TitlebarIcon name="arrow-swap" />,
    id: 'flip-panes',
    label: t.titlebar.swapSidebarSides,
    onSelect: () => {
      triggerHaptic('tap')
      togglePanesFlipped()
    }
  }

  const rightSidebarTool: TitlebarTool = {
    ...TITLEBAR_FIXED_TOOLS['right-sidebar'],
    actionId: 'view.toggleRightSidebar',
    badge: panesFlipped ? unreadBadge : undefined,
    icon: <TitlebarIcon name="layout-sidebar-right" />,
    id: 'right-sidebar',
    label: `${rightLabel}${panesFlipped ? unreadHint : ''}`,
    onSelect: () => {
      triggerHaptic('tap')
      rightEdge.toggle()
    },
    tour: 'right-pane-toggle'
  }

  // Static system tools — always pinned to the screen's right edge so the
  // left titlebar stays free for tabs (#107351).
  const systemTools: TitlebarTool[] = [
    {
      ...TITLEBAR_FIXED_TOOLS.settings,
      actionId: 'nav.settings',
      icon: <TitlebarIcon name="settings-gear" />,
      id: 'settings',
      label: t.titlebar.openSettings,
      onSelect: () => {
        triggerHaptic('open')
        onOpenSettings()
      }
    },
    {
      ...TITLEBAR_FIXED_TOOLS.layout,
      className: 'group/tool',
      // Hover + held ⌘/Ctrl morphs the glyph into its reset form (see
      // LayoutGlyph) — the mod-click telegraphs itself before it happens.
      icon: <LayoutGlyph modHeld={modHeld} />,
      id: 'layout',
      label: t.titlebar.layoutEditor,
      onSelect: event => {
        if (event?.metaKey || event?.ctrlKey) {
          triggerHaptic('warning')
          resetLayoutTree()

          return
        }

        triggerHaptic('open')
        toggleLayoutEditMode()
      },
      title: t.titlebar.layoutEditorTitle(formatModifierToken('mod'))
    },
    {
      ...TITLEBAR_FIXED_TOOLS.hud,
      // No `title`: TitlebarToolButton passes `title` to TipKeybindLabel as a
      // text OVERRIDE, so a long sentence there replaces the short label and
      // crowds the ⌘⇧H hint off the tooltip. Label only — the hint is appended
      // from the action registry, same as every other tool here.
      actionId: 'view.toggleHud',
      icon: <TitlebarIcon name="comment-discussion" />,
      id: 'hud',
      label: t.titlebar.enterHud,
      onSelect: () => {
        triggerHaptic('open')
        toggleHud(hudTargetSessionId())
      }
    }
  ]

  const view = appViewForPath(location.pathname)

  // Route changes can replace measured clusters without resizing the panels.
  useEffect(() => {
    window.dispatchEvent(new CustomEvent(TITLEBAR_CHROME_CHANGED_EVENT))
  }, [location.pathname, pageOwnsTitlebar])

  // Overlays own the window. These clusters are `fixed` at a higher z-index
  // than the overlay card, so they'd otherwise bleed over it — hide them (and
  // the nested titleBar slots) and let the overlay's own chrome take over.
  if (isOverlayView(view)) {
    return null
  }

  const leftClusterClass = cn(
    titlebarToolClusterClass,
    'left-(--titlebar-controls-left) top-(--titlebar-controls-top) translate-y-(--titlebar-controls-y-nudge)'
  )

  // A contributed full page (`extension`) yields the fixed clusters only while
  // it actually projects chrome into the band — page-mounted `titleBar.*` slots
  // like kanban's board switcher. A page that mounts no titlebar chrome keeps
  // the app's controls; an empty claim would leave a bare strip on every plugin
  // route. Contributed `titleBar.tools` items keep rendering here too, so a
  // chrome-owning page never silently drops a registered item.
  if (hidesFixedTitlebarClusters(view) && pageOwnsTitlebar) {
    const pageTools = [...leftTools, ...tools].filter(visibleTool)

    // Both markers are required even when a page contributes to only one side.
    return (
      <>
        <div className={leftClusterClass} data-titlebar-cluster="left">
          {pageTools.map(tool => (
            <TitlebarToolButton key={tool.id} navigate={navigate} tool={tool} />
          ))}
          <Slot area="titleBar.left" />
        </div>
        <div
          className={cn(titlebarToolClusterClass, 'right-(--titlebar-tools-right) top-(--titlebar-controls-top)')}
          data-titlebar-cluster="right"
        >
          <Slot area="titleBar.right" />
        </div>
      </>
    )
  }

  const visibleLeftTools = (
    appActionsSide === 'left' ? [sidebarTool, ...systemTools, ...leftTools] : [sidebarTool, ...leftTools]
  ).filter(visibleTool)

  const visibleSystemTools = appActionsSide === 'right' ? systemTools.filter(visibleTool) : []
  const visiblePaneTools = tools.filter(visibleTool)
  const visibleRightFixedTools = [flipTool, rightSidebarTool].filter(visibleTool)

  return (
    <>
      <div aria-label={t.shell.windowControls} className={leftClusterClass} data-titlebar-cluster="left">
        {visibleLeftTools.map(tool => (
          <TitlebarToolButton key={tool.id} navigate={navigate} tool={tool} />
        ))}
        <Slot area="titleBar.left" />
        <Slot area="titleBar.center" />
      </div>

      {visiblePaneTools.length > 0 && (
        <div
          aria-label={t.shell.appControls}
          className={cn(
            titlebarToolClusterClass,
            'top-[calc(var(--titlebar-controls-top)+var(--right-rail-top-inset,0px))] right-[calc(var(--titlebar-tools-right)+var(--shell-preview-toolbar-gap,0))]'
          )}
        >
          {visiblePaneTools.map(tool => (
            <TitlebarToolButton key={tool.id} navigate={navigate} tool={tool} />
          ))}
        </div>
      )}

      <div
        aria-label={t.shell.appControls}
        className={cn(titlebarToolClusterClass, 'right-(--titlebar-tools-right) top-(--titlebar-controls-top)')}
        data-titlebar-cluster="right"
      >
        {visibleSystemTools.map(tool => (
          <TitlebarToolButton key={tool.id} navigate={navigate} tool={tool} />
        ))}
        {visibleRightFixedTools.map(tool => (
          <TitlebarToolButton key={tool.id} navigate={navigate} tool={tool} />
        ))}
        <Slot area="titleBar.right" />
      </div>
    </>
  )
}

function TitlebarToolButton({ navigate, tool }: { navigate: ReturnType<typeof useNavigate>; tool: TitlebarTool }) {
  // Titlebar actions never show an active background — state reads from the
  // icon itself (e.g. the mute/unmute glyph). aria-pressed still carries it
  // for a11y.
  const className = cn(titlebarButtonClass, 'bg-transparent select-none', tool.className)

  const tooltipLabel = tool.actionId ? (
    <TipKeybindLabel actionId={tool.actionId} text={tool.title ?? tool.label} />
  ) : (
    (tool.title ?? tool.label)
  )

  if (tool.href) {
    return (
      <Tip label={tooltipLabel} placement="toolbar">
        <Button asChild className={className} size="icon-titlebar" variant="ghost">
          <a
            aria-label={tool.label}
            data-tour={tool.tour}
            href={tool.href}
            onPointerDown={event => event.stopPropagation()}
            rel="noreferrer"
            target="_blank"
          >
            {withCountBadge(tool.icon, tool.badge)}
          </a>
        </Button>
      </Tip>
    )
  }

  return (
    <Tip label={tooltipLabel} placement="toolbar">
      <Button
        aria-label={tool.label}
        aria-pressed={tool.active ?? undefined}
        className={className}
        data-tool-id={tool.id}
        data-tour={tool.tour}
        disabled={tool.disabled}
        onClick={event => {
          if (tool.actionId) {
            recordAction(tool.actionId, 'click')
          }

          if (tool.to) {
            navigate(tool.to)
          }

          tool.onSelect?.(event)
        }}
        onPointerDown={event => event.stopPropagation()}
        size="icon-titlebar"
        type="button"
        variant="ghost"
      >
        {withCountBadge(tool.icon, tool.badge)}
      </Button>
    </Tip>
  )
}

/**
 * ARO PROJECT DIALOG — Project Creation, Renaming & Folder Setup
 *
 * Implements 100% visual parity with the Aro Workbench prototype
 * (prototype/src/workbench/components/ProjectDialog.tsx), wired to
 * Hermes Electron engine and projects store.
 */

import { useStore } from '@nanostores/react'
import { useEffect, useRef, useState } from 'react'

import { desktopGit } from '@/lib/desktop-git'
import { cn } from '@/lib/utils'
import { notify, notifyError } from '@/store/notifications'
import {
  $newProjectDropPlacement,
  $projectDialog,
  $projects,
  addProjectFolder,
  clearNewProjectDropPlacement,
  closeProjectDialog,
  createProject,
  enterProject,
  followEnteredProjectCwd,
  pickProjectFolder,
  projectIdForCwd,
  refreshProjects,
  refreshProjectTree,
  renameProject
} from '@/store/projects'
import {
  $selectedStoredSessionId,
  commitWorkspaceCwdForSelectedSession,
  setCurrentCwd,
  setNewChatWorkspaceTarget,
  setSessions
} from '@/store/session'

import { isFolderTrusted, trustFolder } from './folder-trust'
import { IconCheck, IconFolder, IconPlus, IconShield, IconX } from './Icons'
import { assignSessionToProject, setAroDraftProject } from './project-session-map'
import { Button, Modal } from './ui'

export const ARO_PROJECT_COLORS = [
  { label: 'Violet', value: '#818cf8' },
  { label: 'Sky', value: '#38bdf8' },
  { label: 'Rose', value: '#fb7185' },
  { label: 'Mint', value: '#34d399' },
  { label: 'Amber', value: '#fbbf24' },
  { label: 'Pink', value: '#f472b6' }
]

export function AroProjectDialog() {
  const state = useStore($projectDialog)
  const open = state !== null
  const mode = state?.mode ?? 'create'

  const [name, setName] = useState('')
  const [color, setColor] = useState(ARO_PROJECT_COLORS[0].value)
  const [folders, setFolders] = useState<string[]>([])
  const [error, setError] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [pendingTrustFolder, setPendingTrustFolder] = useState<string | null>(null)
  const nameInputRef = useRef<HTMLInputElement>(null)

  const activateProject = (projectId: string, folder?: string) => {
    enterProject(projectId)
    setAroDraftProject(projectId)

    const target = folder?.trim() || ''

    if (target) {
      setCurrentCwd(target)
      setNewChatWorkspaceTarget(target)
      followEnteredProjectCwd(target)
    }

    const selectedSessionId = $selectedStoredSessionId.get()

    if (selectedSessionId) {
      void assignSessionToProject(selectedSessionId, projectId)
      setSessions(prev => prev.map(session => session.id === selectedSessionId ? { ...session, cwd: target || null } : session))

      if (target) {
        commitWorkspaceCwdForSelectedSession(target)
      }
    }
  }

  useEffect(() => {
    if (open) {
      setName(state?.name ?? '')
      setColor(ARO_PROJECT_COLORS[0].value)
      setFolders(state?.folder ? [state.folder] : [])
      setError('')
      setSubmitting(false)
      setPendingTrustFolder(null)
      const timer = window.setTimeout(() => nameInputRef.current?.focus(), 80)

      return () => window.clearTimeout(timer)
    } else {
      setPendingTrustFolder(null)
      clearNewProjectDropPlacement()
    }
  }, [open, state?.folder, state?.name])

  const executeAddFolder = async (dir: string) => {
    if (!state?.projectId) {return}
    setSubmitting(true)

    try {
      await addProjectFolder(state.projectId, dir)
      const target = dir.trim()

      if (target) {
        setCurrentCwd(target)
        setNewChatWorkspaceTarget(target)
        followEnteredProjectCwd(target)
        const selectedSessionId = $selectedStoredSessionId.get()

        if (selectedSessionId) {
          commitWorkspaceCwdForSelectedSession(target)
          setSessions(prev => prev.map(session => session.id === selectedSessionId ? { ...session, cwd: target || null } : session))
        }
      }

      closeProjectDialog()
      notify({ kind: 'info', message: 'Folder added to project' })
    } finally {
      setSubmitting(false)
    }
  }

  const executeCreateProject = async (trimmed: string, projectFolders: string[], projectColor: string) => {
    setSubmitting(true)

    try {
      const folder = projectFolders[0]
      const dropPlacement = $newProjectDropPlacement.get() ?? undefined

      const existingId = folder ? projectIdForCwd(folder) : null
      const isExistingProject = existingId && $projects.get().some(project => project.id === existingId)

      if (existingId && isExistingProject) {
        activateProject(existingId, folder)
        closeProjectDialog()
        notify({ kind: 'info', message: 'Opened existing project' })

        return
      }

      const created = await createProject({
        name: trimmed,
        color: projectColor,
        folders: projectFolders,
        primaryPath: folder || undefined,
        use: true,
        dropPlacement
      })

      if (created) {
        const projectRoot = created.primary_path || created.folders?.[0]?.path || folder
        activateProject(created.id, projectRoot)
        notify({ kind: 'info', message: `Project '${trimmed}' created` })

        if (projectRoot) {
          void desktopGit()
            ?.repoStatus(projectRoot)
            .then(() => refreshProjectTree())
            .catch(() => undefined)
        }
      }

      closeProjectDialog()
      clearNewProjectDropPlacement()
      void Promise.all([
        refreshProjects().catch(() => {}),
        refreshProjectTree().catch(() => {})
      ])
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err))
    } finally {
      setSubmitting(false)
    }
  }

  const handlePickFolder = async () => {
    setError('')

    try {
      const dir = await pickProjectFolder()

      if (!dir) {return}

      if (mode === 'add-folder' && state?.projectId) {
        if (!isFolderTrusted(dir)) {
          setPendingTrustFolder(dir)

          return
        }

        await executeAddFolder(dir)

        return
      }

      setFolders(prev => (prev.includes(dir) ? prev : [...prev, dir]))

      // Auto-populate name if empty
      if (mode === 'create' && !name.trim()) {
        const base = dir.replace(/[/\\]+$/, '').split(/[/\\]/).pop() || dir
        setName(base)
      }
    } catch (err) {
      notifyError(err, 'Failed to select folder')
    }
  }

  const handleRemoveFolder = (folderToRemove: string) => {
    setFolders(prev => prev.filter(f => f !== folderToRemove))
  }

  const handleConfirmTrust = async () => {
    if (!pendingTrustFolder) {return}
    const folder = pendingTrustFolder
    trustFolder(folder)
    setPendingTrustFolder(null)

    if (mode === 'add-folder') {
      await executeAddFolder(folder)
    } else if (mode === 'create') {
      const trimmed = name.trim()
      await executeCreateProject(trimmed, folders, color)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = name.trim()

    if (mode === 'rename') {
      if (!trimmed || !state?.projectId) {return}
      setSubmitting(true)

      try {
        await renameProject(state.projectId, trimmed)
        closeProjectDialog()
        notify({ kind: 'info', message: 'Project renamed' })
      } catch (err) {
        setError(err instanceof Error ? err.message : String(err))
      } finally {
        setSubmitting(false)
      }

      return
    }

    if (mode === 'create') {
      if (!trimmed) {
        setError('Please enter a project name')
        nameInputRef.current?.focus()

        return
      }

      if (folders.length === 0) {
        setError('Please select a local folder for this project')
        void handlePickFolder()

        return
      }

      const folder = folders[0]

      if (folder && !isFolderTrusted(folder)) {
        setPendingTrustFolder(folder)

        return
      }

      await executeCreateProject(trimmed, folders, color)
    }
  }

  const title =
    pendingTrustFolder
      ? 'Trust this folder?'
      : mode === 'rename'
        ? 'Rename project'
        : mode === 'add-folder'
          ? 'Add source folder'
          : 'Create project'

  const sub =
    pendingTrustFolder
      ? 'Aro Agent requires read, edit, and execution access to files in this directory.'
      : mode === 'create'
        ? 'Projects organize your code repos, sessions, and workspaces together.'
        : undefined

  return (
    <Modal
      onClose={closeProjectDialog}
      open={open}
      sub={sub}
      title={title}
      width={520}
    >
      {pendingTrustFolder ? (
        <div className="p-5 pt-3 space-y-4">
          <div className="flex items-center gap-3 rounded-panel border border-aro-line-soft bg-aro-sunken/40 p-3">
            <div className="flex size-9 shrink-0 items-center justify-center rounded-panel bg-aro-iris/15 text-aro-iris">
              <IconShield size={18} />
            </div>
            <div className="min-w-0 flex-1">
              <span className="block text-xs font-medium text-aro-ink-3 uppercase tracking-wider">
                Target Directory
              </span>
              <span className="block truncate font-aro-mono text-aro-sm text-aro-ink" title={pendingTrustFolder}>
                {pendingTrustFolder}
              </span>
            </div>
          </div>

          <div className="space-y-2 rounded-panel border border-aro-line-soft bg-aro-well/40 p-3.5 text-xs text-aro-ink-2">
            <div className="flex items-start gap-2.5">
              <IconCheck className="shrink-0 text-aro-mint mt-0.5" size={13} />
              <div>
                <span className="font-medium text-aro-ink">Read & Inspect:</span>{' '}
                Browse workspace files, search repository code, and index symbols.
              </div>
            </div>
            <div className="flex items-start gap-2.5">
              <IconCheck className="shrink-0 text-aro-mint mt-0.5" size={13} />
              <div>
                <span className="font-medium text-aro-ink">Edit & Create:</span>{' '}
                Apply code changes, create files, and commit project updates.
              </div>
            </div>
            <div className="flex items-start gap-2.5">
              <IconCheck className="shrink-0 text-aro-mint mt-0.5" size={13} />
              <div>
                <span className="font-medium text-aro-ink">Execute:</span>{' '}
                Run terminal commands, test suites, build scripts, and language tooling.
              </div>
            </div>
          </div>

          <p className="text-xs text-aro-ink-4 leading-relaxed">
            Only trust folders from authors and sources you trust. If you do not trust this directory, cancel to abort without granting execution access.
          </p>

          {error && (
            <p className="text-aro-sm text-aro-rose font-medium" role="alert">
              {error}
            </p>
          )}

          <div className="mt-6 flex items-center justify-end gap-2.5 pt-2 border-t border-aro-line-soft">
            <Button
              disabled={submitting}
              onClick={() => setPendingTrustFolder(null)}
              type="button"
              variant="ghost"
            >
              Cancel
            </Button>
            <Button
              disabled={submitting}
              onClick={() => void handleConfirmTrust()}
              type="button"
              variant="primary"
            >
              {submitting ? 'Trusting…' : 'Trust folder'}
            </Button>
          </div>
        </div>
      ) : (
        <form className="p-5 pt-3 space-y-4" onSubmit={handleSubmit}>
          {mode !== 'add-folder' && (
            <div>
              <label className="mb-1.5 block text-xs font-medium text-aro-ink-2">
                Project name
              </label>
              <div className="flex h-[40px] items-center rounded-control border border-aro-line bg-aro-sunken/40 px-3 focus-within:border-aro-iris focus-within:ring-1 focus-within:ring-aro-iris/30">
                <IconFolder className="mr-2.5 text-aro-ink-3 shrink-0" size={15} />
                <input
                  autoComplete="off"
                  className="h-full min-w-0 flex-1 bg-transparent text-sm text-aro-ink placeholder:text-aro-ink-4 focus:outline-none"
                  disabled={submitting}
                  maxLength={80}
                  onChange={e => {
                    setName(e.target.value)
                    setError('')
                  }}
                  placeholder="e.g. backend-api, frontend-app"
                  ref={nameInputRef}
                  value={name}
                />
              </div>
            </div>
          )}

          {mode === 'create' && (
            <>
              {/* Color Swatches */}
              <div className="flex items-center justify-between px-0.5">
                <label className="text-xs font-medium text-aro-ink-3">Project Color</label>
                <div aria-label="Project accent color" className="flex items-center gap-1.5" role="radiogroup">
                  {ARO_PROJECT_COLORS.map(c => (
                    <button
                      aria-label={`Select ${c.label} color`}
                      className={cn(
                        'relative flex size-[20px] cursor-pointer items-center justify-center rounded-full transition-transform hover:scale-110',
                        color === c.value && 'ring-2 ring-aro-ink ring-offset-2 ring-offset-aro-bg scale-105'
                      )}
                      key={c.value}
                      onClick={() => setColor(c.value)}
                      style={{ backgroundColor: c.value }}
                      type="button"
                    >
                      {color === c.value && (
                        <IconCheck className="text-white drop-shadow-(--aro-shadow-e1)" size={10} />
                      )}
                    </button>
                  ))}
                </div>
              </div>

              {/* Source Folders Box */}
              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <label className="block text-xs font-medium text-aro-ink-2">
                    Source folders
                  </label>
                  <span className="text-xs text-aro-ink-4">
                    {folders.length} {folders.length === 1 ? 'folder' : 'folders'}
                  </span>
                </div>

                <div className="rounded-panel border border-aro-line-soft bg-aro-sunken/25 p-2.5">
                  {folders.length > 0 && (
                    <div className="space-y-1 mb-2.5">
                      {folders.map(folder => {
                        const base =
                          folder.replace(/[/\\]+$/, '').split(/[/\\]/).pop() || folder

                        return (
                          <div
                            className="flex items-center gap-2 rounded-control border border-aro-line-soft bg-aro-raise/80 px-2.5 py-1.5"
                            key={folder}
                          >
                            <IconFolder
                              className="text-aro-ink-3 shrink-0"
                              size={14}
                              style={{ color }}
                            />
                            <div className="min-w-0 flex-1">
                              <span className="block truncate text-xs font-medium text-aro-ink">
                                {base}
                              </span>
                              <span className="block truncate font-aro-mono text-[var(--aro-text-2xs,10px)] text-aro-ink-4">
                                {folder}
                              </span>
                            </div>
                            <button
                              aria-label={`Remove ${base}`}
                              className="flex size-5 items-center justify-center rounded-control text-aro-ink-4 hover:bg-aro-hover hover:text-aro-ink cursor-pointer"
                              onClick={() => handleRemoveFolder(folder)}
                              type="button"
                            >
                              <IconX size={11} />
                            </button>
                          </div>
                        )
                      })}
                    </div>
                  )}

                  <div className="flex flex-col items-center justify-center gap-2 py-3">
                    <button
                      className="flex h-[30px] items-center gap-1.5 rounded-full border border-aro-line bg-aro-raise px-3.5 text-xs font-medium text-aro-ink-2 transition-colors hover:bg-aro-hover hover:text-aro-ink disabled:opacity-50 cursor-pointer"
                      disabled={submitting}
                      onClick={() => void handlePickFolder()}
                      type="button"
                    >
                      <IconFolder size={13} />
                      <IconPlus size={11} />
                      <span>Choose a local folder</span>
                    </button>
                    <span className="text-aro-xs text-aro-ink-4">
                      Sessions inside this project will run in this directory
                    </span>
                  </div>
                </div>
              </div>
            </>
          )}

          {mode === 'add-folder' && (
            <div className="py-4 text-center">
              <button
                className="inline-flex h-[32px] items-center gap-2 rounded-control bg-aro-iris px-4 text-aro-sm font-medium text-aro-on-iris hover:brightness-110 cursor-pointer"
                disabled={submitting}
                onClick={() => void handlePickFolder()}
                type="button"
              >
                <IconFolder size={14} />
                <span>Choose Folder to Add</span>
              </button>
            </div>
          )}

          {error && (
            <p className="text-aro-sm text-aro-rose font-medium" role="alert">
              {error}
            </p>
          )}

          {/* Footer */}
          <div className="mt-6 flex items-center justify-end gap-2.5 pt-2 border-t border-aro-line-soft">
            <Button
              disabled={submitting}
              onClick={closeProjectDialog}
              type="button"
              variant="ghost"
            >
              Cancel
            </Button>
            <Button
              disabled={submitting || (mode !== 'add-folder' && !name.trim())}
              type="submit"
              variant="primary"
            >
              {submitting
                ? 'Saving…'
                : mode === 'rename'
                  ? 'Save'
                  : 'Create project'}
            </Button>
          </div>
        </form>
      )}
    </Modal>
  )
}

/**
 * ARO SIDEBAR — Desktop Left Navigation & Session Roster (Prototype Parity)
 *
 * Implements 100% visual parity with the Aro Workbench prototype
 * (prototype/src/workbench/components/Sidebar.tsx), fully wired to the
 * Hermes Electron engine:
 *
 *  · Header: Brand logo + Aro wordmark + Collapse button (toggleLeftSide)
 *  · Primary Actions: New Session (⌘N) + Live Session Search
 *  · Main Navigation: Sessions | Projects | Skills | Connectors
 *  · Projects & Session Hierarchy:
 *      - Foldable projects with accent colors & item counts
 *      - Pinned sessions group
 *      - Project-assigned and unassigned sessions
 *      - Live execution status dots (breathing cyan for running, rose for error)
 *      - Context menus: Rename, Pin, Duplicate, Move to Project, Archive, Delete
 *  · Archive Mode: Toggle to view, restore, or purge archived sessions
 *  · Footer: Active Bot profile identity control + Settings link (⌘,)
 *  · Segregation & Audit:
 *      - Extra Hermes surfaces (Cron jobs, Messaging gateway channels,
 *        Remote connection switches, PR filters) are segregated into a
 *        frozen collapsible audit drawer so the prototype UI remains clean.
 */

