import { beforeEach, describe, expect, it } from 'vitest'

import {
  $trustedFolders,
  isFolderTrusted,
  resetTrustedFolders,
  trustFolder,
  untrustFolder
} from './folder-trust'

describe('folder-trust', () => {
  beforeEach(() => {
    resetTrustedFolders()
  })

  it('initially reports untrusted for unknown paths', () => {
    expect(isFolderTrusted('/home/user/project')).toBe(false)
    expect(isFolderTrusted('')).toBe(false)
  })

  it('trusts a specific folder and child subdirectories', () => {
    trustFolder('/home/user/project')

    expect(isFolderTrusted('/home/user/project')).toBe(true)
    expect(isFolderTrusted('/home/user/project/src')).toBe(true)
    expect(isFolderTrusted('/home/user/project/src/components')).toBe(true)

    // Unrelated sibling is not trusted
    expect(isFolderTrusted('/home/user/other-project')).toBe(false)
    expect(isFolderTrusted('/home/user')).toBe(false)
  })

  it('untrusts a previously trusted folder', () => {
    trustFolder('/workspace/app')
    expect(isFolderTrusted('/workspace/app')).toBe(true)

    untrustFolder('/workspace/app')
    expect(isFolderTrusted('/workspace/app')).toBe(false)
  })

  it('deduplicates trusted folder additions', () => {
    trustFolder('/workspace/app')
    trustFolder('/workspace/app')

    expect($trustedFolders.get().filter(p => p === '/workspace/app').length).toBe(1)
  })
})

import { atom } from 'nanostores'

import { cleanPath, isUnderPath } from '@/lib/path-compare'
import { readKey, writeKey } from '@/lib/storage'
import { requestGatewayForProfile } from '@/store/gateway'
import { $activeGatewayProfile, normalizeProfileKey } from '@/store/profile'

export const TRUSTED_FOLDERS_STORAGE_KEY = 'aro.desktop.trusted_folders'

function readInitialTrustedFolders(): string[] {
  const stored = readKey(TRUSTED_FOLDERS_STORAGE_KEY)

  if (!stored) {
    return []
  }

  try {
    const parsed = JSON.parse(stored)

    if (Array.isArray(parsed)) {
      return parsed.filter((item): item is string => typeof item === 'string' && item.trim().length > 0).map(cleanPath)
    }
  } catch {
    // Malformed JSON fallback
  }

  return []
}

export const $trustedFolders = atom<string[]>(readInitialTrustedFolders())

$trustedFolders.subscribe(folders => {
  writeKey(TRUSTED_FOLDERS_STORAGE_KEY, JSON.stringify(folders))
})

/**
 * Checks whether a folder path is explicitly trusted by the user.
 * Returns true if the path itself or an ancestor directory is in the trusted folders list.
 */
export function isFolderTrusted(folderPath: string): boolean {
  const trimmed = folderPath.trim()

  if (!trimmed) {
    return false
  }

  const cleaned = cleanPath(trimmed)
  const trusted = $trustedFolders.get()

  return trusted.some(trustedPath => isUnderPath(trustedPath, cleaned))
}

/**
 * Adds a directory to the trusted folders set and persists it.
 * Also best-effort syncs with the live gateway's `lsp.trusted_workspaces` config.
 */
export function trustFolder(folderPath: string): void {
  const trimmed = folderPath.trim()

  if (!trimmed) {
    return
  }

  const cleaned = cleanPath(trimmed)
  const current = $trustedFolders.get()

  if (!current.includes(cleaned)) {
    const next = [...current, cleaned]
    $trustedFolders.set(next)

    // Best-effort sync to gateway lsp.trusted_workspaces so LSP doesn't skip this directory
    try {
      void requestGatewayForProfile(normalizeProfileKey($activeGatewayProfile.get()), 'config.set', {
        key: 'lsp.trusted_workspaces',
        value: next
      }).catch(() => {
        // Gateway may not be open or may not support config.set in this environment
      })
    } catch {
      // Ignore background sync errors
    }
  }
}

/**
 * Removes a directory from the trusted folders set.
 */
export function untrustFolder(folderPath: string): void {
  const trimmed = folderPath.trim()

  if (!trimmed) {
    return
  }

  const cleaned = cleanPath(trimmed)
  const current = $trustedFolders.get()
  const next = current.filter(item => item !== cleaned)
  $trustedFolders.set(next)
}

/**
 * Clears all trusted folders (used primarily in tests).
 */
export function resetTrustedFolders(): void {
  $trustedFolders.set([])
}

/**
 * PROTOTYPE → DESKTOP DESIGN-SYSTEM PARITY (source-of-truth guard)
 *
 * The Aro Workbench prototype (`prototype/src/app/globals.css`) is the visual
 * source of truth. The desktop port mirrors its tokens under the `--aro-*`
 * namespace in `src/aro/tokens.css` (prefix swap `--t-` → `--aro-`, with ONE
 * rename: the prototype's `--t-base` surface is the desktop's `--aro-bg`).
 *
 * This suite is a CONTRACT test, not a snapshot: it parses BOTH live stylesheets
 * and asserts that every prototype theme token is present on the desktop with an
 * identical computed value, and that all six prototype themes exist. It exists
 * because the port previously copied token values by hand and silently dropped
 * the font loading — this is the invariant that stops the next such drift.
 */
import { existsSync, readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { describe, expect, it } from 'vitest'

const here = dirname(fileURLToPath(import.meta.url))
const PROTOTYPE_CSS = resolve(here, '../../../../prototype/src/app/globals.css')
const DESKTOP_CSS = resolve(here, './tokens.css')

/** The six themes the prototype defines. */
const THEMES = ['obsidian', 'daylight', 'nord', 'ember', 'paper', 'ink'] as const

/** Token rename applied by the port: prototype surface `base` → desktop `bg`. */
const rename = (protoToken: string): string =>
  protoToken === '--t-base' ? '--aro-bg' : protoToken.replace(/^--t-/, '--aro-')

/** Pull one `html[data-theme="X"] { … }` block's `--token: value` pairs. */
function themeTokens(css: string, theme: string): Record<string, string> {
  // Prototype uses double quotes, desktop uses single; match either.
  const re = new RegExp(`html\\[data-theme=["']${theme}["']\\][^{]*\\{([^}]*)\\}`, 'm')
  const body = css.match(re)?.[1] ?? ''
  const out: Record<string, string> = {}

  for (const m of body.matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) {
    out[m[1].trim()] = normalize(m[2])
  }

  return out
}

/** Normalize a CSS value so rgba spacing / case don't cause false negatives. */
function normalize(value: string): string {
  return value
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/rgba\(\s*/g, 'rgba(')
    .replace(/\s*,\s*/g, ', ')
    .replace(/\s*\)\s*/g, ')')
    .replace(/(?<=[ ,(])0\.(\d+)/g, '.$1')
    .toLowerCase()
}

describe('prototype design-system parity (tokens.css vs prototype globals.css)', () => {
  const protoCss = readFileSync(PROTOTYPE_CSS, 'utf8')
  const desktopCss = readFileSync(DESKTOP_CSS, 'utf8')

  it('defines every prototype theme on the desktop', () => {
    for (const theme of THEMES) {
      expect(
        Object.keys(themeTokens(desktopCss, theme)).length,
        `desktop is missing the "${theme}" theme block`
      ).toBeGreaterThan(0)
    }
  })

  it.each(THEMES)('theme "%s" matches the prototype token-for-token', theme => {
    const proto = themeTokens(protoCss, theme)
    const desktop = themeTokens(desktopCss, theme)

    // The prototype block must actually exist (guards a broken parser path).
    expect(Object.keys(proto).length, `prototype "${theme}" block empty`).toBeGreaterThan(20)

    for (const [protoToken, protoValue] of Object.entries(proto)) {
      const desktopToken = rename(protoToken)
      expect(
        desktop[desktopToken],
        `theme "${theme}": desktop lacks ${desktopToken} (prototype ${protoToken})`
      ).toBeDefined()
      expect(
        desktop[desktopToken],
        `theme "${theme}": ${desktopToken} diverges from prototype ${protoToken}`
      ).toBe(protoValue)
    }
  })

  it('keeps the full surface/ink/signal token vocabulary on every theme', () => {
    // A representative slice across each token family — asserts the port kept
    // the whole vocabulary, not just the handful we diffed above.
    const required = [
      '--aro-void', '--aro-sunken', '--aro-bg', '--aro-raise', '--aro-hover',
      '--aro-overlay', '--aro-well', '--aro-code', '--aro-track',
      '--aro-line', '--aro-line-soft', '--aro-line-strong',
      '--aro-ink', '--aro-ink-2', '--aro-ink-3', '--aro-ink-4',
      '--aro-iris', '--aro-iris-soft', '--aro-iris-deep', '--aro-on-iris',
      '--aro-cyan', '--aro-mint', '--aro-amber', '--aro-rose', '--aro-sky', '--aro-plum',
      '--aro-shadow-a', '--aro-shadow-b', '--aro-shadow-c', '--aro-shadow-d'
    ]

    for (const theme of THEMES) {
      const desktop = themeTokens(desktopCss, theme)

      for (const token of required) {
        expect(desktop[token], `theme "${theme}" missing ${token}`).toBeDefined()
      }
    }
  })
})

describe('prototype webfont parity (identity faces are actually shipped)', () => {
  const desktopCss = readFileSync(DESKTOP_CSS, 'utf8')
  const FONTS_DIR = resolve(here, '../fonts')

  // The five families prototype/src/app/layout.tsx loads via next/font.
  // JetBrains Mono's @font-face pre-dates the Aro port and lives in styles.css;
  // the four Aro identity faces were added to tokens.css.
  const FACES: Array<{ family: string; file: string; declaredIn: 'tokens' | 'styles' }> = [
    { family: 'Space Grotesk', file: 'SpaceGrotesk-Variable.woff2', declaredIn: 'tokens' },
    { family: 'Inter', file: 'Inter-Variable.woff2', declaredIn: 'tokens' },
    { family: 'Newsreader', file: 'Newsreader-Variable.woff2', declaredIn: 'tokens' },
    { family: 'DM Sans', file: 'DMSans-Variable.woff2', declaredIn: 'tokens' },
    { family: 'JetBrains Mono', file: 'JetBrainsMono-Regular.woff2', declaredIn: 'styles' }
  ]

  const stylesCss = readFileSync(resolve(here, '../styles.css'), 'utf8')

  it.each(FACES)('declares an @font-face for $family and ships the woff2', ({ family, file, declaredIn }) => {
    // @font-face present in the right stylesheet (loads via styles.css @import).
    const css = declaredIn === 'tokens' ? desktopCss : stylesCss
    expect(css, `${declaredIn}.css missing @font-face for "${family}"`).toContain(
      `font-family: '${family}'`
    )
    // The referenced woff2 is actually on disk.
    expect(
      existsSync(resolve(FONTS_DIR, file)),
      `bundled font missing: src/fonts/${file}`
    ).toBe(true)
  })

  it('binds the prototype next/font --f-* variables so the fallback chain resolves', () => {
    // Without these, `var(--f-grotesk, "Space Grotesk")` fell through to the
    // system font — the exact drift this suite exists to prevent.
    for (const v of ['--f-grotesk', '--f-inter', '--f-newsreader', '--f-dmsans', '--f-jbmono']) {
      expect(desktopCss, `tokens.css missing ${v} binding`).toContain(`${v}:`)
    }
  })
})

