describe('list post-settle restore vs composer-only resize', () => {
  it('follows pre-settle async layout before the next animation frame can paint', () => {
    const raf = vi.spyOn(globalThis, 'requestAnimationFrame').mockImplementation(() => 0)

    try {
      const { container, unmount } = render(<ScrollHarness messages={sessionMessages('cold')} sessionKey="cold" />)
      const vp = viewportEl(container)
      viewportScrollHeight += 146
      fireContentResizes()
      expect(vp.scrollTop).toBe(viewportScrollHeight - CLIENT_H)
      unmount()
    } finally {
      raf.mockRestore()
    }
  })

  it('does not rewrite scrollTop when only composer clearance grows; content growth still restores', async () => {
    saveThreadScrollPosition('a', { fromBottom: FROM_BOTTOM, kind: 'offset' })

    const { container } = render(<ScrollHarness messages={sessionMessages('a')} sessionKey="a" />)
    const vp = viewportEl(container)

    await settleScroll()

    const restoredTop = SCROLL_H - CLIENT_H - FROM_BOTTOM
    expect(vp.scrollTop).toBe(restoredTop)

    const userRoot = container.querySelector('[data-slot="aui_user-message-root"]')
    expect(userRoot).toBeTruthy()
    expect(container.querySelector(`[data-slot="${CLEARANCE_SLOT}"]`)).toBeTruthy()

    // Composer-only: clearance + viewport box move together; transcript rows do not.
    viewportScrollHeight = SCROLL_H + 80
    viewportClientHeight = CLIENT_H - 80
    clearanceHeight = 200
    fireContentResizes()

    expect(vp.scrollTop).toBe(restoredTop)
    expect(container.querySelector('[data-slot="aui_user-message-root"]')).toBe(userRoot)

    // CONTROL: real transcript growth must still re-pin the frozen fromBottom.
    viewportScrollHeight = SCROLL_H + 80 + 600
    fireContentResizes()

    expect(vp.scrollTop).toBe(
      threadScrollTargetTop(
        { fromBottom: FROM_BOTTOM, kind: 'offset' },
        { clientHeight: viewportClientHeight, scrollHeight: viewportScrollHeight }
      )
    )
  })

  it('a genuine scroll cancels a settled bottom restore, so a later resize tick cannot yank the view back', async () => {
    const { container } = render(<ScrollHarness messages={sessionMessages('b')} sessionKey="b" />)
    const vp = viewportEl(container)

    await settleScroll()
    expect(vp.scrollTop).toBe(SCROLL_H - CLIENT_H)

    // Not a wheel/pointer/key gesture: a rail jump or find-in-page reveal only fires `scroll`.
    act(() => {
      vp.scrollTop = 1000
      vp.dispatchEvent(new Event('scroll'))
    })

    viewportScrollHeight = SCROLL_H + 600
    fireContentResizes()

    expect(vp.scrollTop).toBe(1000)
  })

  it('a settled bottom target ignores a composer-only resize but still follows transcript growth', async () => {
    const { container } = render(<ScrollHarness messages={sessionMessages('c')} sessionKey="c" />)
    const vp = viewportEl(container)

    await settleScroll()
    expect(vp.scrollTop).toBe(SCROLL_H - CLIENT_H)

    // The view sits off the bottom without any cancel gesture having fired.
    vp.scrollTop = 1000

    viewportScrollHeight = SCROLL_H + 80
    viewportClientHeight = CLIENT_H - 80
    clearanceHeight = 200
    fireContentResizes()

    expect(vp.scrollTop).toBe(1000)

    // CONTROL: real transcript growth re-pins the bottom target.
    viewportScrollHeight = SCROLL_H + 80 + 600
    fireContentResizes()

    expect(vp.scrollTop).toBe(viewportScrollHeight - viewportClientHeight)
  })
})

import { useCallback, useEffect, useState } from 'react'

import { useSessionView } from '@/app/chat/session-view'
import { sessionCreatedThisRun } from '@/app/session/hooks/use-session-actions/created-this-run'
import { useStoreSelector } from '@/lib/use-session-slice'
import { $activeGatewayProfile } from '@/store/profile'
import { $connection, getSessionOwnerHint } from '@/store/session'
import { transcriptTailState } from '@/store/transcript-tail'

import { cachedTimelineIndex, fetchTimelineIndex, type TimelineIndex, timelineIndexKey } from './timeline-index'

/** A bounded metadata page after paint; more titles load only on explicit demand. */
export function useTimelineHistory() {
  const view = useSessionView()
  const storedId = useStoreSelector(view.$storedId, id => id)
  const runtimeId = useStoreSelector(view.$runtimeId, id => id)

  const connectionId = useStoreSelector(
    $connection,
    connection => connection?.connectionId || (connection?.mode === 'local' ? 'local' : '')
  )

  const activeProfile = useStoreSelector($activeGatewayProfile, profile => profile)

  const owner = storedId
    ? getSessionOwnerHint(storedId, connectionId ? { connectionId, profile: activeProfile } : undefined)
    : undefined

  const scope = owner
    ? { connectionId: owner.connectionId, profile: owner.targetProfile || owner.profile }
    : (transcriptTailState(storedId)?.profile ?? { connectionId, profile: activeProfile })

  const key = timelineIndexKey(storedId ?? '', scope)
  const [index, setIndex] = useState<{ key: string; value: TimelineIndex } | null>(null)
  const [failed, setFailed] = useState<string | null>(null)

  const loadMore = useCallback(
    async (beyondRowId?: number) => {
      if (!storedId) {
        return
      }

      // A freshly minted draft has no state.db row until the first prompt persists
      // it (#123622) — fetching its timeline before then only ever 404s, since an
      // empty local view already IS the correct (empty) render.
      if (sessionCreatedThisRun(storedId) && view.$messages.get().length === 0) {
        return
      }

      try {
        const value = await fetchTimelineIndex(storedId, scope, beyondRowId)

        if (view.$storedId.get() === storedId && view.$runtimeId.get() === runtimeId) {
          setIndex({ key, value })
          setFailed(null)
        }
      } catch {
        // Old backends keep the loaded rail and their explicit Show earlier path.
        setFailed(key)
      }
      // Owner is represented by key; do not restart on object identity alone.
    },
    [key, storedId, runtimeId, view]
  )

  useEffect(() => {
    if (!storedId) {
      return
    }

    const timer = window.setTimeout(() => {
      void loadMore()
    }, 200)

    return () => window.clearTimeout(timer)
  }, [loadMore, storedId])

  const value = index?.key === key ? index.value : cachedTimelineIndex(key)

  // The newest persisted prompt in the live tail — a scalar, so streaming
  // deltas never re-run this. Each new turn moves it once.
  const newestPromptRowId = useStoreSelector(view.$messages, messages => {
    for (let i = messages.length - 1; i >= 0; i--) {
      const message = messages[i]!

      if (message.role === 'user' && message.rowId !== undefined) {
        return message.rowId
      }
    }

    return undefined
  })

  // A complete index is a snapshot of the turns that existed when it was
  // read. When the live tail grows past its last mark (entries are
  // chronological), page it forward once per new prompt — no timer; an
  // incomplete index still pages on demand.
  const last = value?.entries.at(-1)?.rowId

  const stale =
    value?.complete === true && newestPromptRowId !== undefined && (last === undefined || last < newestPromptRowId)

  useEffect(() => {
    if (!stale || failed === key) {
      return
    }

    void loadMore(newestPromptRowId)
  }, [stale, failed, key, loadMore, newestPromptRowId])

  return { ...value, failed: failed === key, loadMore }
}

