/**
 * Live-behavior test for FloatingPanes: mounts the REAL component into a real
 * DOM and drives real pointer/resize events. This is the closest thing to
 * "running it" without an Electron main process — it exercises the rendered
 * element's computed geometry, not the pure geometry module (that's
 * floating-rect.test.ts).
 */

import { act } from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import type { registry as contributionRegistry } from '@/contrib/registry'
import { reactRoot } from '@/test/react-root'

import type { FloatingPanes as FloatingPanesComponent } from './floating-panes'

let registry: typeof contributionRegistry
let FloatingPanes: typeof FloatingPanesComponent

const mount = reactRoot()
let disposers: (() => void)[] = []

const card = () => document.querySelector<HTMLElement>('[data-floating-pane="hud"]')

const grab = () => card()!.querySelector('header')!

/** jsdom has no real pointer events; PointerEvent falls back to MouseEvent. */
function pointer(target: Element, type: string, x: number, y: number) {
  const event = new MouseEvent(type, { bubbles: true, clientX: x, clientY: y })

  Object.defineProperty(event, 'pointerId', { value: 1 })

  act(() => {
    target.dispatchEvent(event)
  })
}

function resizeWindow(width: number, height: number) {
  Object.defineProperty(window, 'innerWidth', { configurable: true, value: width, writable: true })
  Object.defineProperty(window, 'innerHeight', { configurable: true, value: height, writable: true })

  act(() => {
    window.dispatchEvent(new Event('resize'))
  })
}

function registerHud(data: Record<string, unknown>) {
  disposers.push(
    registry.register({
      area: 'panes',
      data,
      id: 'hud',
      render: () => <p data-testid="hud-body">live</p>,
      title: 'HUD'
    })
  )
}

describe('FloatingPanes (live DOM)', () => {
  beforeEach(async () => {
    vi.resetModules()
    window.localStorage.clear()
    registry = (await import('@/contrib/registry')).registry
    FloatingPanes = (await import('./floating-panes')).FloatingPanes
    resizeWindow(1440, 900)
    // setPointerCapture / releasePointerCapture don't exist in jsdom.
    Element.prototype.setPointerCapture = vi.fn()
    Element.prototype.releasePointerCapture = vi.fn()
  })

  afterEach(() => {
    mount.unmount()
    disposers.forEach(dispose => dispose())
    disposers = []
  })

  it('mounts a fixed card in the anchored corner with the pane body inside', () => {
    registerHud({ anchor: 'top-right', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    const el = card()!

    expect(el).toBeTruthy()
    // 1440 - 224 - 12 margin = 1204; titlebar 34 + 12 = 46.
    expect(el.style.left).toBe('1204px')
    expect(el.style.top).toBe('46px')
    expect(el.style.width).toBe('224px')
    expect(document.querySelector('[data-testid="hud-body"]')?.textContent).toBe('live')
  })

  it('renders nothing for a non-floating placement', () => {
    registerHud({ placement: 'right', width: '224px' })
    mount.render(<FloatingPanes />)

    expect(card()).toBeNull()
  })

  it('moves with a real pointer drag on the header', () => {
    registerHud({ anchor: 'top-left', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    expect(card()!.style.left).toBe('12px')

    pointer(grab(), 'pointerdown', 100, 100)
    pointer(grab(), 'pointermove', 260, 240)
    pointer(grab(), 'pointerup', 260, 240)

    expect(card()!.style.left).toBe('172px')
    expect(card()!.style.top).toBe('186px')
  })

  it('persists the dragged position across a remount', () => {
    registerHud({ anchor: 'top-left', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    pointer(grab(), 'pointerdown', 100, 100)
    pointer(grab(), 'pointermove', 300, 300)
    pointer(grab(), 'pointerup', 300, 300)

    const moved = card()!.style.left

    mount.unmount()
    mount.render(<FloatingPanes />)

    expect(card()!.style.left).toBe(moved)
  })

  it('rides the right edge when the window shrinks', () => {
    registerHud({ anchor: 'top-right', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    expect(card()!.style.left).toBe('1204px')

    resizeWindow(1000, 700)

    // Tracks the edge: 1000 - 224 - 12 = 764.
    expect(card()!.style.left).toBe('764px')
  })

  it('never lets a drag push the card under the titlebar', () => {
    registerHud({ anchor: 'top-left', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    pointer(grab(), 'pointerdown', 100, 100)
    pointer(grab(), 'pointermove', 100, -900)
    pointer(grab(), 'pointerup', 100, -900)

    expect(Number.parseFloat(card()!.style.top)).toBeGreaterThanOrEqual(34)
  })

  it('collapses to the header and drops the body, and does not drag from the button', () => {
    registerHud({ anchor: 'top-left', height: '132px', placement: 'floating', width: '224px' })
    mount.render(<FloatingPanes />)

    const before = card()!.style.left
    const toggle = card()!.querySelector('button')!

    // The button is inside the drag handle — [data-floating-no-drag] must
    // stop it starting a drag.
    pointer(toggle, 'pointerdown', 100, 100)
    pointer(grab(), 'pointermove', 400, 400)
    pointer(grab(), 'pointerup', 400, 400)

    expect(card()!.style.left).toBe(before)

    act(() => {
      toggle.click()
    })

    expect(document.querySelector('[data-testid="hud-body"]')).toBeNull()
    expect(card()!.style.height).toBe('')
  })

  it('renders one card per floating contribution', () => {
    registerHud({ anchor: 'top-left', placement: 'floating', width: '224px' })
    disposers.push(
      registry.register({
        area: 'panes',
        data: { anchor: 'bottom-right', placement: 'floating', width: '200px' },
        id: 'hud2',
        render: () => null,
        title: 'HUD 2'
      })
    )

    mount.render(<FloatingPanes />)

    expect(document.querySelectorAll('[data-floating-pane]').length).toBe(2)
  })
})

/**
 * Floating panes — the tree's non-tiling placement.
 *
 * `placement: 'floating'` opts a pane OUT of the layout tree: it never becomes
 * a track, never takes width from a zone, and never appears in a tab strip.
 * The tree renders it as a fixed card above itself, draggable by its header,
 * with position + collapse persisted per pane id. The geometry rules live in
 * floating-rect.ts.
 */

import { useStore } from '@nanostores/react'
import { type PointerEvent as ReactPointerEvent, useCallback, useEffect, useRef } from 'react'

import { HUD_SURFACE } from '@/app/floating-hud'
import { TITLEBAR_HEIGHT } from '@/app/shell/titlebar'
import { useOnboardingChatActive } from '@/components/onboarding-chat/assembly'
import { Codicon } from '@/components/ui/codicon'
import { ContribBoundary, ContribRender } from '@/contrib/react/boundary'
import { useContributions } from '@/contrib/react/use-contributions'
import type { Contribution } from '@/contrib/types'
import { LAYOUT_KEYS } from '@/lib/layout-persistence'
import { Codecs } from '@/lib/persisted'
import { cn } from '@/lib/utils'
import { modeLayout } from '@/store/interface-mode'

import { hiddenPaneProps, PaneLifecycleContext, PaneVisibleContext } from '../../pane-visibility'
import { $hiddenTreePanes } from '../store'

import {
  anchoredRect,
  clampFloatingRect,
  FLOATING_PLACEMENT,
  floatingPx,
  type FloatingRect,
  type FloatingViewport,
  reflowRect
} from './floating-rect'
import { PaneBody } from './pane-body'
import { paneChrome } from './track-model'

const DEFAULT_SIZE = { width: 240, height: 180 }

interface StoredRect {
  x: number
  y: number
  collapsed?: boolean
}

const $positions = modeLayout.atom<Record<string, StoredRect>>(
  LAYOUT_KEYS.floating,
  () => ({}),
  Codecs.json(value =>
    value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, StoredRect>) : {}
  ),
  true
)

const viewportNow = (): FloatingViewport => ({
  width: window.innerWidth,
  height: window.innerHeight,
  top: TITLEBAR_HEIGHT
})

function FloatingPane({ pane }: { pane: Contribution }) {
  const chrome = paneChrome(pane)
  const anchor = chrome.anchor ?? 'top-right'

  const size = {
    width: floatingPx(chrome.width, DEFAULT_SIZE.width),
    height: floatingPx(chrome.height, DEFAULT_SIZE.height)
  }

  const stored = useStore($positions)[pane.id]
  const rect = { ...anchoredRect(anchor, size, viewportNow()), ...stored }
  const collapsed = stored?.collapsed ?? false
  const drag = useRef<{ x: number; y: number } | null>(null)
  const viewport = useRef<FloatingViewport>(viewportNow())

  const setRect = useCallback(
    (update: (current: FloatingRect) => FloatingRect) => {
      const positions = $positions.get()
      const current = positions[pane.id]

      const next = update({
        ...anchoredRect(anchor, { width: size.width, height: size.height }, viewport.current),
        ...current
      })

      $positions.set({ ...positions, [pane.id]: { x: next.x, y: next.y, collapsed: current?.collapsed } })
    },
    [pane.id, anchor, size.width, size.height]
  )

  const persist = useCallback(
    (next: FloatingRect, nextCollapsed: boolean) => {
      const positions = { ...$positions.get(), [pane.id]: { x: next.x, y: next.y, collapsed: nextCollapsed } }
      $positions.set(positions)
      modeLayout.write(LAYOUT_KEYS.floating, JSON.stringify(positions))
    },
    [pane.id]
  )

  // Track the viewport so an edge-anchored pane rides its edge on resize.
  // The previous-size read lives in the handler (not a useEffect body): it's
  // window geometry, not a mirrored reactive value.
  const handleResize = useCallback(() => {
    const next = viewportNow()

    setRect(current => reflowRect(current, anchor, viewport.current, next))
    viewport.current = next
  }, [anchor, setRect])

  useEffect(() => {
    window.addEventListener('resize', handleResize)

    return () => window.removeEventListener('resize', handleResize)
  }, [handleResize])

  const onPointerDown = useCallback((event: ReactPointerEvent<HTMLElement>) => {
    if ((event.target as HTMLElement).closest('[data-floating-no-drag]')) {
      return
    }

    event.currentTarget.setPointerCapture(event.pointerId)
    drag.current = { x: event.clientX, y: event.clientY }
    event.preventDefault()
  }, [])

  const onPointerMove = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      const from = drag.current

      if (!from) {
        return
      }

      drag.current = { x: event.clientX, y: event.clientY }

      setRect(current =>
        clampFloatingRect(
          { ...current, x: current.x + event.clientX - from.x, y: current.y + event.clientY - from.y },
          viewport.current
        )
      )
    },
    [setRect]
  )

  const onPointerUp = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      if (!drag.current) {
        return
      }

      drag.current = null
      event.currentTarget.releasePointerCapture?.(event.pointerId)
      persist({ ...rect, ...$positions.get()[pane.id] }, collapsed)
    },
    [pane.id, rect, collapsed, persist]
  )

  const toggleCollapsed = () => persist(rect, !collapsed)

  return (
    <div
      className={cn('pointer-events-auto fixed z-45 flex flex-col overflow-hidden', HUD_SURFACE)}
      data-floating-pane={pane.id}
      style={{
        left: rect.x,
        top: rect.y,
        width: size.width,
        height: collapsed ? undefined : size.height
      }}
    >
      {/* Header IS the drag handle — the floating equivalent of a tab strip. */}
      <header
        className="flex shrink-0 cursor-grab items-center justify-between gap-2 px-2.5 py-1.5 text-aro-xs text-(--ui-text-secondary) select-none"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        style={{ touchAction: 'none' }}
      >
        <span className="truncate font-medium">{pane.title ?? pane.id}</span>
        <button
          className="rounded-control p-0.5 text-(--ui-text-quaternary) transition-colors hover:text-(--ui-text-primary)"
          data-floating-no-drag=""
          onClick={toggleCollapsed}
          type="button"
        >
          <Codicon name={collapsed ? 'chevron-up' : 'chevron-down'} size="0.75rem" />
        </button>
      </header>

      {(!collapsed || chrome.lifecycleKeepAlive) && (
        <PaneBody hidden={collapsed}>
          <div className="h-full overflow-auto" inert={collapsed || undefined} {...hiddenPaneProps(collapsed)}>
            <PaneLifecycleContext value={collapsed ? 'hot-hidden' : 'visible'}>
              <PaneVisibleContext value={!collapsed}>
                <ContribBoundary id={pane.id}>{pane.render && <ContribRender render={pane.render} />}</ContribBoundary>
              </PaneVisibleContext>
            </PaneLifecycleContext>
          </div>
        </PaneBody>
      )}
    </div>
  )
}

/** Every `placement: 'floating'` contribution, rendered above the tree. */
export function FloatingPanes() {
  const panes = useContributions('panes')
  const hidden = useStore($hiddenTreePanes)

  const onboardingActive = useOnboardingChatActive()

  const floating = onboardingActive
    ? []
    : panes.filter(pane => paneChrome(pane).placement === FLOATING_PLACEMENT && !hidden.has(pane.id))

  if (floating.length === 0) {
    return null
  }

  return (
    <>
      {floating.map(pane => (
        <FloatingPane key={`${pane.source ?? 'core'}:${pane.id}`} pane={pane} />
      ))}
    </>
  )
}

import { cleanup, render } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { registry } from '@/contrib/registry'
import { stubResizeObserver } from '@/test/jsdom'

import { group, split } from '../model'
import { $hiddenTreePanes, $layoutTree } from '../store'

import { subtreeGone, type TrackContext } from './track-model'
import { TreeSplit } from './tree-split'

// Ground truth for "the main pane always shows, no matter what". Emptying the
// main strip must never let a sibling absorb the center — the failure Bot Mode
// shipped, where closing the last bot chat left the roster sidebar stretched
// across the whole window. Chrome toggles over a tool panel must still collapse.

beforeAll(() => {
  stubResizeObserver()
  // jsdom lacks CSS.escape, which tab-strip-scroll uses in a layout effect.
  vi.stubGlobal('CSS', { ...globalThis.CSS, escape: (value: string) => value })
})

const disposers: (() => void)[] = []

beforeEach(() => {
  window.localStorage.clear()
  $hiddenTreePanes.set(new Set())

  for (const [id, data] of [
    ['sessions', { placement: 'left', width: '237px' }],
    ['workspace', { placement: 'main', uncloseable: true }],
    ['session-tile:a', { placement: 'main' }],
    ['terminal', { placement: 'bottom', height: '38vh' }]
  ] as const) {
    disposers.push(registry.register({ area: 'panes', data, id, render: () => null, title: id }))
  }
})

afterEach(() => {
  cleanup()
  $hiddenTreePanes.set(new Set())
  $layoutTree.set(null)
  disposers.splice(0).forEach(dispose => dispose())
})

/** The split-child WRAPPER the renderer sizes — `display:none` on it is what
 *  hands a zone's space to its siblings. */
const zoneWrapper = (groupId: string) =>
  document.querySelector<HTMLElement>(`[data-tree-group="${groupId}"]`)?.closest<HTMLElement>('[style]')

const ctx = (gone: string[]): TrackContext => ({
  overrides: {},
  paneFor: id => registry.getArea('panes').find(pane => pane.id === id),
  paneGone: id => gone.includes(id)
})

describe('subtreeGone', () => {
  it('keeps a main-bearing subtree even when every one of its panes is gone', () => {
    const main = group(['workspace', 'session-tile:a'], { id: 'grp-main' })

    expect(subtreeGone(main, ctx(['workspace', 'session-tile:a']))).toBe(false)
  })

  it('still collapses a tool zone whose panes a chrome toggle hid', () => {
    expect(subtreeGone(group(['terminal'], { id: 'grp-tools' }), ctx(['terminal']))).toBe(true)
  })

  it('still collapses a main pane whose plugin has not registered yet', () => {
    // No contribution means no placement to read — the zone stays folded until
    // the plugin loads rather than flashing an empty placeholder.
    expect(subtreeGone(group(['plugin-workspace:late'], { id: 'grp-late' }), ctx(['plugin-workspace:late']))).toBe(true)
  })
})

describe('the main placement floor in the renderer', () => {
  it('renders the main zone with every main tab hidden, and leaves tool zones absorbable', () => {
    const tree = split('row', [
      group(['sessions'], { id: 'grp-sessions' }),
      split('column', [
        group(['workspace', 'session-tile:a'], { id: 'grp-main' }),
        group(['terminal'], { id: 'grp-tools' })
      ])
    ])

    $layoutTree.set(tree)
    $hiddenTreePanes.set(new Set(['workspace', 'session-tile:a', 'terminal']))

    render(<TreeSplit node={tree} root rootRow />)

    const main = zoneWrapper('grp-main')

    expect(main).toBeTruthy()
    expect(main!.style.display).not.toBe('none')
    expect(zoneWrapper('grp-sessions')?.style.display).not.toBe('none')
    expect(zoneWrapper('grp-tools')?.style.display).toBe('none')
  })
})

import { act, cleanup, fireEvent, render } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { PANE_TOGGLE_REVEAL_EVENT } from '@/components/pane-shell'
import { registry } from '@/contrib/registry'
import { $paneStates, setPaneWidthOverride } from '@/store/panes'
import { $connection } from '@/store/session'
import { stubResizeObserver } from '@/test/jsdom'

import { group, split } from '../model'
import { $hiddenTreePanes, $layoutTree, $narrowViewport, declareDefaultTree } from '../store'

import { NarrowOverlays, narrowOverlayWidth } from './narrow-overlays'

// Ground truth for "the Bots tab is still visible when the sessions sidebar
// collapses on a narrow window". A collapsible pane DOCKED into the sessions
// zone (SESSIONS | BOTS) must leave the grid with the zone, and the narrow
// edge overlay must mirror the zone's tab strip so the docked pane stays
// reachable — not just the zone's first pane.

beforeAll(() => {
  stubResizeObserver()
})

const disposers: (() => void)[] = []

const registerPane = (id: string, title: string, data: Record<string, unknown>, body: string) => {
  disposers.push(
    registry.register({
      area: 'panes',
      data,
      id,
      render: () => <div data-testid={`${id}-body`}>{body}</div>,
      title
    })
  )
}

beforeEach(() => {
  window.localStorage.clear()
  $hiddenTreePanes.set(new Set())

  registerPane('sessions', 'sessions', { collapsible: true, placement: 'left', width: '237px' }, 'session rows')
  registerPane('bots', 'Bots', { collapsible: true, placement: 'left', width: '260px' }, 'bot roster')
  registerPane('workspace', 'workspace', { placement: 'main', uncloseable: true }, 'chat')

  declareDefaultTree(split('row', [group(['sessions', 'bots']), group(['workspace'])]))
  $narrowViewport.set(true)
})

afterEach(() => {
  cleanup()
  $narrowViewport.set(false)
  $layoutTree.set(null)
  $connection.set(null)
  vi.restoreAllMocks()
  delete (window as unknown as { hermesDesktop?: unknown }).hermesDesktop
  disposers.splice(0).forEach(dispose => dispose())
})

const revealPane = (id: string) => {
  act(() => {
    window.dispatchEvent(new CustomEvent(PANE_TOGGLE_REVEAL_EVENT, { detail: { id, mode: 'open' } }))
  })
}

const overlayTab = (paneId: string) => document.querySelector<HTMLElement>(`[data-narrow-overlay-tab="${paneId}"]`)

describe('narrow overlay of a stacked zone', () => {
  it('mirrors the zone tab strip so every stacked collapsible stays reachable', () => {
    const { getByTestId, queryByTestId } = render(<NarrowOverlays />)

    revealPane('sessions')

    // Both zone-mates surface as tabs; the revealed pane's body is on screen.
    expect(overlayTab('sessions')).toBeTruthy()
    expect(overlayTab('bots')).toBeTruthy()
    expect(getByTestId('sessions-body')).toBeTruthy()
    expect(queryByTestId('bots-body')).toBeNull()

    // Clicking the BOTS tab swaps the overlay to the docked pane.
    fireEvent.pointerDown(overlayTab('bots')!, { button: 0 })
    expect(getByTestId('bots-body')).toBeTruthy()
    expect(queryByTestId('sessions-body')).toBeNull()
  })

  it('keeps the stripless form for a zone with a single collapsible', () => {
    // Direct set: declareDefaultTree only ADOPTS into an existing tree — it
    // would keep the beforeEach zone (with bots) instead of replacing it.
    $layoutTree.set(split('row', [group(['sessions']), group(['workspace'])]))

    const { getByTestId } = render(<NarrowOverlays />)

    revealPane('sessions')

    expect(getByTestId('sessions-body')).toBeTruthy()
    expect(overlayTab('sessions')).toBeNull()
  })

  it('pads the overlay below the native window controls on macOS', () => {
    // Ground truth for "the SESSIONS tab strip slides under the traffic
    // lights on a narrow window" (#110033). The overlay starts at the
    // viewport's top edge, so without a reservation its tab strip sits under
    // the native controls.
    Object.defineProperty(window, 'hermesDesktop', { configurable: true, value: {} })
    $connection.set({ windowButtonPosition: { x: 24, y: 0 } } as never)
    // jsdom has no layout: the overlay fills the viewport's top-left corner.
    vi.spyOn(HTMLElement.prototype, 'getBoundingClientRect').mockReturnValue({
      bottom: 800,
      height: 800,
      left: 0,
      right: 237,
      toJSON: () => ({}),
      top: 0,
      width: 237,
      x: 0,
      y: 0
    } as DOMRect)

    render(<NarrowOverlays />)
    revealPane('sessions')

    // Controls rect = { x: 0, y: 0, width: 24 + 58, height: 34 }; the
    // reservation is the overlap's bottom edge, so the strip starts below it.
    const overlay = document.querySelector<HTMLElement>('[data-narrow-overlay="sessions"]')
    expect(overlay?.style.paddingTop).toBe('34px')
    // The reserved band stays a window-drag target, as in a docked TreeGroup.
    const dragSpacer = overlay?.querySelector<HTMLElement>('[aria-hidden="true"]')
    expect(dragSpacer).not.toBeNull()
    expect(dragSpacer?.style.height).toBe('34px')
  })

  it('honors the user drag width, not the declared width, when the zone collapsed', () => {
    // The sash writes a widthOverride per shown pane of the zone; the overlay
    // must size from the same resolution the docked zone uses (fixedTrackSize
    // = declared max() refined by overrides), not from data.width alone.
    // jsdom's CSSOM drops the min() wrapper from style.width, so the rendered
    // width is unobservable here — assert the overlay's own resolution
    // (narrowOverlayWidth, the pure helper the component styles from) against
    // the live tree + store the mounted overlay saw.
    setPaneWidthOverride('sessions', 170)
    setPaneWidthOverride('bots', 170)

    const { container } = render(<NarrowOverlays />)

    revealPane('bots')

    const overlay = container.querySelector<HTMLElement>('[data-narrow-overlay]')
    expect(overlay).toBeTruthy()

    const tree = $layoutTree.get()!
    const bots = registry.getArea('panes').find(p => p.id === 'bots')!

    const width = narrowOverlayWidth(
      {
        paneFor: id => registry.getArea('panes').find(p => p.id === id),
        paneGone: () => false,
        overrides: $paneStates.get()
      },
      tree,
      bots
    )

    // The user dragged the zone to 170px; the declared 260px must lose.
    expect(width).toBe('170px')
    expect(width).not.toBe('260px')

    // And the seamless fallback: without a tree the declared width still
    // sizes the overlay.
    expect(narrowOverlayWidth({ paneFor: () => undefined, paneGone: () => false, overrides: {} }, null, bots)).toBe(
      '260px'
    )
  })
})

import { act, cleanup, renderHook } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import type { HermesConnection } from '@/global'
import { $connection } from '@/store/session'
import { stubResizeObserver } from '@/test/jsdom'

import { usePanelTitlebar } from './panel-titlebar'

// The panel tab strip (SESSIONS | BOTS) reserves the width the fixed titlebar
// clusters cover by MEASURING them. On a macOS fullscreen transition the left
// cluster moves to the window edge without changing size, so neither the
// ResizeObserver nor the window `resize` (which fires before the state IPC
// lands) re-measures — the reservation stayed stale until a sidebar toggle or
// reload (#108641). Chrome-state changes must schedule a re-measure.

let clusterLeft = 100

function rect(left: number, width: number): DOMRect {
  return { bottom: 34, height: 34, left, right: left + width, top: 0, width, x: left, y: 0 } as DOMRect
}

beforeEach(() => {
  // Re-stub per test: `vi.unstubAllGlobals()` in afterEach drops it too.
  stubResizeObserver()
  clusterLeft = 100
  const left = document.createElement('div')
  left.dataset.titlebarCluster = 'left'
  left.getBoundingClientRect = () => rect(clusterLeft, 60)
  const right = document.createElement('div')
  right.dataset.titlebarCluster = 'right'
  right.getBoundingClientRect = () => rect(900, 80)
  document.body.append(left, right)
  $connection.set({ isFullscreen: false, windowButtonPosition: { x: 20, y: 10 } } as unknown as HermesConnection)
  vi.stubGlobal('requestAnimationFrame', (cb: FrameRequestCallback) => {
    cb(0)

    return 0
  })
  vi.stubGlobal('cancelAnimationFrame', () => undefined)
})

afterEach(() => {
  cleanup()
  document.body.innerHTML = ''
  vi.unstubAllGlobals()
  $connection.set(null)
})

describe('usePanelTitlebar', () => {
  it('re-measures the cluster reservation when the window chrome state moves the clusters', () => {
    const element = document.createElement('div')
    element.getBoundingClientRect = () => rect(0, 1000)
    document.body.append(element)
    const ref = { current: element }

    renderHook(() => usePanelTitlebar(ref, true, false))
    expect(element.style.getPropertyValue('--panel-titlebar-left')).toBe('172px')

    // Fullscreen: the traffic lights vanish and the cluster pins to the edge —
    // a pure translate. No ResizeObserver callback, no `resize` event.
    clusterLeft = 14
    act(() => {
      $connection.set({ ...$connection.get()!, isFullscreen: true })
    })

    expect(element.style.getPropertyValue('--panel-titlebar-left')).toBe('86px')
  })

  it('ignores connection updates that leave the chrome where it is', () => {
    const element = document.createElement('div')
    element.getBoundingClientRect = () => rect(0, 1000)
    document.body.append(element)
    const ref = { current: element }

    renderHook(() => usePanelTitlebar(ref, true, false))
    // A stale-geometry read must not be re-committed by an unrelated update
    // (e.g. a status heartbeat): only chrome-moving fields trigger a measure.
    clusterLeft = 14
    act(() => {
      $connection.set({ ...$connection.get()!, connected: true } as HermesConnection)
    })

    expect(element.style.getPropertyValue('--panel-titlebar-left')).toBe('172px')
  })
})

