import { cleanup, fireEvent, render } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { registry } from '@/contrib/registry'

import { allPaneIds, group, split } from '../model'
import { $layoutTree } from '../store'

import { TreeGroup } from './tree-group'

// The hover ✕ and middle-click are ONE affordance in two shapes: whichever tabs
// the pointer gesture can close must advertise it. A tab that closes on
// middle-click but hides its ✕ is a close verb the user cannot discover, and a
// tab that shows a ✕ it will not honor is a dead control. This asserts the
// equivalence over every tab kind the app registers, so the ✕ can never be
// wired (or un-wired) on its own again.

class TestResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}

beforeAll(() => {
  vi.stubGlobal('ResizeObserver', TestResizeObserver)
  // jsdom lacks CSS.escape, which tab-strip-scroll uses in a layout effect.
  vi.stubGlobal('CSS', { ...globalThis.CSS, escape: (value: string) => value })
  Element.prototype.hasPointerCapture ??= () => false
  Element.prototype.setPointerCapture ??= () => undefined
  Element.prototype.releasePointerCapture ??= () => undefined
  HTMLElement.prototype.scrollIntoView ??= () => undefined
})

const disposers: (() => void)[] = []

/** Every tab kind that shares a strip, paired with what its chrome declares. */
const PANES: readonly (readonly [string, Record<string, unknown>])[] = [
  // Standing chrome: no close gesture of any kind.
  ['sessions', { hideOnly: true, placement: 'left' }],
  // A plain side pane: closes, so it must say so.
  ['files', { placement: 'right' }],
  // The one surface that cannot leave the tree.
  ['workspace', { placement: 'main', uncloseable: true }],
  // A mirrored session tile — `placement: 'main'` but closeable.
  ['session-tile:abc', { placement: 'main' }]
]

beforeEach(async () => {
  window.localStorage.clear()

  const { $dismissedPanes, $hiddenTreePanes } = await import('../store')
  $dismissedPanes.set(new Set())
  $hiddenTreePanes.set(new Set())

  for (const [id, data] of PANES) {
    disposers.push(registry.register({ area: 'panes', data, id, render: () => null, title: id }))
  }
})

afterEach(() => {
  cleanup()
  disposers.splice(0).forEach(dispose => dispose())
})

/** All four panes in ONE zone, so every tab renders in the same strip. */
function renderOneStrip() {
  $layoutTree.set(
    split('row', [
      group(
        PANES.map(([id]) => id),
        { active: 'workspace', id: 'grp-all' }
      ),
      group(['spacer'], { id: 'grp-spacer' })
    ])
  )

  const node = $layoutTree.get()!
  const zone = (node.type === 'split' ? node.children[0] : node) as never

  render(<TreeGroup node={zone} parentAxis="row" />)
}

const tabEl = (paneId: string) => document.querySelector<HTMLElement>(`[data-tree-tab="${paneId}"]`)

/** Does this tab advertise a ✕? */
const hasCloseButton = (paneId: string) => Boolean(tabEl(paneId)?.querySelector('button[aria-label]'))

/** Does the middle-click gesture actually close this tab? Observed through the
 *  tree, not through a spy — a pane that is gone stopped being a tab. */
function middleClickCloses(paneId: string): boolean {
  const tab = tabEl(paneId)!
  fireEvent.pointerDown(tab, { button: 1 })
  fireEvent.pointerUp(tab, { button: 1 })

  return !allPaneIds($layoutTree.get()!).includes(paneId)
}

describe('a tab advertises exactly the close gesture it honors', () => {
  for (const [paneId] of PANES) {
    it(`${paneId}: ✕ presence matches middle-click`, () => {
      renderOneStrip()

      expect(tabEl(paneId)).toBeTruthy()

      const advertised = hasCloseButton(paneId)

      expect(advertised).toBe(middleClickCloses(paneId))
    })
  }
})

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { registry } from '@/contrib/registry'
import { stubMenuDomApis, stubResizeObserver } from '@/test/jsdom'

import { group, split } from '../model'
import {
  $layoutTree,
  declareDefaultTree,
  markCollapsePane,
  noteActiveTreeGroup,
  registerPaneCloser,
  setTreeGroupMinimized
} from '../store'

import { TreeGroup } from './tree-group'

// Ground truth for "right-clicking logs doesn't even show Close, and ⌘W
// doesn't close it". Renders the REAL zone renderer and opens the REAL
// context menu.

beforeAll(() => {
  stubResizeObserver()
  stubMenuDomApis()
  // jsdom lacks CSS.escape, which tab-strip-scroll uses in a layout effect.
  vi.stubGlobal('CSS', { ...globalThis.CSS, escape: (value: string) => value })
})

const disposers: (() => void)[] = []

beforeEach(async () => {
  window.localStorage.clear()

  // Per-test isolation: earlier cases dismiss / hide panes, and both records
  // live in module state that survives into the next test.
  const { $dismissedPanes, $hiddenTreePanes } = await import('../store')
  $dismissedPanes.set(new Set())
  $hiddenTreePanes.set(new Set())

  for (const [id, data] of [
    ['workspace', { placement: 'main', uncloseable: true }],
    ['terminal', { placement: 'bottom' }],
    ['logs', { placement: 'bottom' }]
  ] as const) {
    disposers.push(registry.register({ area: 'panes', data, id, render: () => null, title: id }))
  }

  markCollapsePane('terminal')
  markCollapsePane('logs')
  registerPaneCloser('terminal', () => undefined)
  registerPaneCloser('logs', () => undefined)
})

afterEach(() => {
  cleanup()
  disposers.splice(0).forEach(dispose => dispose())
})

/** Radix opens a ContextMenu on contextmenu after a pointerdown positions it. */
function openContextMenu(target: HTMLElement) {
  fireEvent.pointerDown(target, { button: 2, pointerType: 'mouse' })
  fireEvent.contextMenu(target, { button: 2 })
}

const zoneAt = (index: number) => {
  const node = $layoutTree.get()!

  return (node.type === 'split' ? node.children[index] : node) as never
}

const tabEl = (paneId: string) => document.querySelector<HTMLElement>(`[data-tree-tab="${paneId}"]`)

describe('right-clicking a tool panel tab', () => {
  it('offers Close when logs is STACKED with the terminal', async () => {
    declareDefaultTree(
      split('column', [
        group(['workspace'], { active: 'workspace', id: 'grp-main' }),
        group(['terminal', 'logs'], { active: 'logs', id: 'grp-tools' })
      ])
    )
    render(<TreeGroup node={zoneAt(1)} parentAxis="column" />)

    openContextMenu(tabEl('logs')!)

    expect(await screen.findByRole('menuitem', { name: /^close$/i })).toBeTruthy()
  })

  it('offers Close when logs is ALONE in its zone', async () => {
    declareDefaultTree(
      split('column', [
        group(['workspace'], { active: 'workspace', id: 'grp-main' }),
        group(['logs'], { active: 'logs', id: 'grp-logs' })
      ])
    )
    render(<TreeGroup node={zoneAt(1)} parentAxis="column" />)

    const tab = tabEl('logs')
    expect(tab).toBeTruthy()

    openContextMenu(tab!)

    expect(await screen.findByRole('menuitem', { name: /^close$/i })).toBeTruthy()
  })

  it('offers Close while the zone is MINIMIZED to its rail', async () => {
    declareDefaultTree(
      split('column', [
        group(['workspace'], { active: 'workspace', id: 'grp-main' }),
        group(['terminal', 'logs'], { active: 'logs', id: 'grp-tools' })
      ])
    )
    setTreeGroupMinimized('grp-tools', true)
    render(<TreeGroup node={zoneAt(1)} parentAxis="column" />)

    openContextMenu(tabEl('logs')!)

    expect(await screen.findByRole('menuitem', { name: /^close$/i })).toBeTruthy()
  })
})

describe('⌘W over a focused tool panel', () => {
  it('closes the logs tab and the toggle brings it back', async () => {
    const { closeActiveTab } = await import('@/app/chat/close-tab')
    const { allPaneIds } = await import('../model')
    const { revealTreePane, setPaneCollapsed } = await import('../store')

    declareDefaultTree(
      split('column', [
        group(['workspace'], { active: 'workspace', id: 'grp-main' }),
        group(['terminal', 'logs'], { active: 'logs', id: 'grp-tools' })
      ])
    )

    // Production wiring (bindPaneCollapse): a store drives visibility, its
    // closer collapses, its opener reveals.
    let open = true
    registerPaneCloser('logs', () => {
      open = false
      setPaneCollapsed('logs', true)
    })

    // The user clicked into the tools zone — ⌘W must act on ITS active tab.
    noteActiveTreeGroup('grp-tools')

    closeActiveTab()

    // The tab left the strip, and the toggle knows the pane is off.
    expect(allPaneIds($layoutTree.get()!)).not.toContain('logs')
    expect(open).toBe(false)

    // Toggling it back on re-adopts the pane (revealTreePane un-dismisses).
    open = true
    revealTreePane('logs')

    expect(allPaneIds($layoutTree.get()!)).toContain('logs')
  })

  it('leaves the uncloseable workspace zone to the chat rung', async () => {
    const { allPaneIds } = await import('../model')
    const { closeFocusedToolTab } = await import('../store')

    declareDefaultTree(
      split('column', [
        group(['workspace'], { active: 'workspace', id: 'grp-main' }),
        group(['logs'], { active: 'logs', id: 'grp-logs' })
      ])
    )

    noteActiveTreeGroup('grp-main')

    // Pointer/focus on main: the tool rung must decline, not reach across and
    // close the logs pane the user isn't looking at.
    expect(closeFocusedToolTab()).toBe(false)
    expect(allPaneIds($layoutTree.get()!)).toContain('logs')
  })
})

import { cleanup, fireEvent, render } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { registry } from '@/contrib/registry'
import { $paneStates } from '@/store/panes'

import { group, split, type SplitNode } from '../model'
import { $hiddenTreePanes, $layoutTree, markCollapsePane, setTreeGroupMinimized } from '../store'

import { TreeSplit } from './tree-split'

class TestResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}

const disposers: (() => void)[] = []

beforeAll(() => {
  vi.stubGlobal('ResizeObserver', TestResizeObserver)
  vi.stubGlobal('CSS', { ...globalThis.CSS, escape: (value: string) => value })
  vi.stubGlobal('requestAnimationFrame', () => 1)
  vi.stubGlobal('cancelAnimationFrame', () => undefined)
  Element.prototype.hasPointerCapture ??= () => false
  Element.prototype.setPointerCapture ??= () => undefined
  Element.prototype.releasePointerCapture ??= () => undefined
})

beforeEach(() => {
  window.localStorage.clear()
  $hiddenTreePanes.set(new Set())
  $paneStates.set({})

  disposers.push(
    registry.register({ area: 'panes', data: { placement: 'main' }, id: 'chat', render: () => null, title: 'Chat' }),
    registry.register({
      area: 'panes',
      data: { placement: 'main', width: '100px' },
      id: 'cron',
      render: () => null,
      title: 'Cron'
    }),
    registry.register({
      area: 'panes',
      data: { placement: 'main' },
      id: 'browser',
      render: () => null,
      title: 'Browser'
    })
  )
})

afterEach(() => {
  cleanup()
  $layoutTree.set(null)
  $paneStates.set({})
  disposers.splice(0).forEach(dispose => dispose())
})

function rect(width: number): DOMRect {
  return {
    bottom: 600,
    height: 600,
    left: 0,
    right: width,
    toJSON: () => ({}),
    top: 0,
    width,
    x: 0,
    y: 0
  } as DOMRect
}

function setWidth(element: HTMLElement, width: number) {
  Object.defineProperty(element, 'getBoundingClientRect', { configurable: true, value: () => rect(width) })
}

function setHeight(element: HTMLElement, height: number) {
  Object.defineProperty(element, 'getBoundingClientRect', {
    configurable: true,
    value: () => ({ ...rect(1000), bottom: height, height })
  })
}

function row(): SplitNode {
  const tree = $layoutTree.get()

  if (!tree || tree.type !== 'split') {
    throw new Error('expected root row split')
  }

  return tree
}

describe('TreeSplit cascading expansion', () => {
  it('grows Browser through Cron into Chat after Cron reaches its minimum', () => {
    const tree = split(
      'row',
      [
        group(['chat'], { id: 'chat-zone' }),
        group(['cron'], { id: 'cron-zone' }),
        group(['browser'], { id: 'browser-zone' })
      ],
      [5, 1, 2],
      'root-row'
    )

    $layoutTree.set(tree)

    render(<TreeSplit node={tree} root rootRow />)

    const container = document.querySelector<HTMLElement>('[data-tree-split="root-row"]')!
    const [chat, cron, browser] = [...container.children] as HTMLElement[]
    setWidth(container, 800)
    setWidth(chat, 500)
    setWidth(cron, 100)
    setWidth(browser, 200)
    setWidth(document.querySelector<HTMLElement>('[data-tree-group="cron-zone"]')!, 100)

    const browserSash = document.querySelectorAll('[role="separator"]')[1]!
    fireEvent.pointerDown(browserSash, { button: 0, clientX: 600, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerMove(window, { clientX: 300, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerUp(window, { clientX: 300, pointerId: 1, pointerType: 'mouse' })

    // Browser's 300px requested growth first takes Cron from 100px to its
    // 80px floor, then takes the remaining 280px from Chat. The browser gets
    // every released pixel instead of stopping at Cron's local floor.
    expect($paneStates.get().cron?.widthOverride).toBe(80)
    expect(row().weights).toEqual([2.2, 1, 5])
  })
  it('commits a regular cascade when an unrelated tool rail is already minimized', () => {
    markCollapsePane('terminal')
    disposers.push(
      registry.register({
        area: 'panes',
        data: { maxWidth: '600px', minWidth: '160px', placement: 'right', width: '200px' },
        id: 'browser',
        render: () => null,
        title: 'Browser'
      }),
      registry.register({
        area: 'panes',
        data: { placement: 'bottom' },
        id: 'terminal',
        render: () => null,
        title: 'Terminal'
      })
    )

    const tree = split(
      'row',
      [
        group(['chat'], { id: 'chat-zone' }),
        group(['cron'], { id: 'cron-zone' }),
        group(['browser'], { id: 'browser-zone' }),
        group(['terminal'], { id: 'terminal-zone' })
      ],
      [5, 1, 2, 0.28],
      'root-row'
    )

    $layoutTree.set(tree)
    $paneStates.set({ browser: { open: true, widthOverride: 200 } })
    setTreeGroupMinimized('terminal-zone', true)

    render(<TreeSplit node={row()} root rootRow />)

    const container = document.querySelector<HTMLElement>('[data-tree-split="root-row"]')!
    const [chat, cron, browser, terminal] = [...container.children] as HTMLElement[]
    setWidth(container, 828)
    setWidth(chat, 500)
    setWidth(cron, 100)
    setWidth(browser, 200)
    setWidth(terminal, 28)
    setWidth(document.querySelector<HTMLElement>('[data-tree-group="cron-zone"]')!, 100)
    setWidth(document.querySelector<HTMLElement>('[data-tree-group="browser-zone"]')!, 200)
    setWidth(document.querySelector<HTMLElement>('[data-tree-group="terminal-zone"]')!, 28)

    const browserSash = document.querySelectorAll('[role="separator"]')[1]!
    fireEvent.pointerDown(browserSash, { button: 0, clientX: 600, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerMove(window, { clientX: 300, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerUp(window, { clientX: 300, pointerId: 1, pointerType: 'mouse' })

    expect($paneStates.get().cron?.widthOverride).toBe(80)
    expect($paneStates.get().browser?.widthOverride).toBe(500)
    expect(row().weights[0]).toBeCloseTo(2.2)
    expect(row().children[3]).toMatchObject({ id: 'terminal-zone', minimized: true })
  })
  it('folding a tool zone at its floor leaves no drag preview pinned on the flex sibling', () => {
    markCollapsePane('terminal')
    disposers.push(
      registry.register({
        area: 'panes',
        data: { height: '200px', placement: 'bottom' },
        id: 'terminal',
        render: () => null,
        title: 'Terminal'
      })
    )

    const tree = split(
      'column',
      [group(['chat'], { id: 'chat-zone' }), group(['terminal'], { id: 'terminal-zone' })],
      [1, 1],
      'root-column'
    )

    $layoutTree.set(tree)

    render(<TreeSplit node={tree} root />)

    const container = document.querySelector<HTMLElement>('[data-tree-split="root-column"]')!
    const [chat, terminal] = [...container.children] as HTMLElement[]
    setHeight(container, 800)
    setHeight(chat, 600)
    setHeight(terminal, 200)
    setHeight(document.querySelector<HTMLElement>('[data-tree-group="terminal-zone"]')!, 200)

    const chatFlex = chat.style.flex
    const terminalSash = document.querySelectorAll('[role="separator"]')[0]!
    fireEvent.pointerDown(terminalSash, { button: 0, clientY: 600, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerMove(window, { clientY: 790, pointerId: 1, pointerType: 'mouse' })
    fireEvent.pointerUp(window, { clientY: 790, pointerId: 1, pointerType: 'mouse' })

    // The zone folds to its rail (no sliver persisted) and the chat wrapper —
    // which the commit does not re-render — is back on React's own flex, not
    // the `0 1 <px>` pin the gesture previewed.
    expect(row().children[1]).toMatchObject({ id: 'terminal-zone', minimized: true })
    expect($paneStates.get().terminal?.heightOverride).toBeUndefined()
    expect(chat.style.flex).toBe(chatFlex)
  })
})

import { cleanup, fireEvent, render } from '@testing-library/react'
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

import { registry } from '@/contrib/registry'
import { $paneStates } from '@/store/panes'

import { group, split } from '../model'
import { $hiddenTreePanes, $layoutTree } from '../store'

import { TreeSplit } from './tree-split'

class TestResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}

const disposers: (() => void)[] = []

beforeAll(() => {
  vi.stubGlobal('ResizeObserver', TestResizeObserver)
  vi.stubGlobal('CSS', { ...globalThis.CSS, escape: (value: string) => value })
  // Flush the drag preview on the same turn so mid-drag styles are observable.
  vi.stubGlobal('requestAnimationFrame', (cb: FrameRequestCallback) => {
    cb(0)

    return 1
  })
  vi.stubGlobal('cancelAnimationFrame', () => undefined)
  Element.prototype.hasPointerCapture ??= () => false
  Element.prototype.setPointerCapture ??= () => undefined
  Element.prototype.releasePointerCapture ??= () => undefined
})

beforeEach(() => {
  window.localStorage.clear()
  $hiddenTreePanes.set(new Set())
  $paneStates.set({})

  disposers.push(
    registry.register({
      area: 'panes',
      data: { placement: 'main' },
      id: 'workspace',
      render: () => null,
      title: 'Chat'
    }),
    registry.register({
      area: 'panes',
      data: { maxWidth: '320px', minWidth: '160px', placement: 'right', width: '237px' },
      id: 'review',
      render: () => null,
      title: 'Review'
    }),
