import { reactRoot } from '@/test/react-root'

import { installWindowStateBridge, setDocumentHidden, type WindowStateBridge } from '../../test/window-state'

import { PetSprite } from './pet-sprite'

const INFO = {
  enabled: true,
  frameH: 16,
  frameW: 16,
  framesPerState: 2,
  loopMs: 120,
  scale: 1,
  spritesheetBase64: 'stub',
  stateRows: ['idle']
}

const mount = reactRoot()
let windowState: WindowStateBridge
let drawImage: ReturnType<typeof vi.fn>

function installRaf() {
  let nextId = 1
  const frames = new Map<number, FrameRequestCallback>()

  const request = vi.fn((callback: FrameRequestCallback) => {
    const id = nextId++
    frames.set(id, callback)

    return id
  })

  const cancel = vi.fn((id: number) => {
    frames.delete(id)
  })

  Object.defineProperty(window, 'requestAnimationFrame', { configurable: true, value: request })
  Object.defineProperty(window, 'cancelAnimationFrame', { configurable: true, value: cancel })

  return {
    cancel,
    pending: () => frames.size,
    request,
    runNext: (now: number) => {
      const next = frames.entries().next().value

      if (!next) {
        throw new Error('No pending RAF')
      }

      const [id, callback] = next
      frames.delete(id)
      callback(now)
    }
  }
}

describe('PetSprite RAF scheduling', () => {
  beforeEach(() => {
    ;(globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true
    vi.useFakeTimers()
    setDocumentHidden(false)
    Object.defineProperty(window, 'devicePixelRatio', { configurable: true, value: 1 })
    vi.spyOn(document, 'hasFocus').mockReturnValue(true)
    windowState = installWindowStateBridge()
    vi.stubGlobal(
      'Image',
      class extends EventTarget {
        complete = true
        naturalWidth = 16
        src = ''
      } as unknown as typeof Image
    )
    drawImage = vi.fn()
    vi.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue({
      clearRect: vi.fn(),
      drawImage,
      imageSmoothingEnabled: false
    } as unknown as CanvasRenderingContext2D)
  })

  afterEach(() => {
    mount.unmount()
    vi.useRealTimers()
    vi.unstubAllGlobals()
    vi.restoreAllMocks()
    setDocumentHidden(false)
    delete (window as unknown as { hermesDesktop?: unknown }).hermesDesktop
  })

  it('sleeps between visible sprite frames instead of chaining RAFs', () => {
    const raf = installRaf()

    mount.render(<PetSprite info={INFO} />)

    expect(raf.request).toHaveBeenCalledTimes(1)

    act(() => {
      raf.runNext(0)
    })

    expect(raf.request).toHaveBeenCalledTimes(1)
    expect(raf.pending()).toBe(0)
    expect(vi.getTimerCount()).toBe(1)

    act(() => {
      vi.advanceTimersByTime(60)
    })

    expect(raf.request).toHaveBeenCalledTimes(2)
  })

  it('uses a DPR-sized backing store while preserving the CSS footprint', () => {
    Object.defineProperty(window, 'devicePixelRatio', { configurable: true, value: 2 })
    const raf = installRaf()

    mount.render(<PetSprite info={INFO} />)

    const canvas = mount.container?.querySelector('canvas')

    expect(canvas).not.toBeNull()
    expect(canvas?.width).toBe(32)
    expect(canvas?.height).toBe(32)
    expect(canvas?.style.width).toBe('16px')
    expect(canvas?.style.height).toBe('16px')

    act(() => {
      raf.runNext(0)
    })

    expect(drawImage).toHaveBeenCalledWith(expect.anything(), 0, 0, 16, 16, 0, 0, 32, 32)
  })

  it('cancels pending RAF work while the Electron window is paused and resumes when visible', () => {
    const raf = installRaf()

    mount.render(<PetSprite info={INFO} />)

    expect(raf.request).toHaveBeenCalledTimes(1)

    act(() => {
      windowState.emit({ isMinimized: true, isVisible: false })
    })

    expect(raf.cancel).toHaveBeenCalledTimes(1)
    expect(raf.pending()).toBe(0)

    act(() => {
      windowState.emit({ isMinimized: false, isVisible: true })
    })

    expect(raf.request).toHaveBeenCalledTimes(2)
  })

  it('keeps animating while unfocused and leaves no work after unmount', () => {
    const raf = installRaf()

    mount.render(<PetSprite info={INFO} />)

    act(() => window.dispatchEvent(new Event('blur')))
    expect(raf.pending()).toBe(1)

    act(() => window.dispatchEvent(new Event('focus')))
    expect(raf.pending()).toBe(1)

    act(() => raf.runNext(0))
    expect(vi.getTimerCount()).toBe(1)

    mount.unmount()
    expect(raf.pending()).toBe(0)
    expect(vi.getTimerCount()).toBe(0)

    act(() => {
      vi.advanceTimersByTime(500)
      window.dispatchEvent(new Event('focus'))
    })
    expect(raf.pending()).toBe(0)
  })
})

import { act } from 'react'
import { createRoot, type Root } from 'react-dom/client'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { PixelEggSprite } from './pixel-egg-sprite'

let root: Root | null = null
let container: HTMLDivElement | null = null

function render(mode: 'bounce' | 'hatch', onDone?: () => void) {
  container = document.createElement('div')
  document.body.append(container)
  root = createRoot(container)

  act(() => {
    root!.render(<PixelEggSprite mode={mode} onDone={onDone} size={32} />)
  })
}

function cleanup() {
  if (root) {
    act(() => {
      root!.unmount()
    })
  }

  container?.remove()
  root = null
  container = null
}

function installRaf(startId = 1) {
  let nextId = startId
  const frames = new Map<number, FrameRequestCallback>()

  const request = vi.fn((callback: FrameRequestCallback) => {
    const id = nextId++
    frames.set(id, callback)

    return id
  })

  const cancel = vi.fn((id: number) => {
    frames.delete(id)
  })

  Object.defineProperty(window, 'requestAnimationFrame', { configurable: true, value: request })
  Object.defineProperty(window, 'cancelAnimationFrame', { configurable: true, value: cancel })

  return {
    pending: () => frames.size,
    request,
    runNext: (now: number) => {
      const next = frames.entries().next().value

      if (!next) {
        throw new Error('No pending RAF')
      }

      const [id, callback] = next
      frames.delete(id)
      callback(now)
    }
  }
}

describe('PixelEggSprite scheduling', () => {
  beforeEach(() => {
    ;(globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true
    vi.useFakeTimers()
    vi.spyOn(Math, 'random').mockReturnValue(0)
    Object.defineProperty(window, 'devicePixelRatio', { configurable: true, value: 1 })
    vi.stubGlobal(
      'Image',
      class {
        complete = true
        onerror: (() => undefined) | null = null
        onload: (() => undefined) | null = null

        set src(_value: string) {
          queueMicrotask(() => this.onload?.())
        }
      } as unknown as typeof Image
    )
    vi.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue({
      clearRect: vi.fn(),
      drawImage: vi.fn(),
      getImageData: vi.fn(() => ({ data: new Uint8ClampedArray(32 * 32 * 4) })),
      imageSmoothingEnabled: false,
      putImageData: vi.fn()
    } as unknown as CanvasRenderingContext2D)
  })

  afterEach(() => {
    cleanup()
    vi.useRealTimers()
    vi.unstubAllGlobals()
    vi.restoreAllMocks()
  })

  it('sleeps during the long bounce rest instead of chaining RAFs', async () => {
    const raf = installRaf()

    render('bounce')
    await act(async () => undefined)

    act(() => {
      raf.runNext(0)
    })

    expect(raf.pending()).toBe(0)
    expect(vi.getTimerCount()).toBe(1)

    act(() => {
      vi.advanceTimersByTime(650)
    })

    expect(raf.pending()).toBe(1)

    cleanup()
    expect(raf.pending()).toBe(0)
    expect(vi.getTimerCount()).toBe(0)
  })

  it('stops scheduling frames after the final hatch frame', async () => {
    const raf = installRaf()
    const onDone = vi.fn()

    render('hatch', onDone)
    await act(async () => undefined)

    act(() => {
      raf.runNext(0)
    })

    for (const now of [190, 380, 570, 760, 950]) {
      act(() => {
        vi.advanceTimersByTime(162)
      })

      act(() => {
        raf.runNext(now)
      })
    }

    expect(onDone).toHaveBeenCalledTimes(1)
    expect(raf.pending()).toBe(0)
  })

  it('cancels a pending animation frame even when the browser assigns ID zero', async () => {
    const raf = installRaf(0)

    render('bounce')
    await act(async () => undefined)

    expect(raf.pending()).toBe(1)
    cleanup()
    expect(raf.pending()).toBe(0)
  })
})

