function clearSidebarFilters() {
  $sidebarStatusFilter.set([])
  $sidebarProjectFilter.set([])
  $sidebarProfileFilter.set([])
  $sidebarPrFilter.set([])
  $sidebarShowArchived.set(false)
}

/** Every knob the filter menu owns, back to the sidebar as it ships. Ordering
 *  goes through its setter so a hand-dragged sequence is dropped along with it. */
export function resetSidebarView() {
  setSidebarGrouping(SIDEBAR_DEFAULT_GROUPING)
  // Both scopes, not just the one on screen: each keeps its own grouping (and
  // its own Project flag), so a reset that left the other customized would
  // hand it back on the next flip.
  $sidebarFlatGrouping.set(SIDEBAR_DEFAULT_GROUPING)
  $sidebarAllProfilesGrouping.set(SIDEBAR_DEFAULT_GROUPING)
  $sidebarFlatAgentsGrouped.set(false)
  $sidebarAllProfilesAgentsGrouped.set(false)
  setSidebarOrdering(SIDEBAR_DEFAULT_ORDERING)
  $sidebarRowMeta.set(SIDEBAR_DEFAULT_ROW_META)
  $sidebarCardRows.set(false)
  $sidebarShowAllSessions.set(false)
  clearSidebarFilters()
}

/** Whether anything on screen needs PR data — the gate on shelling out to
 *  `gh`. Nobody pays for a network call per repo to render a view that would
 *  not show a PR anywhere. */
export const $sidebarPrDataWanted: ReadableAtom<boolean> = computed(
  [$sidebarRowMeta, $sidebarPrFilter],
  (rowMeta, prFilter) => rowMeta.includes('pr') || prFilter.length > 0
)

// Write an order list only when it actually changed, so an identical drag
// result keeps the same array reference and subscribers don't churn.
function setOrderIds($atom: WritableAtom<string[]>, ids: string[]) {
  if (!arraysEqual($atom.get(), ids)) {
    $atom.set(ids)
  }
}

export function setSidebarSessionOrderIds(ids: string[]) {
  setOrderIds($sidebarSessionOrderIds, ids)
}

export function setSidebarSessionOrderManual(manual: boolean) {
  if ($sidebarSessionOrderManual.get() !== manual) {
    $sidebarSessionOrderManual.set(manual)
  }
}

export function setSidebarWorkspaceOrderIds(ids: string[]) {
  setOrderIds($sidebarWorkspaceOrderIds, ids)
}

export function setSidebarWorkspaceParentOrderIds(ids: string[]) {
  setOrderIds($sidebarWorkspaceParentOrderIds, ids)
}

export function setSidebarProjectOrderIds(ids: string[]) {
  setOrderIds($sidebarProjectOrderIds, ids)
}

export function setSidebarResizing(resizing: boolean) {
  $isSidebarResizing.set(resizing)
}

export function pinSession(sessionId: string, index?: number) {
  const prev = $pinnedSessionIds.get()

  setOrderIds($pinnedSessionIds, insertUniqueId(prev, sessionId, index ?? prev.filter(id => id !== sessionId).length))
}

export function unpinSession(sessionId: string) {
  setOrderIds(
    $pinnedSessionIds,
    $pinnedSessionIds.get().filter(id => id !== sessionId)
  )
}

// Apply a new pinned order from a drag. The dragged list only holds the pins
// that currently RESOLVE to a loaded row, so this is a permutation of a subset:
// re-slot the ids it names into the positions they already occupied, leaving
// any pin it doesn't mention (row not loaded yet) exactly where it was.
// Requiring both lists to be the same length instead let one unresolved pin
// silently discard the whole reorder.
export function setPinnedSessionOrder(ids: string[]) {
  const prev = $pinnedSessionIds.get()
  const pinned = new Set(prev)
  const moving = ids.filter(id => pinned.has(id))

  if (!moving.length) {
    return
  }

  const movingSet = new Set(moving)
  const next = [...prev]
  let cursor = 0

  prev.forEach((id, index) => {
    if (movingSet.has(id)) {
      next[index] = moving[cursor++]
    }
  })

  setOrderIds($pinnedSessionIds, next)
}

export function bumpSessionsLimit(step: number = SIDEBAR_SESSIONS_PAGE_SIZE) {
  const safeStep = Math.max(1, Math.floor(step))
  $sessionsLimit.set($sessionsLimit.get() + safeStep)
}

/** Raise the window to at least `floor`, never shrinking it. Returns true when
 *  it moved, so the caller knows a refetch is worth it. */
export function raiseSessionsLimit(floor: number): boolean {
  if ($sessionsLimit.get() >= floor) {
    return false
  }

  $sessionsLimit.set(floor)

  return true
}

export function resetSessionsLimit() {
  if ($sessionsLimit.get() !== SIDEBAR_SESSIONS_PAGE_SIZE) {
    $sessionsLimit.set(SIDEBAR_SESSIONS_PAGE_SIZE)
  }
}

import { act } from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import * as notifications from '@/store/notifications'
import { makeOAuthProvider } from '@/test/oauth-provider'
import type { OAuthProvider } from '@/types/hermes'

import {
  $desktopOnboarding,
  completeDesktopOnboarding,
  type DesktopOnboardingState,
  type OnboardingContext,
  refreshOnboarding,
  requestDesktopOnboarding,
  resetBootRaceWindowForTests,
  saveOnboardingLocalEndpoint,
  setOnboardingModel,
  submitOnboardingCode
} from './onboarding'

function baseState(overrides: Partial<DesktopOnboardingState> = {}): DesktopOnboardingState {
  return {
    configured: false,
    flow: { status: 'idle' },
    mode: 'oauth',
    providers: null,
    reason: null,
    requested: false,
    firstRunSkipped: false,
    manual: false,
    localEndpoint: false,
    freeTierReady: false,
    ...overrides
  }
}

function installApiMock(api: (request: { path: string }) => Promise<unknown>) {
  Object.defineProperty(window, 'hermesDesktop', {
    configurable: true,
    value: { api }
  })
}

function emptyOpenRouterGateway(): OnboardingContext['requestGateway'] {
  return async method => {
    if (method === 'setup.status') {
      return { provider_configured: true } as never
    }

    if (method === 'setup.runtime_check') {
      return { error: 'No usable credentials found for openrouter.', ok: false, provider: 'openrouter' } as never
    }

    throw new Error(`unexpected gateway method: ${method}`)
  }
}

function keylessCustomGateway(): OnboardingContext['requestGateway'] {
  return async method => {
    if (method === 'setup.status') {
      return { provider_configured: true } as never
    }

    if (method === 'setup.runtime_check') {
      return { ok: true, provider: 'custom' } as never
    }

    throw new Error(`unexpected gateway method: ${method}`)
  }
}

function onboardingContext(requestGateway: OnboardingContext['requestGateway']): OnboardingContext {
  return { requestGateway }
}

function fallbackTimeoutGateway(): OnboardingContext['requestGateway'] {
  return async method => {
    if (method === 'setup.status' || method === 'setup.runtime_check') {
      throw new Error(`request timed out: ${method}`)
    }

    throw new Error(`unexpected gateway method: ${method}`)
  }
}

describe('refreshOnboarding', () => {
  it('keeps onboarding work in its initiating lifetime and profile', async () => {
    const { startManualOnboarding, startProviderOAuth, saveOnboardingApiKey, closeManualOnboarding } =
      await import('./onboarding')

    const requests: { path: string; profile?: string }[] = []
    let release!: () => void
    let delayKey = true
    installApiMock(async request => {
      requests.push(request)

      if (request.path === '/api/providers/oauth') {
        return { providers: [] }
      }

      if (request.path.endsWith('/start')) {
        return {
          flow: 'device_code',
          session_id: 'local-fixture',
          user_code: 'FAKE',
          verification_url: 'http://localhost/fixture',
          expires_in: 600
        }
      }

      if (request.path.includes('/poll/')) {
        return { status: 'approved' }
      }

      if (request.path === '/api/env' && delayKey) {
        await new Promise<void>(resolve => {
          release = resolve
        })
      }

      if (request.path.startsWith('/api/model/options')) {
        return { providers: [{ slug: 'fixture', name: 'Fixture', models: ['fixture-model'] }] }
      }

      if (request.path.startsWith('/api/model/recommended-default')) {
        return { model: 'fixture-model' }
      }

      return { ok: true }
    })
    vi.spyOn(window, 'open').mockReturnValue(null)
    let profile = 'beta'

    const ctx: OnboardingContext = {
      get profile() {
        return profile
      },
      requestGateway: async method =>
        (method === 'setup.status' ? { provider_configured: true } : { ok: true }) as never
    }

    try {
      startManualOnboarding(null, 'beta')
      const pending = saveOnboardingApiKey('FIREWORKS_API_KEY', 'fake-key', 'Fireworks', ctx)
      await vi.waitFor(() => expect(release).toBeTypeOf('function'))
      closeManualOnboarding()
      profile = 'alpha'
      startManualOnboarding(null, 'alpha')
      release()
      await pending
      expect(requests.some(r => r.path === '/api/model/set')).toBe(false)
      expect($desktopOnboarding.get()).toMatchObject({ targetScope: { profile: 'alpha' }, flow: { status: 'idle' } })
      closeManualOnboarding()
      delayKey = false
      profile = 'beta'
      startManualOnboarding(null, 'beta')
      const startAt = requests.length
      await startProviderOAuth(makeOAuthProvider('fixture'), ctx)
      await vi.waitFor(() => expect($desktopOnboarding.get().flow.status).toBe('confirming_model'), { timeout: 5000 })
      expect(requests.slice(startAt).some(r => r.path.includes('/poll/'))).toBe(true)
      expect(requests.slice(startAt).some(r => r.path === '/api/model/set')).toBe(true)
      expect(requests.slice(startAt).every(r => r.profile === 'beta')).toBe(true)
    } finally {
      closeManualOnboarding()
    }
  })

  beforeEach(() => {
    window.localStorage.clear()
    $desktopOnboarding.set(baseState())
  })

  afterEach(() => {
    window.localStorage.clear()
    $desktopOnboarding.set(baseState())
    resetBootRaceWindowForTests()
    vi.restoreAllMocks()
  })

  it('refreshes OAuth providers again when onboarding was explicitly requested', async () => {
    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return { providers: [makeOAuthProvider('fresh')] }
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    $desktopOnboarding.set(baseState({ providers: [makeOAuthProvider('cached')] }))
    requestDesktopOnboarding('Need provider setup')

    const ready = await refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

    expect(ready).toBe(false)
    expect(api).toHaveBeenCalledTimes(1)
    expect($desktopOnboarding.get().providers?.map(p => p.id)).toEqual(['fresh'])
    expect($desktopOnboarding.get().reason).toContain('No usable credentials found for openrouter.')
    expect($desktopOnboarding.get().reason).toContain('setup.status reports configured credentials')
  })

  it('keeps cached providers when onboarding was not re-requested', async () => {
    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return { providers: [makeOAuthProvider('fresh')] }
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    $desktopOnboarding.set(baseState({ providers: [makeOAuthProvider('cached')] }))

    const ready = await refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

    expect(ready).toBe(false)
    expect(api).not.toHaveBeenCalled()
    expect($desktopOnboarding.get().providers?.map(p => p.id)).toEqual(['cached'])
  })

  it('does not downgrade configured=true on fallback-only readiness failures', async () => {
    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return { providers: [makeOAuthProvider('fresh')] }
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    // Simulate a returning user: cache is set and store is configured.
    window.localStorage.setItem('hermes-desktop-onboarded-v1', '1')
    $desktopOnboarding.set(
      baseState({
        configured: true,
        providers: [makeOAuthProvider('cached')],
        reason: null,
        requested: false
      })
    )

    const ready = await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))

    expect(ready).toBe(false)
    expect(api).not.toHaveBeenCalled()
    expect($desktopOnboarding.get().configured).toBe(true)
    expect($desktopOnboarding.get().reason).toBeNull()
    // The cache must survive the refresh — proving we didn't downgrade.
    expect(window.localStorage.getItem('hermes-desktop-onboarded-v1')).toBe('1')
  })

  it('keeps an unknown readiness notice temporary and clears it on recovery (#124545)', async () => {
    vi.useFakeTimers()
    notifications.clearNotifications()
    installApiMock(vi.fn())
    $desktopOnboarding.set(baseState({ configured: true }))

    try {
      await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))
      expect(notifications.$notifications.get()).toEqual([
        expect.objectContaining({ id: 'runtime-not-ready', kind: 'info' })
      ])
      expect($desktopOnboarding.get().configured).toBe(true)
      await vi.advanceTimersByTimeAsync(5_000)
      expect(notifications.$notifications.get()).toEqual([])

      // A later outage can show a fresh notice; an authoritative ready clears it
      // without waiting for its timer, and must not dismiss unrelated errors.
      await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))
      notifications.notify({ id: 'unrelated', kind: 'error', message: 'Keep me' })
      await refreshOnboarding(onboardingContext(keylessCustomGateway()))
      expect(notifications.$notifications.get().map(item => item.id)).toEqual(['unrelated'])
    } finally {
      notifications.clearNotifications()
      vi.useRealTimers()
    }
  })

  it('leaves configured unknown on a boot fallback instead of erasing the cache', async () => {
    const notifySpy = vi.spyOn(notifications, 'notify')

    installApiMock(vi.fn())
    // Cold launch, no onboarded cache yet: `configured` is UNKNOWN, not false.
    // A round that loses the race to a cold/queued backend answers neither
    // probe, and recording that as "no provider" deleted the cache — which
    // re-armed the blocking first-run picker on every launch afterwards.
    $desktopOnboarding.set(baseState({ configured: null, providers: null, requested: false }))

    const ready = await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))

    expect(ready).toBe(false)
    expect($desktopOnboarding.get().configured).toBeNull()
    expect(window.localStorage.getItem('hermes-desktop-onboarded-v1')).toBeNull()
    // Nothing was ever verified, so there is no outage worth a toast.
    expect(notifySpy).not.toHaveBeenCalled()
  })

  it('does not downgrade a configured install when the boot race answers ok:false', async () => {
    const { notifySetupReady } = await import('@/store/live-sync')

    installApiMock(vi.fn())
    // Fully configured install (durable cache present), backend just booted:
    // setup.ready bumped the boot generation moments ago. The runtime_check
    // answers ok:false because the external secret source (BWS) has not
    // hydrated yet — a hydration race, not a credential verdict (#124939).
    window.localStorage.setItem('hermes-desktop-onboarded-v1', '1')
    $desktopOnboarding.set(baseState({ configured: true, providers: null, requested: false }))

    notifySetupReady()

    const ready = await refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

    expect(ready).toBe(false)
    expect($desktopOnboarding.get().configured).toBe(true)
    expect(window.localStorage.getItem('hermes-desktop-onboarded-v1')).toBe('1')
  })

  it('still downgrades when the same ok:false arrives long after boot', async () => {
    const { notifySetupReady } = await import('@/store/live-sync')

    installApiMock(vi.fn())
    window.localStorage.setItem('hermes-desktop-onboarded-v1', '1')
    $desktopOnboarding.set(baseState({ configured: true, providers: null, requested: false }))

    // Boot happened, then the grace window elapsed: an ok:false now is a real
    // verdict (the secret source had its chance), so onboarding must surface.
    notifySetupReady()
    const clock = vi.spyOn(Date, 'now').mockReturnValue(Date.now() + 60_000)

    try {
      const ready = await refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

      expect(ready).toBe(false)
      expect($desktopOnboarding.get().configured).toBe(false)
      expect(window.localStorage.getItem('hermes-desktop-onboarded-v1')).toBeNull()
    } finally {
      clock.mockRestore()
    }
  })

  it('keeps a persisted "choose later" when a passive round completes onboarding', () => {
    window.localStorage.setItem('hermes-onboarding-skipped-v1', '1')
    $desktopOnboarding.set(baseState({ configured: null, firstRunSkipped: true }))

    completeDesktopOnboarding()

    expect(window.localStorage.getItem('hermes-onboarding-skipped-v1')).toBe('1')
    expect($desktopOnboarding.get().firstRunSkipped).toBe(true)
  })

  it('clears the skip only when the user actually connected a provider', () => {
    window.localStorage.setItem('hermes-onboarding-skipped-v1', '1')
    $desktopOnboarding.set(baseState({ configured: null, firstRunSkipped: true }))

    completeDesktopOnboarding(true)

    expect(window.localStorage.getItem('hermes-onboarding-skipped-v1')).toBeNull()
    expect($desktopOnboarding.get().firstRunSkipped).toBe(false)
  })

  it('enters setup when the selected OpenRouter credential is genuinely empty', async () => {
    // Outside the boot window: no setup.ready bump precedes the round, so an
    // answered ok:false is a real verdict, not a hydration race.
    installApiMock(vi.fn())
    window.localStorage.setItem('hermes-desktop-onboarded-v1', '1')
    $desktopOnboarding.set(
      baseState({
        configured: true,
        providers: [makeOAuthProvider('cached')],
        reason: null,
        requested: false
      })
    )

    const ready = await refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

    expect(ready).toBe(false)
    expect($desktopOnboarding.get().configured).toBe(false)
    expect($desktopOnboarding.get().reason).toContain('No usable credentials found for openrouter.')
    expect(window.localStorage.getItem('hermes-desktop-onboarded-v1')).toBeNull()
  })

  it('keeps a keyless custom runtime out of setup', async () => {
    const api = vi.fn()

    installApiMock(api)
    $desktopOnboarding.set(baseState({ configured: false, reason: 'stale setup error', requested: true }))

    const ready = await refreshOnboarding(onboardingContext(keylessCustomGateway()))

    expect(ready).toBe(true)
    expect(api).not.toHaveBeenCalled()
    expect($desktopOnboarding.get()).toMatchObject({
      configured: true,
      reason: null,
      requested: false
    })
  })

  it('does not preserve configured when onboarding was explicitly requested', async () => {
    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return { providers: [makeOAuthProvider('fresh')] }
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    $desktopOnboarding.set(
      baseState({
        configured: true,
        providers: [makeOAuthProvider('cached')],
        reason: null,
        requested: true
      })
    )

    const ready = await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))

    expect(ready).toBe(false)
    // requested overrides preservation — should downgrade.
    expect($desktopOnboarding.get().configured).toBe(false)
    expect(api).toHaveBeenCalledTimes(1)
  })

  it('still surfaces onboarding when fallback failure happens before configured state', async () => {
    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return { providers: [makeOAuthProvider('fresh')] }
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    $desktopOnboarding.set(baseState({ configured: false, providers: null, requested: true }))

    const ready = await refreshOnboarding(onboardingContext(fallbackTimeoutGateway()))

    expect(ready).toBe(false)
    expect(api).toHaveBeenCalledTimes(1)
    expect($desktopOnboarding.get().configured).toBe(false)
    expect($desktopOnboarding.get().reason).toContain('request timed out')
  })

  it('deduplicates concurrent provider refresh calls', async () => {
    let resolveProviders!: (value: { providers: OAuthProvider[] }) => void

    const providersPromise = new Promise<{ providers: OAuthProvider[] }>(resolve => {
      resolveProviders = value => {
        resolve(value)
      }
    })

    const api = vi.fn(async ({ path }: { path: string }) => {
      if (path === '/api/providers/oauth') {
        return providersPromise
      }

      throw new Error(`unexpected api path: ${path}`)
    })

    installApiMock(api)
    $desktopOnboarding.set(baseState({ requested: true }))

    const first = refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))
    const second = refreshOnboarding(onboardingContext(emptyOpenRouterGateway()))

    await vi.waitFor(() => expect(api).toHaveBeenCalledTimes(1))

    resolveProviders({ providers: [makeOAuthProvider('shared')] })
    await Promise.all([first, second])

    expect($desktopOnboarding.get().providers?.map(p => p.id)).toEqual(['shared'])
  })
})

